window.FO_PACKS=window.FO_PACKS||{};window.FO_PACKS["KS2"]={"KS2-001":{"objectives":["Kendini ve adını İngilizce tanıtmak","'I like…' ile hobilerini anlatmak","Bir arkadaşına 'Do you like…?' diye sormak"],"dialogues":[{"title":"Hi, I'm Ela","setting":"Okulun ilk gününde Ela, yeni arkadaşı Kaan'a kendini tanıtıyor.","lines":[{"s":"Ela","en":"Hi! I'm Ela. What's your name?","tr":"Merhaba! Ben Ela. Senin adın ne?"},{"s":"Kaan","en":"Hi, Ela. I'm Kaan. I'm ten.","tr":"Merhaba Ela. Ben Kaan. On yaşındayım."},{"s":"Ela","en":"Nice to meet you, Kaan!","tr":"Tanıştığımıza memnun oldum, Kaan!"},{"s":"Kaan","en":"Nice to meet you too. Do you like sports?","tr":"Ben de tanıştığıma memnun oldum. Spor yapmayı sever misin?"},{"s":"Ela","en":"Yes, I like swimming. I can swim very fast!","tr":"Evet, yüzmeyi severim. Çok hızlı yüzebilirim!"},{"s":"Kaan","en":"Wow! I like football.","tr":"Vay! Ben futbolu severim."}]},{"title":"My hobbies","setting":"Teneffüste Ela ve Deniz hobilerini karşılaştırıyor.","lines":[{"s":"Deniz","en":"What do you like to do, Ela?","tr":"Ela, ne yapmayı seversin?"},{"s":"Ela","en":"I like drawing. I draw cats and birds.","tr":"Resim yapmayı severim. Kediler ve kuşlar çizerim."},{"s":"Deniz","en":"Do you like music too?","tr":"Müziği de sever misin?"},{"s":"Ela","en":"Yes! I like playing the piano. It's fun.","tr":"Evet! Piyano çalmayı severim. Çok eğlenceli."},{"s":"Deniz","en":"I like reading books. My favourite book is about a dragon.","tr":"Ben kitap okumayı severim. En sevdiğim kitap bir ejderha hakkında."},{"s":"Ela","en":"Cool! Can I read it after you?","tr":"Harika! Sen okuduktan sonra ben de okuyabilir miyim?"}]},{"title":"Hobby time","setting":"Sınıfta öğretmen Bay Can, öğrencilerin hobilerini soruyor.","lines":[{"s":"Teacher","en":"Class, can you say one hobby in English?","tr":"Sınıf, İngilizce bir hobinizi söyleyebilir misiniz?"},{"s":"Mina","en":"I like dancing!","tr":"Dans etmeyi severim!"},{"s":"Teacher","en":"Great, Mina. Who likes cooking?","tr":"Harika, Mina. Yemek yapmayı kim sever?"},{"s":"Kaan","en":"I like cooking with my mum. I can make pancakes.","tr":"Annemle yemek yapmayı severim. Pankek yapabilirim."},{"s":"Teacher","en":"Yummy! Ela, do you like dancing too?","tr":"Harika görünüyor! Ela, sen de dans etmeyi sever misin?"},{"s":"Ela","en":"No, I don't. I like drawing better.","tr":"Hayır, sevmem. Resim yapmayı daha çok severim."}]}],"reading":{"title":"Ela's hobbies","paras":[{"en":"Hi! My name is Ela. I am ten years old. I like drawing, swimming and music. I can swim very fast! My favourite hobby is drawing cats. What do you like? Tell me about your hobbies! I go to the pool on Monday and Friday with my dad. We swim for one hour. After that, I draw in my room with my little cat, Pamuk.","tr":"Merhaba! Benim adım Ela. On yaşındayım. Resim yapmayı, yüzmeyi ve müziği severim. Çok hızlı yüzebilirim! En sevdiğim hobi kedi çizmek. Sen neyi seversin? Hobilerini bana anlat! Pazartesi ve cuma günleri babamla havuza giderim. Bir saat yüzeriz. Ondan sonra odamda küçük kedim Pamuk ile resim yaparım."}]},"vocab":[{"w":"hobby","ipa":"/ˈhɒbi/","pos":"🎯","tr":"hobi","ex":"My favourite hobby is drawing.","exTr":"En sevdiğim hobi resim yapmak."},{"w":"swim","ipa":"/swɪm/","pos":"🏊","tr":"yüzmek","ex":"I can swim very fast.","exTr":"Çok hızlı yüzebilirim."},{"w":"draw","ipa":"/drɔː/","pos":"✏️","tr":"resim yapmak, çizmek","ex":"I draw cats and birds.","exTr":"Kediler ve kuşlar çizerim."},{"w":"piano","ipa":"/piˈænəʊ/","pos":"🎹","tr":"piyano","ex":"I like playing the piano.","exTr":"Piyano çalmayı severim."},{"w":"music","ipa":"/ˈmjuːzɪk/","pos":"🎵","tr":"müzik","ex":"Do you like music?","exTr":"Müziği sever misin?"},{"w":"dancing","ipa":"/ˈdɑːnsɪŋ/","pos":"💃","tr":"dans etme","ex":"I like dancing!","exTr":"Dans etmeyi severim!"},{"w":"cooking","ipa":"/ˈkʊkɪŋ/","pos":"🍳","tr":"yemek yapma","ex":"I like cooking with my mum.","exTr":"Annemle yemek yapmayı severim."},{"w":"book","ipa":"/bʊk/","pos":"📚","tr":"kitap","ex":"My favourite book is about a dragon.","exTr":"En sevdiğim kitap bir ejderha hakkında."}],"chunks":[{"en":"What's your name?","tr":"Senin adın ne?"},{"en":"Nice to meet you!","tr":"Tanıştığımıza memnun oldum!"},{"en":"I like drawing.","tr":"Resim yapmayı severim."},{"en":"Do you like music?","tr":"Müziği sever misin?"}],"grammar":{"point":"I like + -ing","tr":"'I like' kalıbından sonra bir fiil gelirse, fiilin sonuna '-ing' eklenir. Örneğin 'swim' fiili 'swimming' olur ve 'yüzmeyi severim' anlamına gelir. Bu kalıp hobilerden söz ederken çok işe yarar.","examples":["I like swimming.","I like reading books.","She likes dancing.","Do you like cooking?"]},"questions":[{"q":"What is Ela's favourite hobby?","a":"Drawing cats."},{"q":"When does Ela go to the pool?","a":"On Monday and Friday."},{"q":"What is Ela's cat called?","a":"Pamuk."}],"quiz":[{"q":"'I like ___.' (🏊)","o":["swim","swimming","swims"],"a":1,"why":"'Like' den sonra fiilin sonuna -ing gelir."},{"q":"A 'hobby' is something you do…","o":["for fun","at school","to eat"],"a":0,"why":""},{"q":"Which picture means 'book'? (📚)","o":["bike","bag","book"],"a":2,"why":""},{"q":"Ela ___ drawing.","o":["like","likes","liking"],"a":1,"why":"Ela tek kişi olduğu için 'likes' kullanılır."}],"drills":[{"type":"Yerine koyma","prompt":"I like swimming.","cue":"drawing","answer":"I like drawing."},{"type":"Dönüştürme","prompt":"I like music.","cue":"Make a question with 'Do you…?'","answer":"Do you like music?"},{"type":"Genişletme","prompt":"I like football.","cue":"+ on Sundays","answer":"I like football on Sundays."}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Kısa /ɪ/ gevşek ve kısa söylenir. Uzun /iː/ ise dilini öne doğru gerip sesi uzatırsın. Türkçede bu fark yoktur, bu yüzden 'ship' ve 'sheep' birbirine karışabilir.","pairs":["ship / sheep","fit / feet","bit / beat"]}],"mission":{"brief":"Ela'yı tanıdın! Şimdi Claude, yeni sınıf arkadaşın Leo'yu canlandıracak. Ona kendini tanıt ve en az üç hobini 'I like…' ile anlat.","persona":"Leo, a friendly 10-year-old new classmate. Uses very short sentences and cheers the learner on. Asks only one question at a time. Hidden fact: Leo loves cycling, but he is a little afraid of falling. He tells this only if the learner asks what he likes doing at weekends and why.","goal":"En az üç hobini 'I like…' ile söyle.","opener":"Hi! I'm Leo. What do you like to do?"}},"KS2-002":{"objectives":["Okul gününü basit cümlelerle anlatmak","'I go / I have / I play' kalıplarını kullanmak","Teneffüs ve okul eşyalarıyla ilgili kelimeleri öğrenmek"],"dialogues":[{"title":"The school bus","setting":"Sabah, Ela ile arkadaşı Deniz otobüs durağında buluşuyor.","lines":[{"s":"Ela","en":"Good morning, Deniz! Are you ready for school?","tr":"Günaydın Deniz! Okula hazır mısın?"},{"s":"Deniz","en":"Yes! I have my bag and my lunch.","tr":"Evet! Çantam ve öğle yemeğim var."},{"s":"Ela","en":"Great. The bus is here!","tr":"Harika. Otobüs geldi!"},{"s":"Deniz","en":"I love my school bus. It's yellow!","tr":"Okul otobüsümü çok severim. Sarı!"},{"s":"Ela","en":"Let's go. I have a maths test today.","tr":"Hadi gidelim. Bugün matematik sınavım var."},{"s":"Deniz","en":"Good luck!","tr":"Bol şans!"}]},{"title":"Break time","setting":"Okulda teneffüs. Ali, öğretmeni Mr Kaya ile konuşuyor.","lines":[{"s":"Ali","en":"It's break time! Do you want to play?","tr":"Teneffüs zamanı! Oynamak ister misin?"},{"s":"Mr Kaya","en":"Ali, first finish your homework, please.","tr":"Ali, önce ödevini bitir lütfen."},{"s":"Ali","en":"OK, teacher. Sorry!","tr":"Tamam, öğretmenim. Özür dilerim!"},{"s":"Mr Kaya","en":"Good. Thank you.","tr":"Güzel. Teşekkürler."},{"s":"Ali","en":"Then lunch! I am so hungry.","tr":"Sonra öğle yemeği! Çok acıktım."},{"s":"Mr Kaya","en":"Eat your lunch in the classroom, please.","tr":"Öğle yemeğini lütfen sınıfta ye."}]},{"title":"After school","setting":"Okul çıkışı, Ela annesine okul gününü anlatıyor.","lines":[{"s":"Mum","en":"How was school, Ela?","tr":"Okul nasıldı, Ela?"},{"s":"Ela","en":"It was good! I read a book at break.","tr":"Güzeldi! Teneffüste bir kitap okudum."},{"s":"Mum","en":"Nice. Do you have homework?","tr":"Güzel. Ödevin var mı?"},{"s":"Ela","en":"Yes, one page of maths.","tr":"Evet, matematikten bir sayfa."},{"s":"Mum","en":"Then do it after your snack.","tr":"O zaman atıştırmalığını yedikten sonra yap."},{"s":"Ela","en":"OK, Mum. Then I can play.","tr":"Tamam anne. Sonra oynayabilirim."}]}],"reading":{"title":"Ela's school day","paras":[{"en":"My name is Ela. I go to school by bus. My school starts at eight thirty. In the morning I have maths and English. At lunch I eat with my friends in the canteen. My favourite lesson is art. After school I do my homework and then I play in the park.","tr":"Benim adım Ela. Okula otobüsle giderim. Okulum sekiz buçukta başlar. Sabahları matematik ve İngilizce dersim var. Öğle yemeğinde arkadaşlarımla kantinde yemek yerim. En sevdiğim ders resim. Okuldan sonra ödevimi yaparım, sonra parkta oynarım."}]},"vocab":[{"w":"school","ipa":"/skuːl/","pos":"🏫","tr":"okul","ex":"I go to school by bus.","exTr":"Okula otobüsle giderim."},{"w":"bus","ipa":"/bʌs/","pos":"🚌","tr":"otobüs","ex":"The bus is yellow.","exTr":"Otobüs sarı."},{"w":"bag","ipa":"/bæɡ/","pos":"🎒","tr":"çanta","ex":"My bag is red.","exTr":"Çantam kırmızı."},{"w":"lunch","ipa":"/lʌntʃ/","pos":"🥪","tr":"öğle yemeği","ex":"I eat my lunch at school.","exTr":"Öğle yemeğimi okulda yerim."},{"w":"homework","ipa":"/ˈhəʊmwɜːk/","pos":"📝","tr":"ev ödevi","ex":"I do my homework after school.","exTr":"Ödevimi okuldan sonra yaparım."},{"w":"break","ipa":"/breɪk/","pos":"🔔","tr":"teneffüs","ex":"We play at break.","exTr":"Teneffüste oynarız."},{"w":"teacher","ipa":"/ˈtiːtʃə/","pos":"👩‍🏫","tr":"öğretmen","ex":"My teacher is very kind.","exTr":"Öğretmenim çok nazik."},{"w":"book","ipa":"/bʊk/","pos":"📖","tr":"kitap","ex":"I read a book.","exTr":"Bir kitap okurum."}],"chunks":[{"en":"Are you ready?","tr":"Hazır mısın?"},{"en":"It's break time!","tr":"Teneffüs zamanı!"},{"en":"Good luck!","tr":"Bol şans!"},{"en":"Thank you, teacher.","tr":"Teşekkürler, öğretmenim."}],"grammar":{"point":"I + simple verb","tr":"Her gün yaptığımız şeyleri anlatırken 'I' ile fiil hep aynı kalır: I go, I have, I play. Bu yüzden fiile -s eklemeyiz.","examples":["I go to school by bus.","I have a red bag.","I play in the park.","I read a book at break."]},"questions":[{"q":"How does Ela go to school?","a":"By bus."},{"q":"What time does Ela's school start?","a":"At half past eight."},{"q":"What is Ela's favourite lesson?","a":"Art."}],"quiz":[{"q":"I go to school ___ bus.","o":["in","on","by"],"a":2,"why":"'By bus' otobüsle demektir."},{"q":"🎒 is a ___.","o":["bag","bus","book"],"a":0,"why":""},{"q":"Ela reads a ___ at break.","o":["bus","book","lunch"],"a":1,"why":""},{"q":"Which word means 'öğretmen'?","o":["homework","break","teacher"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I go to school by bus.","cue":"car","answer":"I go to school by car."},{"type":"Soru yap","prompt":"I have a book.","cue":"Soru yap (you)","answer":"Do you have a book?"},{"type":"Genişletme","prompt":"I eat my lunch.","cue":"+ at school","answer":"I eat my lunch at school."}],"sounds":[{"focus":"/æ/ – /ʌ/","tr":"/æ/ için ağzını geniş aç, dilini aşağı indir ve 'e' ile 'a' arası bir ses çıkar. /ʌ/ ise daha kısa ve ağzı az açık bir 'a' sesidir.","pairs":["bag / bug","cap / cup","bat / but"]}],"mission":{"brief":"Oyun: Okul gününü İngilizce anlat; otobüse nasıl bindiğini, derste ne yaptığını ve teneffüste neler yaptığını söyle. Claude, yeni arkadaşın Leo olacak ve sana sorular soracak.","persona":"Leo, a friendly 10-year-old who just joined the school. Uses short, simple sentences and encourages the learner. Asks one question at a time. Hidden fact: he is nervous about his first maths test on Friday, and he only admits it if asked how he feels about maths or about his day.","goal":"Okul gününü üç cümleyle anlat ve Leo'ya bir soru sor.","opener":"Hi! I'm new here. What do you do at break time?"}},"KS2-003":{"objectives":["Okul derslerinin adlarını söylemek","'Do you like…?' sorusunu sorup cevaplamak","Ders programı hakkında kısa konuşmalar yapmak"],"dialogues":[{"title":"Favourite subjects","setting":"Sınıfta, Can ve arkadaşı Selin ders programına bakıyor.","lines":[{"s":"Selin","en":"What lesson do we have first?","tr":"İlk hangi ders var?"},{"s":"Can","en":"Maths! I don't like maths very much.","tr":"Matematik! Matematiği pek sevmem."},{"s":"Selin","en":"Really? I love science. It's fun!","tr":"Gerçekten mi? Ben fen bilgisini çok severim. Çok eğlenceli!"},{"s":"Can","en":"What about you? Do you like art?","tr":"Peki ya sen? Resmi sever misin?"},{"s":"Selin","en":"Art! I like painting pictures.","tr":"Resim! Resim yapmayı severim."},{"s":"Can","en":"Me too! Art is my favourite, too.","tr":"Ben de! Resim benim de en sevdiğim ders."}]},{"title":"The timetable","setting":"Mrs Demir, bugünkü ders programını tahtaya yazıyor.","lines":[{"s":"Mrs Demir","en":"Good morning, class! Today we have music first.","tr":"Günaydın sınıf! Bugün ilk derste müzik var."},{"s":"Ali","en":"Yay! I love music!","tr":"Yaşasın! Müziği çok seviyorum!"},{"s":"Mrs Demir","en":"Then we have geography after break.","tr":"Teneffüsten sonra da coğrafya var."},{"s":"Ali","en":"Where is the world map?","tr":"Dünya haritası nerede?"},{"s":"Mrs Demir","en":"It's on the wall, next to the door.","tr":"Duvarda, kapının yanında."},{"s":"Ali","en":"Thank you, Mrs Demir!","tr":"Teşekkürler, Mrs Demir!"}]},{"title":"PE lesson","setting":"Okul bahçesinde, Ece beden eğitimi öğretmeni Mr Yıldız ile konuşuyor.","lines":[{"s":"Ece","en":"Excuse me, Mr Yıldız. Is it PE today?","tr":"Affedersiniz Bay Yıldız. Bugün beden eğitimi var mı?"},{"s":"Mr Yıldız","en":"Yes, Ece! Bring your trainers.","tr":"Evet Ece! Spor ayakkabılarını getir."},{"s":"Ece","en":"OK. Do we play football?","tr":"Tamam. Futbol oynayacak mıyız?"},{"s":"Mr Yıldız","en":"Yes, and then we do a short run.","tr":"Evet, sonra da kısa bir koşu yapacağız."},{"s":"Ece","en":"Great! PE is my favourite lesson.","tr":"Harika! Beden eğitimi en sevdiğim ders."}]}],"reading":{"title":"Our school subjects","paras":[{"en":"Our school has many lessons. On Monday we have maths, English and science. On Tuesday we have art and music. Geography is my favourite lesson because I like maps. History is a bit hard, but it is interesting. On Friday we have PE in the big garden. I like running and football!","tr":"Okulumuzda birçok ders var. Pazartesi günü matematik, İngilizce ve fen bilgisi dersimiz var. Salı günü resim ve müzik var. Coğrafya en sevdiğim ders, çünkü haritaları severim. Tarih biraz zor ama ilginç. Cuma günü büyük bahçede beden eğitimi var. Koşmayı ve futbolu çok severim!"}]},"vocab":[{"w":"maths","ipa":"/mæθs/","pos":"🔢","tr":"matematik","ex":"We have maths on Monday.","exTr":"Pazartesi matematiğimiz var."},{"w":"science","ipa":"/ˈsaɪəns/","pos":"🔬","tr":"fen bilgisi","ex":"I love science.","exTr":"Fen bilgisini çok severim."},{"w":"art","ipa":"/ɑːt/","pos":"🎨","tr":"resim","ex":"Art is fun.","exTr":"Resim eğlencelidir."},{"w":"music","ipa":"/ˈmjuːzɪk/","pos":"🎵","tr":"müzik","ex":"We sing in music.","exTr":"Müzik dersinde şarkı söyleriz."},{"w":"geography","ipa":"/dʒiˈɒɡrəfi/","pos":"🌍","tr":"coğrafya","ex":"Geography is about maps.","exTr":"Coğrafya haritalarla ilgilidir."},{"w":"history","ipa":"/ˈhɪstri/","pos":"📜","tr":"tarih","ex":"History is about the past.","exTr":"Tarih geçmişle ilgilidir."},{"w":"PE","ipa":"/ˌpiː ˈiː/","pos":"🏃","tr":"beden eğitimi","ex":"We run in PE.","exTr":"Beden eğitiminde koşarız."},{"w":"English","ipa":"/ˈɪŋɡlɪʃ/","pos":"🔤","tr":"İngilizce","ex":"I speak English.","exTr":"İngilizce konuşurum."}],"chunks":[{"en":"What lesson do we have first?","tr":"İlk hangi ders var?"},{"en":"I love science!","tr":"Fen bilgisini çok severim!"},{"en":"Bring your trainers.","tr":"Spor ayakkabılarını getir."},{"en":"Thank you, Mrs Demir!","tr":"Teşekkürler, Mrs Demir!"}],"grammar":{"point":"Do you like…? questions","tr":"'Do you like…?' sorusu 'Sen … sever misin?' anlamına gelir. Cevapta 'Yes, I do' ya da 'No, I don't' deriz. 'He' ve 'she' için soru 'Does … like?' olur.","examples":["Do you like art?","Yes, I do.","Does Can like music?","No, he doesn't."]},"questions":[{"q":"Which lesson does Selin love?","a":"Science."},{"q":"What lesson comes after break in Mrs Demir's class?","a":"Geography."},{"q":"What must Ece bring to PE?","a":"Her trainers."}],"quiz":[{"q":"Which lesson is about maps and countries?","o":["history","geography","music"],"a":1,"why":"Coğrafya haritalar ve ülkelerle ilgilidir."},{"q":"I ___ science.","o":["love","loves","lovely"],"a":0,"why":""},{"q":"What do you bring to PE?","o":["a map","a book","trainers"],"a":2,"why":""},{"q":"Which word means 'matematik'?","o":["science","maths","history"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I love science.","cue":"art","answer":"I love art."},{"type":"Soru yap","prompt":"I like music.","cue":"Soru yap (you)","answer":"Do you like music?"},{"type":"Genişletme","prompt":"Geography is interesting.","cue":"+ very","answer":"Geography is very interesting."}],"sounds":[{"focus":"/ɑː/ – /æ/","tr":"Uzun /ɑː/ için ağzını geniş aç ve sesi uzat. Kısa /æ/ ise dilini aşağıda tutarak 'e' ile 'a' arası kısa bir ses çıkarmaktır.","pairs":["art / at","car / cat","far / fat"]}],"mission":{"brief":"Oyun: Okul ders programını İngilizce anlat ve en sevdiğin dersi söyle. Claude, yeni sınıf arkadaşın Lily olacak ve sana sorular soracak.","persona":"Lily, a shy 10-year-old classmate. Speaks in short, simple sentences and asks one question at a time. Hidden fact: she dislikes PE because she is afraid of running, and she only admits it if asked how she feels about PE.","goal":"Üç ders adını İngilizce söyle ve Lily'ye en sevdiği dersi sor.","opener":"Hi! I'm new in class. Which lessons do you like?"}},"KS2-004":{"objectives":["Saati İngilizce söylemek","'It's half past…' ve 'o'clock' kalıplarını kullanmak","Bir buluşma saati üzerinde anlaşmak"],"dialogues":[{"title":"Running late","setting":"Sabah, Ela babasıyla okula gitmek için hazırlanıyor.","lines":[{"s":"Ela","en":"Dad, what time is it?","tr":"Baba, saat kaç?"},{"s":"Dad","en":"It's half past seven. Hurry up!","tr":"Yedi buçuk. Acele et!"},{"s":"Ela","en":"Oh no! School starts at eight.","tr":"Ay hayır! Okul sekizde başlıyor."},{"s":"Dad","en":"Don't worry. We have half an hour.","tr":"Endişelenme. Yarım saatimiz var."},{"s":"Ela","en":"Let's go! Look, I have my watch.","tr":"Hadi gidelim! Bak, kol saatim var."},{"s":"Dad","en":"Nice watch! Let's go.","tr":"Güzel saat! Hadi, yola çıkalım."}]},{"title":"Meeting at the park","setting":"Hafta sonu, Can ve Selin parkta buluşmayı planlıyor.","lines":[{"s":"Can","en":"Let's meet at three o'clock at the park.","tr":"Parkta saat üçte buluşalım."},{"s":"Selin","en":"Three o'clock? Or a quarter past three?","tr":"Üçte mi? Yoksa üçü çeyrek geçe mi?"},{"s":"Can","en":"No, it's three o'clock exactly. Look at the clock.","tr":"Hayır, tam üçte. Saate bak."},{"s":"Selin","en":"OK! I'll bring the ball.","tr":"Tamam! Topu ben getireyim."},{"s":"Can","en":"Great. See you at three.","tr":"Harika. Üçte görüşürüz."},{"s":"Selin","en":"See you! Don't be late!","tr":"Görüşürüz! Geç kalma!"}]},{"title":"Lunch and art","setting":"Okulda, Miss Ayla saatin kaç olduğunu sınıfa soruyor.","lines":[{"s":"Miss Ayla","en":"Class, what time is it now?","tr":"Sınıf, şimdi saat kaç?"},{"s":"Ali","en":"It's twelve o'clock! Lunch time!","tr":"Saat on iki! Öğle yemeği zamanı!"},{"s":"Miss Ayla","en":"Yes! Lunch is at twelve. Then we have art.","tr":"Evet! Öğle yemeği on ikide. Sonra resim dersi var."},{"s":"Zeynep","en":"What time is art?","tr":"Resim saat kaçta?"},{"s":"Miss Ayla","en":"Art is at half past one.","tr":"Resim, bir buçukta."},{"s":"Ali","en":"Half past one, OK!","tr":"Bir buçuk, tamam!"}]}],"reading":{"title":"Telling the time","paras":[{"en":"We use a clock to know the time. The short hand shows the hour. The long hand shows the minutes. When the long hand is on twelve, it is o'clock. When it is on six, it is half past. Quarter past means fifteen minutes after the hour, and quarter to means fifteen minutes before the next hour. Look at the clock every day!","tr":"Saati öğrenmek için saat kullanırız. Kısa akrep saati gösterir. Uzun akrep dakikaları gösterir. Uzun akrep on ikideyse, tam saattir. Altıdaysa, buçuk demektir. 'Quarter past' bir saat başından on beş dakika sonrasını, 'quarter to' ise bir sonraki saate on beş dakika kala demektir. Her gün saate bak!"}]},"vocab":[{"w":"clock","ipa":"/klɒk/","pos":"🕐","tr":"saat (duvar saati)","ex":"The clock is on the wall.","exTr":"Saat duvarda."},{"w":"hour","ipa":"/ˈaʊə/","pos":"🕒","tr":"saat (zaman birimi)","ex":"An hour has sixty minutes.","exTr":"Bir saatte altmış dakika vardır."},{"w":"minute","ipa":"/ˈmɪnɪt/","pos":"⏱","tr":"dakika","ex":"Wait a minute!","exTr":"Bir dakika bekle!"},{"w":"half past","ipa":"/hɑːf pɑːst/","pos":"🕧","tr":"buçuk","ex":"It's half past seven.","exTr":"Yedi buçuk."},{"w":"quarter","ipa":"/ˈkwɔːtə/","pos":"🕓","tr":"çeyrek","ex":"A quarter is fifteen minutes.","exTr":"Çeyrek, on beş dakikadır."},{"w":"o'clock","ipa":"/əˈklɒk/","pos":"🕘","tr":"tam saat","ex":"It's nine o'clock.","exTr":"Saat dokuz."},{"w":"watch","ipa":"/wɒtʃ/","pos":"⌚","tr":"kol saati","ex":"I have a new watch.","exTr":"Yeni bir kol saatim var."},{"w":"time","ipa":"/taɪm/","pos":"⏰","tr":"zaman, saat","ex":"What time is it?","exTr":"Saat kaç?"}],"chunks":[{"en":"What time is it?","tr":"Saat kaç?"},{"en":"It's half past seven.","tr":"Yedi buçuk."},{"en":"Don't be late!","tr":"Geç kalma!"},{"en":"Look at the clock.","tr":"Saate bak."}],"grammar":{"point":"Telling the time: It's…","tr":"Saati söylerken cümleyi 'It's' ile başlatırız: It's three o'clock. Yarım saat için 'half past', çeyrek için 'quarter past' ya da 'quarter to' kullanılır.","examples":["It's three o'clock.","It's half past seven.","It's a quarter past nine.","What time is it? It's twelve o'clock."]},"questions":[{"q":"What time does Ela's school start?","a":"At eight o'clock."},{"q":"What time do Can and Selin plan to meet?","a":"At three o'clock."},{"q":"When is art class?","a":"At half past one."}],"quiz":[{"q":"The clock shows 3. It's ___ o'clock.","o":["half","nine","three"],"a":2,"why":""},{"q":"It's 7:30. It's half past ___.","o":["six","seven","eight"],"a":1,"why":""},{"q":"The ___ hand shows the hour.","o":["long","fast","short"],"a":2,"why":"Kısa akrep saati gösterir."},{"q":"Which word means 'dakika'?","o":["minute","hour","quarter"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"It's half past seven.","cue":"nine","answer":"It's half past nine."},{"type":"Soru yap","prompt":"It's half past seven.","cue":"Ask: What time…?","answer":"What time is it?"},{"type":"Genişletme","prompt":"Look at the clock.","cue":"+ every day","answer":"Look at the clock every day."}],"sounds":[{"focus":"/θ/","tr":"Dilinin ucunu üst dişlerinin arasına koy ve hafifçe üfle. 'T', 'd' ya da 's' gibi değil; dil dişlerin arasında kalmalı.","pairs":["three / tree","thirty / dirty","thin / tin"]}],"mission":{"brief":"Oyun: Arkadaşınla bir buluşma saati ayarla ve saati İngilizce söyle. Claude, yeni arkadaşın Mia olacak ve sana zamanla ilgili sorular soracak.","persona":"Mia, a 10-year-old classmate who often gets confused about time. Uses short, simple sentences and asks one question at a time. Hidden fact: she has a piano lesson at quarter to five every Tuesday, and she only mentions it if asked what she does on Tuesdays.","goal":"Üç farklı saati İngilizce söyle ve bir buluşma saati üzerinde Mia ile anlaş.","opener":"Hi! Can we meet after school? What time do you finish?"}},"KS2-005":{"objectives":["Yaptığım sporları İngilizce söylemek","'play' ve 'go' fiillerini spor adlarıyla doğru kullanmak","Hangi sporu, ne zaman yaptığımı anlatmak"],"dialogues":[{"title":"Which sport?","setting":"Okul bahçesinde Ali ve Zeynep hangi sporu yaptıklarını konuşuyor.","lines":[{"s":"Ali","en":"Do you play any sports, Zeynep?","tr":"Hiç spor yapıyor musun, Zeynep?"},{"s":"Zeynep","en":"Yes! I play tennis on Saturdays.","tr":"Evet! Cumartesileri tenis oynarım."},{"s":"Ali","en":"Cool! I play football with my team.","tr":"Harika! Takımımla futbol oynarım."},{"s":"Zeynep","en":"Do you score many goals?","tr":"Çok gol atıyor musun?"},{"s":"Ali","en":"Sometimes! I'm a good goalkeeper, too.","tr":"Bazen! Ben de iyi bir kaleciyim."},{"s":"Zeynep","en":"Let's play at break!","tr":"Teneffüste oynayalım!"}]},{"title":"Swimming lesson","setting":"Yüzme kursunda antrenör Mr Ahmet öğrencilerine konuşuyor.","lines":[{"s":"Mr Ahmet","en":"Good morning, swimmers! Today we swim fifty metres.","tr":"Günaydın yüzücüler! Bugün elli metre yüzeceğiz."},{"s":"Leo","en":"I can swim twenty metres. Is that good?","tr":"Yirmi metre yüzebiliyorum. Bu iyi mi?"},{"s":"Mr Ahmet","en":"That's great, Leo! You're getting better every week.","tr":"Harika Leo! Her hafta daha iyi oluyorsun."},{"s":"Leo","en":"Thank you! I love swimming.","tr":"Teşekkürler! Yüzmeyi çok seviyorum."},{"s":"Mr Ahmet","en":"Then let's start. One, two, three, go!","tr":"O zaman başlayalım. Bir, iki, üç, hadi!"}]},{"title":"Sports day teams","setting":"Spor günü için sınıfta takımlar kuruluyor. Öğretmen Ms Kaya listeyi yapıyor.","lines":[{"s":"Ms Kaya","en":"Who wants to be in the basketball team?","tr":"Kim basketbol takımında olmak ister?"},{"s":"Deniz","en":"I do! I'm tall, so I can jump high.","tr":"Ben! Uzunum, o yüzden yüksek zıplayabilirim."},{"s":"Ms Kaya","en":"Great! And who wants to do cycling?","tr":"Harika! Peki bisiklete kim binmek ister?"},{"s":"Ece","en":"I'd like to. Can I bring my own bike?","tr":"Ben isterim. Kendi bisikletimi getirebilir miyim?"},{"s":"Ms Kaya","en":"Yes, bring it on Friday. Team captains, please come here.","tr":"Evet, cuma günü getir. Takım kaptanları, lütfen buraya gelin."}]}],"reading":{"title":"My two sports","paras":[{"en":"I play two sports. On Monday and Thursday I play football with my team at school. We wear blue shirts. I am a defender, so I try to stop the other team from scoring a goal. On weekends I go swimming with my dad. He says I swim like a fish! I like cycling, too, but only in the park.","tr":"İki spor yapıyorum. Pazartesi ve perşembe okulda takımımla futbol oynarım. Mavi formalar giyeriz. Savunmacıyım, bu yüzden diğer takımın gol atmasını engellemeye çalışırım. Hafta sonları babamla yüzmeye giderim. Babam balık gibi yüzdüğümü söyler! Bisiklet sürmeyi de severim, ama sadece parkta."}]},"vocab":[{"w":"football","ipa":"/ˈfʊtbɔːl/","pos":"⚽","tr":"futbol","ex":"I play football on Monday.","exTr":"Pazartesi futbol oynarım."},{"w":"basketball","ipa":"/ˈbɑːskɪtbɔːl/","pos":"🏀","tr":"basketbol","ex":"Basketball is fun.","exTr":"Basketbol eğlencelidir."},{"w":"swimming","ipa":"/ˈswɪmɪŋ/","pos":"🏊","tr":"yüzme","ex":"I go swimming on Sundays.","exTr":"Pazar günleri yüzmeye giderim."},{"w":"tennis","ipa":"/ˈtenɪs/","pos":"🎾","tr":"tenis","ex":"She plays tennis.","exTr":"O tenis oynar."},{"w":"cycling","ipa":"/ˈsaɪklɪŋ/","pos":"🚴","tr":"bisiklet sürme","ex":"I like cycling in the park.","exTr":"Parkta bisiklet sürmeyi severim."},{"w":"team","ipa":"/tiːm/","pos":"👥","tr":"takım","ex":"I am in a team.","exTr":"Bir takımdayım."},{"w":"goal","ipa":"/ɡəʊl/","pos":"🥅","tr":"gol","ex":"He scores a goal.","exTr":"Gol atar."},{"w":"sport","ipa":"/spɔːt/","pos":"🏅","tr":"spor","ex":"Which sport do you like?","exTr":"Hangi sporu seversin?"}],"chunks":[{"en":"I play football.","tr":"Futbol oynarım."},{"en":"Let's play at break!","tr":"Teneffüste oynayalım!"},{"en":"Do you play any sports?","tr":"Hiç spor yapıyor musun?"},{"en":"Great job!","tr":"Harika iş!"}],"grammar":{"point":"play / go + sport","tr":"Çoğu spor için 'play' kullanırız: play football, play tennis. Yüzme ve bisiklet gibi '-ing' ile biten sporlarda ise genellikle 'go' kullanırız: go swimming, go cycling.","examples":["I play football on Monday.","She plays tennis.","We go swimming on Sundays.","He goes cycling in the park."]},"questions":[{"q":"What sport does Zeynep play on Saturdays?","a":"Tennis."},{"q":"On which days does the narrator play football?","a":"On Monday and Thursday."},{"q":"What does the narrator's dad say about swimming?","a":"That the narrator swims like a fish."}],"quiz":[{"q":"I play ___ with my team.","o":["football","swimming","cycling"],"a":0,"why":""},{"q":"Which sport uses a racket?","o":["swimming","football","tennis"],"a":2,"why":"Tenisçiler raket kullanır."},{"q":"I ___ swimming on Sundays.","o":["play","go","have"],"a":1,"why":"Yüzme için 'go' kullanılır."},{"q":"Which word means 'takım'?","o":["goal","ball","team"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I play football on Monday.","cue":"Thursday","answer":"I play football on Thursday."},{"type":"Soru yap","prompt":"I play tennis on Saturdays.","cue":"Soru yap (you)","answer":"Do you play tennis on Saturdays?"},{"type":"Genişletme","prompt":"We go swimming.","cue":"+ with my dad on Sundays","answer":"We go swimming with my dad on Sundays."}],"sounds":[{"focus":"/ɔː/ – /ɒ/","tr":"/ɔː/ uzun ve dudakların yuvarlak olduğu bir 'o' sesidir; sesi uzat. /ɒ/ ise daha kısa ve dudakların daha az yuvarlak olduğu bir sestir.","pairs":["short / shot","port / pot","caught / cot"]}],"mission":{"brief":"Oyun: En sevdiğin sporu anlat ve nerede ve ne zaman oynadığını söyle. Claude, yeni takım arkadaşın Max olacak ve sporla ilgili sorular soracak.","persona":"Max, a 10-year-old new team member. Excited and friendly, uses short, simple sentences and asks one question at a time. Hidden fact: he is nervous about swimming and only admits it if asked whether he likes water sports.","goal":"En az üç spor adını İngilizce söyle ve Max'e bir soru sor.","opener":"Hi! I'm new in the team. What sports do you play?"}},"KS2-006":{"objectives":["Bir aile üyesinin görünüşünü İngilizce anlatmak","'has' ve 'is' kalıplarını üçüncü kişi için kullanmak","Aile bireylerini kısa tanıtımlarla sunmak"],"dialogues":[{"title":"The family photo","setting":"Okulda Selin, arkadaşı Ben'e aile fotoğrafını gösteriyor.","lines":[{"s":"Ben","en":"Who is the woman in the photo?","tr":"Fotoğraftaki kadın kim?"},{"s":"Selin","en":"That's my aunt. She's tall and she has curly hair.","tr":"O benim teyzem. Uzun boylu ve kıvırcık saçları var."},{"s":"Ben","en":"Is she funny?","tr":"Komik mi?"},{"s":"Selin","en":"Very! She tells the best jokes.","tr":"Çok! En iyi şakaları anlatır."},{"s":"Ben","en":"And who are these two boys?","tr":"Peki şu iki çocuk kim?"},{"s":"Selin","en":"They are my twin cousins, Emre and Ali.","tr":"Onlar ikiz kuzenlerim, Emre ve Ali."},{"s":"Ben","en":"They look the same!","tr":"Tıpatıp benziyorlar!"}]},{"title":"Uncle's visit","setting":"Akşam, Murat Amca evlerine geldiğinde Derya onu karşılıyor.","lines":[{"s":"Derya","en":"Uncle Murat! It's so nice to see you.","tr":"Murat Amca! Seni görmek çok güzel."},{"s":"Murat","en":"You're taller than last year, Derya!","tr":"Geçen yıldan daha uzunsun Derya!"},{"s":"Derya","en":"Thank you! I'm ten now.","tr":"Teşekkürler! Artık on yaşındayım."},{"s":"Murat","en":"Where is your little brother?","tr":"Küçük kardeşin nerede?"},{"s":"Derya","en":"He's in the garden with Aunt Ayşe.","tr":"Bahçede, Ayşe Teyze'yle birlikte."},{"s":"Murat","en":"Let's go and say hello!","tr":"Gidip merhaba diyelim!"}]},{"title":"My family at school","setting":"Sınıfta aile çalışması. Öğretmen Ms Ece öğrencilere soruyor.","lines":[{"s":"Ms Ece","en":"Who wants to describe their family?","tr":"Ailesini anlatmak isteyen var mı?"},{"s":"Ayla","en":"I do! I have a cousin. Her name is Lina.","tr":"Ben! Bir kuzenim var. Adı Lina."},{"s":"Ms Ece","en":"What does she look like?","tr":"Nasıl görünüyor?"},{"s":"Ayla","en":"She has short hair and big brown eyes.","tr":"Kısa saçları ve büyük kahverengi gözleri var."},{"s":"Ms Ece","en":"Lovely! Is she funny, too?","tr":"Harika! O da komik mi?"},{"s":"Ayla","en":"Yes! She makes me laugh every day.","tr":"Evet! Her gün beni güldürür."}]}],"reading":{"title":"My big family","paras":[{"en":"My family is big and fun. I have a mum, a dad and one older sister. My mum is short, but she is very strong. My dad has curly hair and a big smile. My uncle lives in Ankara. He is tall and he plays the guitar. My cousin Lina is my best friend. We laugh a lot together!","tr":"Ailem büyük ve eğlenceli. Bir annem, bir babam ve büyük bir ablam var. Annem kısa boylu ama çok güçlü. Babamın kıvırcık saçları ve geniş bir gülümsemesi var. Amcam Ankara'da yaşıyor. Uzun boylu ve gitar çalıyor. Kuzenim Lina en iyi arkadaşım. Birlikte çok gülüyoruz!"}]},"vocab":[{"w":"uncle","ipa":"/ˈʌŋkl/","pos":"🧔","tr":"amca, dayı","ex":"My uncle lives in Ankara.","exTr":"Amcam Ankara'da yaşıyor."},{"w":"aunt","ipa":"/ɑːnt/","pos":"👩","tr":"teyze, hala, yenge","ex":"That's my aunt.","exTr":"O benim teyzem."},{"w":"cousin","ipa":"/ˈkʌzn/","pos":"🧒","tr":"kuzen","ex":"My cousin is my best friend.","exTr":"Kuzenim en iyi arkadaşım."},{"w":"twin","ipa":"/twɪn/","pos":"👯","tr":"ikiz","ex":"They are twins.","exTr":"Onlar ikiz."},{"w":"tall","ipa":"/tɔːl/","pos":"📏","tr":"uzun boylu","ex":"My uncle is tall.","exTr":"Amcam uzun boylu."},{"w":"short","ipa":"/ʃɔːt/","pos":"🤏","tr":"kısa boylu; kısa","ex":"My mum is short.","exTr":"Annem kısa boylu."},{"w":"curly","ipa":"/ˈkɜːli/","pos":"🌀","tr":"kıvırcık","ex":"She has curly hair.","exTr":"Kıvırcık saçları var."},{"w":"funny","ipa":"/ˈfʌni/","pos":"😄","tr":"komik","ex":"She is very funny.","exTr":"Çok komik."}],"chunks":[{"en":"She has curly hair.","tr":"Kıvırcık saçları var."},{"en":"What does she look like?","tr":"Nasıl görünüyor?"},{"en":"She makes me laugh.","tr":"Beni güldürür."},{"en":"They look the same!","tr":"Tıpatıp benziyorlar!"}],"grammar":{"point":"has / is (he, she)","tr":"Üçüncü kişi (he, she) için saç ve özellikleri 'has' ile, sıfatları 'is' ile söyleriz. 'Has' yerine 'have' yazılmaz.","examples":["She has curly hair.","He has a big smile.","My uncle is tall.","Lina has short hair."]},"questions":[{"q":"What kind of hair does Selin's aunt have?","a":"Curly hair."},{"q":"Where does the narrator's uncle live?","a":"In Ankara."},{"q":"Who is the narrator's best friend?","a":"Lina, the narrator's cousin."}],"quiz":[{"q":"My ___ is my mum's brother.","o":["aunt","uncle","cousin"],"a":1,"why":"Annenin erkek kardeşi amca ya da dayıdır."},{"q":"Lina ___ short hair.","o":["has","is","have"],"a":0,"why":""},{"q":"A person who makes you laugh is…","o":["short","tall","funny"],"a":2,"why":"'Funny' komik demektir."},{"q":"Which word means 'kıvırcık'?","o":["straight","curly","tall"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"My uncle is tall.","cue":"aunt","answer":"My aunt is tall."},{"type":"Dönüştürme","prompt":"She has curly hair.","cue":"They","answer":"They have curly hair."},{"type":"Genişletme","prompt":"Lina is my best friend.","cue":"+ and my cousin","answer":"Lina is my best friend and my cousin."}],"sounds":[{"focus":"/ʌ/ – /ɑː/","tr":"/ʌ/ kısa, ağzı az açık ve gırtlaktan gelen bir 'a' sesidir; 'uncle' ve 'cousin' kelimelerindeki 'u' bu sestir. /ɑː/ ise ağzını geniş açıp uzat.","pairs":["cut / cart","fun / farm","cup / car"]}],"mission":{"brief":"Oyun: Bir aile üyeni görünüşüyle ve bir özelliğiyle İngilizce tanıt. Claude, yeni arkadaşın Sam olacak ve senden aile fotoğrafı hakkında sorular soracak.","persona":"Sam, a curious 10-year-old who just moved to town. Uses short, simple sentences and asks one question at a time. Hidden fact: his parents work abroad and he lives with his grandma; he only mentions this if asked who lives in his house.","goal":"Bir aile üyeni görünüşüyle ve kişiliğiyle tanıt, sonra Sam'e bir soru sor.","opener":"Hi! I'm Sam. Can you show me a family photo? Who is in it?"}},"KS2-007":{"objectives":["Kasabadaki yerleri İngilizce adlandırmak","Yer bildiren edatları ('next to', 'near', 'in') kullanmak","Basit bir yol tarifi vermek"],"dialogues":[{"title":"Where is the library?","setting":"Sokakta, Ece yeni gelen arkadaşı Tom'a yol tarif ediyor.","lines":[{"s":"Tom","en":"Excuse me, where is the library?","tr":"Affedersiniz, kütüphane nerede?"},{"s":"Ece","en":"It's next to the park. Go straight on.","tr":"Parkın yanında. Düz gidin."},{"s":"Tom","en":"Is it far from here?","tr":"Buradan uzak mı?"},{"s":"Ece","en":"No, it's five minutes on foot.","tr":"Hayır, yürüyerek beş dakika."},{"s":"Tom","en":"Thank you! Is the cinema near the library?","tr":"Teşekkürler! Sinema kütüphaneye yakın mı?"},{"s":"Ece","en":"Yes, it's across the road from it.","tr":"Evet, tam karşısında."}]},{"title":"Saturday at the market","setting":"Cumartesi sabahı, Derin annesiyle pazara gitmeyi planlıyor.","lines":[{"s":"Derin","en":"Mum, can we go to the market on Saturday?","tr":"Anne, cumartesi pazara gidebilir miyiz?"},{"s":"Mum","en":"Yes! It's near the station.","tr":"Evet! İstasyonun yakınında."},{"s":"Derin","en":"Is there a fruit shop there?","tr":"Orada meyve dükkânı var mı?"},{"s":"Mum","en":"Yes, there are lots of fruit shops.","tr":"Evet, bir sürü meyve dükkânı var."},{"s":"Derin","en":"I want to buy some bananas!","tr":"Biraz muz almak istiyorum!"},{"s":"Mum","en":"Good idea. Bring your bag.","tr":"İyi fikir. Çantanı getir."}]},{"title":"School trip","setting":"Okul gezisinde, Miss Ayla öğrencilere kasabanın köprüsünü gösteriyor.","lines":[{"s":"Miss Ayla","en":"Look, children! This is our town's old bridge.","tr":"Bakın çocuklar! Bu bizim kasabanın eski köprüsü."},{"s":"Ali","en":"It's very long! Is it safe?","tr":"Çok uzun! Güvenli mi?"},{"s":"Miss Ayla","en":"Yes, it's safe. The hospital is over there, behind the bridge.","tr":"Evet, güvenli. Hastane orada, köprünün arkasında."},{"s":"Zeynep","en":"Is it a big hospital?","tr":"Büyük bir hastane mi?"},{"s":"Miss Ayla","en":"Yes, and it has a very kind doctor.","tr":"Evet, ve çok nazik bir doktoru var."},{"s":"Ali","en":"I want to visit the station too!","tr":"İstasyonu da ziyaret etmek istiyorum!"}]}],"reading":{"title":"My town","paras":[{"en":"I live in a small town near the sea. There is a big park with a lake, and my favourite place is the library. It has lots of books and a quiet room for reading. Next to the library there is a cinema. On Saturdays we go to the market near the station. Dad buys fresh bread there. Our town is quiet, friendly and clean.","tr":"Denize yakın küçük bir kasabada yaşıyorum. Gölü olan büyük bir park var ve en sevdiğim yer kütüphane. İçinde bir sürü kitap ve okumak için sessiz bir oda var. Kütüphanenin yanında bir sinema var. Cumartesileri istasyonun yakınındaki pazara gideriz. Babam orada taze ekmek alır. Kasabamız sakin, samimi ve temiz."}]},"vocab":[{"w":"park","ipa":"/pɑːk/","pos":"🌳","tr":"park","ex":"The park is big.","exTr":"Park büyük."},{"w":"shop","ipa":"/ʃɒp/","pos":"🏪","tr":"dükkân","ex":"The shop is near my house.","exTr":"Dükkân evimin yakınında."},{"w":"library","ipa":"/ˈlaɪbrəri/","pos":"📚","tr":"kütüphane","ex":"The library is quiet.","exTr":"Kütüphane sessiz."},{"w":"cinema","ipa":"/ˈsɪnəmə/","pos":"🎬","tr":"sinema","ex":"We watch films at the cinema.","exTr":"Sinemada film izleriz."},{"w":"hospital","ipa":"/ˈhɒspɪtl/","pos":"🏥","tr":"hastane","ex":"The hospital is over there.","exTr":"Hastane orada."},{"w":"bridge","ipa":"/brɪdʒ/","pos":"🌉","tr":"köprü","ex":"We walk over the bridge.","exTr":"Köprünün üzerinden yürürüz."},{"w":"station","ipa":"/ˈsteɪʃn/","pos":"🚉","tr":"istasyon","ex":"The station is near the market.","exTr":"İstasyon pazarın yakınında."},{"w":"market","ipa":"/ˈmɑːkɪt/","pos":"🛒","tr":"pazar","ex":"We buy fruit at the market.","exTr":"Pazardan meyve alırız."}],"chunks":[{"en":"Where is the library?","tr":"Kütüphane nerede?"},{"en":"Go straight on.","tr":"Düz gidin."},{"en":"It's next to the park.","tr":"Parkın yanında."},{"en":"It's five minutes on foot.","tr":"Yürüyerek beş dakika."}],"grammar":{"point":"Prepositions of place","tr":"Bir şeyin yerini söylemek için 'next to' (tam yanında), 'near' (yakınında) ve 'in' (içinde) gibi edatlar kullanırız. Bu kelimeler Türkçedeki yer eklerinin karşılığıdır ve yerin önünde gelir.","examples":["The park is next to the school.","The shop is near the station.","The library is in the town centre.","The bank is on the main street."]},"questions":[{"q":"What is next to the library?","a":"A cinema."},{"q":"Where does the family go on Saturdays?","a":"To the market near the station."},{"q":"What does Dad buy at the market?","a":"Fresh bread."}],"quiz":[{"q":"Where can you borrow books?","o":["cinema","market","library"],"a":2,"why":""},{"q":"The shop is ___ the station.","o":["near","under","sea"],"a":0,"why":"'Near' yakınında demektir."},{"q":"Which place is for watching films?","o":["hospital","cinema","park"],"a":1,"why":""},{"q":"A ___ goes over a river.","o":["market","station","bridge"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"The park is next to the school.","cue":"the cinema","answer":"The park is next to the cinema."},{"type":"Soru yap","prompt":"The library is next to the park.","cue":"Where…?","answer":"Where is the library?"},{"type":"Genişletme","prompt":"It's five minutes on foot.","cue":"+ from here","answer":"It's five minutes on foot from here."}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Kısa ve gevşek /ɪ/ sesinde dil yukarıda ama gevşektir; uzun /iː/ ise daha gergin ve uzun söylenir. 'Live' (yaşamak) ile 'leave' (ayrılmak) bu yüzden farklı anlama gelir.","pairs":["live / leave","ship / sheep","bit / beat"]}],"mission":{"brief":"Oyun: Kasabanı İngilizce tanıt ve yeni bir arkadaşına yol tarif et. Claude, yeni gelen arkadaşın Oscar olacak ve sana yerlerin nerede olduğunu soracak.","persona":"Oscar, a polite 10-year-old new student from England. Speaks in short, simple sentences and asks one question at a time. Hidden fact: he is looking for the hospital because his little brother hurt his arm; he only tells you if asked why he needs that place.","goal":"Oscar'a en az üç yer adını İngilizce söyle ve ona bir yol tarif et.","opener":"Hi! I'm new here. Can you help me? Where is the hospital?"}},"KS2-008":{"objectives":["Bakkalda atıştırmalık ve içecek istemek","'Can I have…, please?' kalıbını kibarca kullanmak","Fiyat sorup ödeme yapmak"],"dialogues":[{"title":"At the corner shop","setting":"Ada, bakkalda atıştırmalık alıyor.","lines":[{"s":"Ada","en":"Can I have some crisps, please?","tr":"Biraz cips alabilir miyim, lütfen?"},{"s":"Shopkeeper","en":"Sure! Here you are. Anything else?","tr":"Tabii! Buyur. Başka bir şey var mı?"},{"s":"Ada","en":"I want a chocolate bar too. How much is it?","tr":"Bir de bir çikolata istiyorum. Kaç para?"},{"s":"Shopkeeper","en":"It costs five lira.","tr":"Beş lira tutar."},{"s":"Ada","en":"Here is my money. Thank you!","tr":"İşte param. Teşekkürler!"},{"s":"Shopkeeper","en":"You're welcome. Have a nice day!","tr":"Rica ederim. İyi günler!"}]},{"title":"Snack time with Ali","setting":"Okulda Ali, Ada'nın atıştırmalıklarına bakıyor.","lines":[{"s":"Ali","en":"What do you have, Ada?","tr":"Ne var sende, Ada?"},{"s":"Ada","en":"I have a banana and a biscuit.","tr":"Bir muzum ve bir bisküvim var."},{"s":"Ali","en":"I like biscuits! Can I have one, please?","tr":"Bisküvileri severim! Birini alabilir miyim, lütfen?"},{"s":"Ada","en":"Yes, of course. Here you are.","tr":"Tabii ki. Buyur."},{"s":"Ali","en":"Thanks! I don't like bananas, though.","tr":"Teşekkürler! Ama ben muzu sevmem."},{"s":"Ada","en":"That's OK. I like bananas!","tr":"Sorun değil. Ben muzu severim!"}]},{"title":"Juice or lemonade?","setting":"Bakkalda, Ada babasıyla içecek seçiyor.","lines":[{"s":"Dad","en":"Do you want juice or lemonade?","tr":"Meyve suyu mu yoksa limonata mı istersin?"},{"s":"Ada","en":"Orange juice, please.","tr":"Portakal suyu, lütfen."},{"s":"Dad","en":"Small or big?","tr":"Küçük mü, büyük mü?"},{"s":"Ada","en":"A small one, please.","tr":"Küçük olanı, lütfen."},{"s":"Dad","en":"Here you are. Let's go home now!","tr":"Buyur. Hadi şimdi eve gidelim!"},{"s":"Ada","en":"Thank you, Dad!","tr":"Teşekkürler baba!"}]}],"reading":{"title":"Ada's Friday snack","paras":[{"en":"Ada loves snacks. On Friday, she goes to the shop with her dad. She has some money in her pocket. She buys crisps, a biscuit and an orange juice. The crisps cost five lira. Ada says, 'Thank you!' to the shopkeeper. Then they walk home and share their snacks. Ada is very happy!","tr":"Ada atıştırmalıkları çok sever. Cuma günü babasıyla bakkala gider. Cebinde biraz parası vardır. Cips, bir bisküvi ve bir portakal suyu alır. Cips beş lira tutar. Ada bakkala 'Teşekkürler!' der. Sonra yürüyerek eve dönerler ve atıştırmalıklarını paylaşırlar. Ada çok mutlu!"}]},"vocab":[{"w":"crisps","ipa":"/krɪsps/","pos":"🥔","tr":"cips","ex":"I want some crisps.","exTr":"Biraz cips istiyorum."},{"w":"biscuit","ipa":"/ˈbɪskɪt/","pos":"🍪","tr":"bisküvi","ex":"This biscuit is sweet.","exTr":"Bu bisküvi tatlı."},{"w":"banana","ipa":"/bəˈnɑːnə/","pos":"🍌","tr":"muz","ex":"I like bananas.","exTr":"Muzu severim."},{"w":"juice","ipa":"/dʒuːs/","pos":"🧃","tr":"meyve suyu","ex":"Orange juice, please.","exTr":"Portakal suyu, lütfen."},{"w":"chocolate","ipa":"/ˈtʃɒklət/","pos":"🍫","tr":"çikolata","ex":"I have a chocolate bar.","exTr":"Bir çikolata barım var."},{"w":"shop","ipa":"/ʃɒp/","pos":"🏪","tr":"bakkal, dükkân","ex":"We go to the shop on Friday.","exTr":"Cuma günü bakkala gidiyoruz."},{"w":"money","ipa":"/ˈmʌni/","pos":"💰","tr":"para","ex":"I have some money.","exTr":"Biraz param var."},{"w":"cost","ipa":"/kɒst/","pos":"💲","tr":"tutmak, fiyatı olmak","ex":"The crisps cost five lira.","exTr":"Cips beş lira tutar."}],"chunks":[{"en":"Can I have…, please?","tr":"…alabilir miyim, lütfen?"},{"en":"Here you are.","tr":"Buyur."},{"en":"How much is it?","tr":"Kaç para?"},{"en":"Have a nice day!","tr":"İyi günler!"}],"grammar":{"point":"Asking politely: Can I have…?","tr":"Bir şey istediğinde 'Can I have…?' kalıbını kullanırsın. Bu, Türkçedeki 'Bir … alabilir miyim?' cümlesinin karşılığıdır. Sonuna 'please' eklemek kibar olmasını sağlar.","examples":["Can I have a banana, please?","Can I have some juice?","Can I have one biscuit?","Can I have a chocolate bar, please?"]},"questions":[{"q":"What does Ada buy at the shop?","a":"Crisps, a biscuit and an orange juice."},{"q":"How much do the crisps cost?","a":"Five lira."},{"q":"Who does Ada go to the shop with?","a":"Her dad."}],"quiz":[{"q":"What is this? 🍌","o":["biscuit","banana","chocolate"],"a":1,"why":""},{"q":"Which sentence asks politely for a snack?","o":["Give me it now!","Can I have a biscuit, please?","Biscuit, I have."],"a":1,"why":"'Can I have…, please?' kibar bir istektir."},{"q":"The shopkeeper says 'Here you are.' He means…","o":["How are you?","Goodbye.","Here it is, take it."],"a":2,"why":"'Here you are' = Buyur, al."},{"q":"I ___ some money.","o":["have","has","having"],"a":0,"why":"'I' ile 'have' kullanılır."}],"drills":[{"type":"Yerine koyma","prompt":"Can I have some crisps, please?","cue":"juice","answer":"Can I have some juice, please?"},{"type":"Dönüştürme","prompt":"I want a banana, please.","cue":"Can I have…?","answer":"Can I have a banana, please?"},{"type":"Soru yap","prompt":"The biscuit costs two lira.","cue":"How much…?","answer":"How much does the biscuit cost?"}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Kısa /ɪ/ sesini 'i' gibi uzatma; dilini biraz gevşek tut. Uzun /iː/ daha gergin ve uzun söylenir. 'Chip' ile 'cheap' arasındaki fark buradan gelir.","pairs":["chip / cheap","ship / sheep","fill / feel"]}],"mission":{"brief":"Bakkalda bir alışveriş oyunu oynayacaksın. Claude, bakkal Bay Tom olacak; sen ona atıştırmalık ve içecek istemeli, fiyatını sormalı ve kibarca ödeme yapmalısın. Bay Tom'a iyi sorular sorarak bugünkü özel ürünü öğrenmeye çalış.","persona":"Mr Tom, a friendly shopkeeper. Speaks slowly, in short sentences, and smiles a lot. Hidden fact: the orange juice is on special offer today for half price, but he only mentions it if the learner asks what is special or cheap today.","goal":"Bay Tom'a üç kibar soru sor ve indirimli ürünü bul.","opener":"Hello! Welcome to my shop. What would you like today?"}},"KS2-009":{"objectives":["Yiyecek ve içecekleri İngilizce söylemek","'I like' ve 'I don't like' ile sevdiklerini anlatmak","Sağlıklı bir öğle yemeği hakkında kısa konuşmalar yapmak"],"dialogues":[{"title":"What's in your lunch box?","setting":"Okulda öğle yemeği. Ela ve Leo kutularını açıyor.","lines":[{"s":"Leo","en":"What's in your lunch box, Ela?","tr":"Öğle yemeği kutunda ne var, Ela?"},{"s":"Ela","en":"An apple and some carrots. Look!","tr":"Bir elma ve biraz havuç. Bak!"},{"s":"Leo","en":"Carrots are healthy! I have a sandwich and a cake.","tr":"Havuç sağlıklı! Benim bir sandviçim ve bir kekim var."},{"s":"Ela","en":"Cake is not very healthy. Eat more fruit!","tr":"Kek pek sağlıklı değil. Daha çok meyve ye!"},{"s":"Leo","en":"OK, I'll eat my apple too.","tr":"Tamam, elmamı da yiyeceğim."},{"s":"Ela","en":"Great! And eat your vegetables too.","tr":"Harika! Sebzelerini de ye."}]},{"title":"Breakfast with Mum","setting":"Sabah kahvaltısında Mert annesiyle konuşuyor.","lines":[{"s":"Mum","en":"Good morning, Mert! Eat your breakfast.","tr":"Günaydın Mert! Kahvaltını ye."},{"s":"Mert","en":"I want some milk and an egg, please.","tr":"Biraz süt ve bir yumurta istiyorum, lütfen."},{"s":"Mum","en":"Eggs are good for you. They make you strong.","tr":"Yumurta senin için iyidir. Seni güçlü yapar."},{"s":"Mert","en":"Can I have some honey too?","tr":"Bir de biraz bal alabilir miyim?"},{"s":"Mum","en":"Yes, a little. Too much sugar is not good.","tr":"Evet, biraz. Çok şeker iyi değil."},{"s":"Mert","en":"OK, Mum. Thank you!","tr":"Tamam anne. Teşekkürler!"}]},{"title":"Snack at the park","setting":"Parkta, Mia ve Leo atıştırmalık seçiyor.","lines":[{"s":"Mia","en":"I'm hungry. Do you want a cookie?","tr":"Açım. Bir kurabiye ister misin?"},{"s":"Leo","en":"No, thanks. I want a strawberry.","tr":"Hayır, teşekkürler. Bir çilek istiyorum."},{"s":"Mia","en":"Strawberries are sweet and healthy.","tr":"Çilekler tatlı ve sağlıklı."},{"s":"Leo","en":"And they are red, like a heart!","tr":"Ayrıca kalp gibi kırmızılar!"},{"s":"Mia","en":"I like them too. Let's share!","tr":"Ben de severim. Paylaşalım!"}]}],"reading":{"title":"Ela's healthy day","paras":[{"en":"Ela likes healthy food. Every day she eats fruit and vegetables. She drinks lots of water. Sometimes she eats a small cake, but not every day. Her mum says healthy food makes us strong and happy. Ela agrees! She says a healthy lunch makes her feel good and gives her energy to play.","tr":"Ela sağlıklı yiyecekleri sever. Her gün meyve ve sebze yer. Bol su içer. Bazen küçük bir kek yer, ama her gün değil. Annesi, sağlıklı yiyeceklerin bizi güçlü ve mutlu yaptığını söyler. Ela da katılıyor! Ela, sağlıklı bir öğle yemeğinin kendini iyi hissettirdiğini ve oynamak için enerji verdiğini söyler."}]},"vocab":[{"w":"apple","ipa":"/ˈæpl/","pos":"🍎","tr":"elma","ex":"I have a red apple.","exTr":"Kırmızı bir elmam var."},{"w":"carrot","ipa":"/ˈkærət/","pos":"🥕","tr":"havuç","ex":"Carrots are healthy.","exTr":"Havuç sağlıklıdır."},{"w":"vegetable","ipa":"/ˈvedʒtəbl/","pos":"🥦","tr":"sebze","ex":"Eat your vegetables.","exTr":"Sebzelerini ye."},{"w":"fruit","ipa":"/fruːt/","pos":"🍉","tr":"meyve","ex":"Fruit is sweet.","exTr":"Meyve tatlıdır."},{"w":"milk","ipa":"/mɪlk/","pos":"🥛","tr":"süt","ex":"I drink milk.","exTr":"Süt içerim."},{"w":"egg","ipa":"/eɡ/","pos":"🥚","tr":"yumurta","ex":"I want an egg.","exTr":"Bir yumurta istiyorum."},{"w":"water","ipa":"/ˈwɔːtə/","pos":"💧","tr":"su","ex":"Drink some water.","exTr":"Biraz su iç."},{"w":"strawberry","ipa":"/ˈstrɔːbəri/","pos":"🍓","tr":"çilek","ex":"I like strawberries.","exTr":"Çilekleri severim."}],"chunks":[{"en":"I'm hungry.","tr":"Açım."},{"en":"Let's share!","tr":"Paylaşalım!"},{"en":"Eat your vegetables.","tr":"Sebzelerini ye."},{"en":"That's good for you.","tr":"Bu senin için iyi."}],"grammar":{"point":"I like… / I don't like…","tr":"'I like' bir şeyi sevdiğini, 'I don't like' ise sevmediğini anlatır. İkisinden sonra bir isim gelir: 'I like apples.' Türkçedeki 'severim' ve 'sevmem' kelimelerinin karşılığıdır.","examples":["I like carrots.","I don't like cake.","I like strawberries.","I don't like milk."]},"questions":[{"q":"What does Ela eat every day?","a":"Fruit and vegetables."},{"q":"What does Mert want for breakfast?","a":"Milk and an egg."},{"q":"Why does Leo like strawberries?","a":"They are sweet, healthy and red."}],"quiz":[{"q":"What is this? 🍎","o":["milk","apple","egg"],"a":1,"why":""},{"q":"Which one is a vegetable?","o":["strawberry","milk","carrot"],"a":2,"why":""},{"q":"I ___ cake. (Kek sevmem.)","o":["like","don't like","likes"],"a":1,"why":"Olumsuz için 'I don't like' kullanılır."},{"q":"Which drink is good for you?","o":["water","cake","biscuit"],"a":0,"why":"Su sağlıklıdır."}],"drills":[{"type":"Yerine koyma","prompt":"I like apples.","cue":"carrots","answer":"I like carrots."},{"type":"Genişletme","prompt":"I like strawberries.","cue":"+ very much","answer":"I like strawberries very much."},{"type":"Soru yap","prompt":"Ela likes strawberries.","cue":"Does…?","answer":"Does Ela like strawberries?"}],"sounds":[{"focus":"/s/ – /z/","tr":"Sonda gelen 'z' sesini 's' gibi fısıldama. Boğazında bir titreşim hissetmelisin. 'Eggs' ve 'is' gibi kelimelerde dilini dişlerinin arkasında tut ve sesi titret.","pairs":["sip / zip","bus / buzz","ice / eyes"]}],"mission":{"brief":"Bir öğle yemeği kutusu hazırlıyorsun. Claude, arkadaşın Leo olacak; Leo'ya ne yemek sevdiğini sormalı ve ona sağlıklı bir atıştırmalık önermelisin.","persona":"Leo, a 10-year-old boy who loves sandwiches and says he hates vegetables. Hidden fact: he secretly loves cucumbers, but he only admits it when asked open questions about which vegetables he likes at home. Speaks in short, simple sentences and gets excited by fun ideas.","goal":"Leo'nun en sevdiği sebzeyi öğren ve 'I like…' kalıbıyla ona sağlıklı bir öğle yemeği öner.","opener":"Hi! What's in your lunch box today? Mine has a sandwich and a cake!"}},"KS2-010":{"objectives":["Hastalık belirtilerini İngilizce anlatmak","'I feel…' kalıbıyla nasıl hissettiğini söylemek","Doktor ve eczacıyla kısa konuşmalar yapmak"],"dialogues":[{"title":"At the doctor's","setting":"Mia karnı ağrıdığı için doktora gidiyor. Annesi yanında.","lines":[{"s":"Doctor","en":"Hello, Mia. What's the matter?","tr":"Merhaba Mia. Sorun ne?"},{"s":"Mia","en":"I have a stomach ache.","tr":"Karnım ağrıyor."},{"s":"Doctor","en":"Oh no! Do you feel sick?","tr":"Ay, olamaz! Kendini hasta gibi hissediyor musun?"},{"s":"Mia","en":"A little. And I feel tired.","tr":"Biraz. Bir de kendimi yorgun hissediyorum."},{"s":"Doctor","en":"Let me see. Open your mouth, please.","tr":"Bir bakayım. Ağzını aç, lütfen."},{"s":"Mum","en":"Will she be OK, Doctor?","tr":"Doktor, iyi olacak mı?"},{"s":"Doctor","en":"Yes, she just needs rest and water.","tr":"Evet, sadece dinlenmeye ve su içmeye ihtiyacı var."}]},{"title":"At the pharmacy","setting":"Eczanede Leo'nun babası ilaç alıyor.","lines":[{"s":"Pharmacist","en":"Can I help you?","tr":"Size yardımcı olabilir miyim?"},{"s":"Dad","en":"Yes, my son has a fever.","tr":"Evet, oğlumun ateşi var."},{"s":"Pharmacist","en":"Here is some medicine. Take one spoon, twice a day.","tr":"Buyurun, biraz ilaç. Günde iki kez bir kaşık alsın."},{"s":"Leo","en":"Does it taste good?","tr":"Tadı iyi mi?"},{"s":"Pharmacist","en":"It tastes like orange!","tr":"Portakal gibi tadı var!"},{"s":"Dad","en":"Thank you very much.","tr":"Çok teşekkür ederim."}]},{"title":"Feeling better","setting":"Ertesi gün okulda Leo, Mia'nın nasıl olduğunu soruyor.","lines":[{"s":"Leo","en":"How are you today, Mia?","tr":"Bugün nasılsın, Mia?"},{"s":"Mia","en":"I feel better, thank you!","tr":"Daha iyiyim, teşekkürler!"},{"s":"Leo","en":"Did you take the medicine?","tr":"İlacını içtin mi?"},{"s":"Mia","en":"Yes! It tasted like oranges.","tr":"Evet! Portakal gibi tadı vardı."},{"s":"Leo","en":"Great! Do you want to play in the garden?","tr":"Harika! Bahçede oynamak ister misin?"},{"s":"Mia","en":"Not yet. I need to rest.","tr":"Henüz değil. Dinlenmem gerekiyor."},{"s":"Leo","en":"OK. Get well soon!","tr":"Tamam. Çabuk iyileş!"}]}],"reading":{"title":"Mia feels sick","paras":[{"en":"Mia had a stomach ache and a fever. Her mum took her to the doctor. The doctor looked at her and said, 'Rest and drink lots of water.' At the pharmacy, Mia got some medicine. It tasted like orange. Two days later, Mia felt much better and went back to school.","tr":"Mia'nın karnı ağrıyordu ve ateşi vardı. Annesi onu doktora götürdü. Doktor ona baktı ve 'Dinlen ve bol su iç' dedi. Eczanede Mia biraz ilaç aldı. Portakal gibi tadı vardı. İki gün sonra Mia kendini çok daha iyi hissetti ve okula geri döndü."}]},"vocab":[{"w":"doctor","ipa":"/ˈdɒktə/","pos":"👩‍⚕️","tr":"doktor","ex":"The doctor is kind.","exTr":"Doktor nazik."},{"w":"medicine","ipa":"/ˈmedsn/","pos":"💊","tr":"ilaç","ex":"Take your medicine.","exTr":"İlacını al."},{"w":"fever","ipa":"/ˈfiːvə/","pos":"🌡️","tr":"ateş","ex":"I have a fever.","exTr":"Ateşim var."},{"w":"stomach ache","ipa":"/ˈstʌmək eɪk/","pos":"🤕","tr":"karın ağrısı","ex":"I have a stomach ache.","exTr":"Karnım ağrıyor."},{"w":"tired","ipa":"/ˈtaɪəd/","pos":"😴","tr":"yorgun","ex":"I'm tired after school.","exTr":"Okuldan sonra yorgunum."},{"w":"rest","ipa":"/rest/","pos":"🛏️","tr":"dinlenmek","ex":"Rest in bed.","exTr":"Yatakta dinlen."},{"w":"sick","ipa":"/sɪk/","pos":"🤢","tr":"hasta","ex":"Mia feels sick.","exTr":"Mia kendini hasta hissediyor."},{"w":"better","ipa":"/ˈbetə/","pos":"😊","tr":"daha iyi","ex":"I feel better now.","exTr":"Şimdi kendimi daha iyi hissediyorum."}],"chunks":[{"en":"What's the matter?","tr":"Sorun ne?"},{"en":"I feel sick.","tr":"Kendimi hasta hissediyorum."},{"en":"Get well soon!","tr":"Çabuk iyileş!"},{"en":"Take one spoon, twice a day.","tr":"Günde iki kez bir kaşık al."}],"grammar":{"point":"I feel + adjective","tr":"'I feel' kendini nasıl hissettiğini anlatmak için kullanılır. Sıfat (sick, tired, better gibi) 'feel' fiilinden sonra gelir. Türkçedeki 'Kendimi … hissediyorum' yapısının karşılığıdır.","examples":["I feel sick.","I feel tired today.","She feels better now.","Do you feel OK?"]},"questions":[{"q":"What is wrong with Mia at the start?","a":"She has a stomach ache and she feels sick."},{"q":"How often should Leo take the medicine?","a":"Twice a day."},{"q":"How does Mia feel at school?","a":"She feels better."}],"quiz":[{"q":"The ___ helps sick people.","o":["apple","carrot","doctor"],"a":2,"why":""},{"q":"Mia has a stomach ___.","o":["ache","cake","take"],"a":0,"why":"'Ache' = ağrı."},{"q":"I have a ___. I feel hot and cold.","o":["rest","fever","medicine"],"a":1,"why":"'Fever' = ateş."},{"q":"'Get well soon!' means…","o":["Goodbye!","Let's go shopping.","I hope you feel better soon."],"a":2,"why":"'Get well soon' = Çabuk iyileş."}],"drills":[{"type":"Yerine koyma","prompt":"I feel sick.","cue":"tired","answer":"I feel tired."},{"type":"Genişletme","prompt":"Mia takes medicine.","cue":"+ twice a day","answer":"Mia takes medicine twice a day."},{"type":"Soru yap","prompt":"Mia feels better now.","cue":"Does…?","answer":"Does Mia feel better now?"}],"sounds":[{"focus":"/ʌ/","tr":"Türkçedeki 'a' sesine benzer ama daha kısa ve dil ortada tutulur. Ağzını fazla açma. 'Stomach' ve 'fun' gibi kelimelerde sesi kısa tut.","pairs":["cup / cap","bus / bass","fun / fan"]}],"mission":{"brief":"Oyunda doktor sensin. Claude, hasta Ela olacak; Ela'ya ne hissettiğini, ne zamandır kötü olduğunu ve dün ne yaptığını sormalısın. Doğru soruları sorarak Ela'nın asıl sorununu bulmaya çalış.","persona":"Ela, a 10-year-old patient who feels unwell. Speaks in short sentences. Hidden fact: she fell off her bike yesterday and her arm hurts badly, but she only says her tummy hurts unless the doctor asks where it hurts or what she did yesterday.","goal":"Ela'nın kolunun neden ağrıdığını öğren ve en az iki soru sor.","opener":"Hello, doctor. I don't feel very well today."}},"KS2-011":{"objectives":["Hava durumunu ve mevsimleri İngilizce söylemek","'It's…' kalıbıyla hava durumunu anlatmak","Hava durumuna göre kıyafet önermek"],"dialogues":[{"title":"What's the weather like?","setting":"Sabah, Mert ve annesi pencereden dışarı bakıyor.","lines":[{"s":"Mum","en":"Look outside, Mert. What's the weather like?","tr":"Dışarı bak Mert. Hava nasıl?"},{"s":"Mert","en":"It's sunny and warm!","tr":"Güneşli ve sıcak!"},{"s":"Mum","en":"Great! Then take a hat and sunglasses.","tr":"Harika! O zaman bir şapka ve güneş gözlüğü al."},{"s":"Mert","en":"What about my jacket?","tr":"Ya ceketim?"},{"s":"Mum","en":"Not today. It's too hot for a jacket.","tr":"Bugün hayır. Ceket için hava çok sıcak."},{"s":"Mert","en":"OK! Let's go to the park.","tr":"Tamam! Haydi parka gidelim."}]},{"title":"A rainy day","setting":"Yağmurlu bir günde Ela ve Leo evde oyun oynuyor.","lines":[{"s":"Leo","en":"It's raining! I can't play outside.","tr":"Yağmur yağıyor! Dışarıda oynayamam."},{"s":"Ela","en":"Don't worry. Let's play a board game.","tr":"Merak etme. Hadi bir masa oyunu oynayalım."},{"s":"Leo","en":"Good idea. Oh, and it's windy too!","tr":"İyi fikir. Ayrıca rüzgâr da var!"},{"s":"Ela","en":"Yes. The wind is strong today.","tr":"Evet. Bugün rüzgâr çok sert."},{"s":"Leo","en":"Is it cold outside?","tr":"Dışarısı soğuk mu?"},{"s":"Ela","en":"A little. Wear your coat, please.","tr":"Biraz. Lütfen mantonu giy."}]},{"title":"Four seasons song","setting":"Sınıfta öğretmen mevsimleri şarkıyla öğretiyor. Ritimle tekrar edin!","lines":[{"s":"Teacher","en":"Spring is green, summer is hot.","tr":"İlkbahar yeşildir, yaz sıcaktır."},{"s":"Kids","en":"Spring is green, summer is hot!","tr":"İlkbahar yeşildir, yaz sıcaktır!"},{"s":"Teacher","en":"Autumn leaves fall, winter is cold.","tr":"Sonbaharda yapraklar düşer, kış soğuktur."},{"s":"Kids","en":"Autumn leaves fall, winter is cold!","tr":"Sonbaharda yapraklar düşer, kış soğuktur!"},{"s":"Teacher","en":"Four seasons, one year. Clap, clap!","tr":"Dört mevsim, bir yıl. Alkışla, alkışla!"},{"s":"Kids","en":"Four seasons, one year. Clap, clap!","tr":"Dört mevsim, bir yıl. Alkışla, alkışla!"}]}],"reading":{"title":"The four seasons","paras":[{"en":"Turkey has four seasons. In spring, flowers grow and the weather is mild. Summer is hot, so we go to the beach. In autumn, the leaves turn orange and fall from the trees. Winter is cold, and sometimes it snows. In winter, we wear hats and gloves. My favourite season is summer, because I can swim!","tr":"Türkiye'de dört mevsim vardır. İlkbaharda çiçekler açar ve hava ılıktır. Yaz sıcaktır, bu yüzden sahile gideriz. Sonbaharda yapraklar turuncuya döner ve ağaçlardan düşer. Kış soğuktur ve bazen kar yağar. Kışın şapka ve eldiven takarız. En sevdiğim mevsim yaz, çünkü yüzebiliyorum!"}]},"vocab":[{"w":"sunny","ipa":"/ˈsʌni/","pos":"☀️","tr":"güneşli","ex":"It's sunny today.","exTr":"Bugün hava güneşli."},{"w":"rain","ipa":"/reɪn/","pos":"🌧️","tr":"yağmur, yağmak","ex":"It's raining now.","exTr":"Şu an yağmur yağıyor."},{"w":"snow","ipa":"/snəʊ/","pos":"❄️","tr":"kar","ex":"Snow is white.","exTr":"Kar beyazdır."},{"w":"wind","ipa":"/wɪnd/","pos":"💨","tr":"rüzgâr","ex":"The wind is strong.","exTr":"Rüzgâr sert."},{"w":"spring","ipa":"/sprɪŋ/","pos":"🌸","tr":"ilkbahar","ex":"Flowers grow in spring.","exTr":"Çiçekler ilkbaharda açar."},{"w":"summer","ipa":"/ˈsʌmə/","pos":"🏖️","tr":"yaz","ex":"We go to the beach in summer.","exTr":"Yazın sahile gideriz."},{"w":"autumn","ipa":"/ˈɔːtəm/","pos":"🍂","tr":"sonbahar","ex":"The leaves fall in autumn.","exTr":"Yapraklar sonbaharda düşer."},{"w":"winter","ipa":"/ˈwɪntə/","pos":"⛄","tr":"kış","ex":"It is cold in winter.","exTr":"Kışın hava soğuktur."}],"chunks":[{"en":"What's the weather like?","tr":"Hava nasıl?"},{"en":"It's too hot.","tr":"Hava çok sıcak."},{"en":"Don't worry.","tr":"Merak etme."},{"en":"Wear your coat.","tr":"Mantonu giy."}],"grammar":{"point":"It's + weather word","tr":"Hava durumunu anlatırken 'It's' ile başlayan kısa cümleler kurulur: 'It's sunny.' Türkçedeki 'Hava güneşli.' cümlesinin karşılığıdır. Soru sormak için 'What's the weather like?' diyebilirsin.","examples":["It's sunny today.","It's raining now.","It's cold in winter.","What's the weather like in summer?"]},"questions":[{"q":"What does Mert wear on a sunny day?","a":"A hat and sunglasses."},{"q":"Why can't Leo play outside?","a":"Because it's raining."},{"q":"Which season is cold?","a":"Winter."}],"quiz":[{"q":"What's the weather like? ☀️ It's ___.","o":["sunny","snowy","windy"],"a":0,"why":""},{"q":"In ___, the leaves fall from the trees.","o":["spring","autumn","summer"],"a":1,"why":""},{"q":"Take your coat. It's ___!","o":["sunny","hot","cold"],"a":2,"why":"Mont için hava soğuk olmalı."},{"q":"Which season is the hottest?","o":["winter","summer","spring"],"a":1,"why":"Yaz en sıcak mevsimdir."}],"drills":[{"type":"Yerine koyma","prompt":"It's sunny today.","cue":"rainy","answer":"It's rainy today."},{"type":"Dönüştürme","prompt":"It's windy today.","cue":"Ask: Is it…?","answer":"Is it windy today?"},{"type":"Genişletme","prompt":"We wear coats.","cue":"+ when it's cold","answer":"We wear coats when it's cold."}],"sounds":[{"focus":"/ɜː/","tr":"Türkçedeki uzun 'ö' sesine yakındır, ama dilin ucu geriye kıvrılmaz ve 'r' sesi yoktur. 'Bird' ve 'shirt' kelimelerinde dudaklarını hafifçe yuvarla ve sesi uzun tut.","pairs":["bird / bed","shirt / shot","first / fast"]}],"mission":{"brief":"Arkadaşın Ela yarın bir geziye çıkacak. Ela'ya hangi kıyafetleri giymesi gerektiğini söylemen gerekiyor; önce nereye gittiğini ve hava durumunu öğrenmelisin. Sonra ona uygun iki kıyafet öner.","persona":"Ela, a 10-year-old going on a school trip tomorrow. Friendly, uses short sentences. Hidden fact: the trip is to the mountains, not the beach, and it will be cold and snowy at the top; she has only packed shorts and sandals. She reveals this only when asked where the trip is or what the weather will be like.","goal":"Ela'nın nereye gideceğini ve hava durumunu öğren; ona uygun iki kıyafet öner.","opener":"Hi! I'm going on a trip tomorrow. What should I wear?"}},"KS2-012":{"objectives":["Tatil ve gezi ile ilgili kelimeleri İngilizce söylemek","'want to' kalıbıyla ne yapmak istediğini anlatmak","Otelde ve telefonda kısa konuşmalar yapmak"],"dialogues":[{"title":"Where shall we go?","setting":"Aile tatil planı yapıyor. Ela ile Mert nereye gideceklerine karar veriyor.","lines":[{"s":"Dad","en":"Where do you want to go on holiday?","tr":"Tatilde nereye gitmek istersiniz?"},{"s":"Ela","en":"I want to go to the beach!","tr":"Plaja gitmek istiyorum!"},{"s":"Mert","en":"I want to go to the mountains.","tr":"Dağlara gitmek istiyorum."},{"s":"Dad","en":"Both are good! Let's go to the beach in July.","tr":"İkisi de güzel! Temmuzda plaja gidelim."},{"s":"Ela","en":"Yay! Can I bring my swimsuit?","tr":"Yaşasın! Mayomu getirebilir miyim?"},{"s":"Dad","en":"Of course. And don't forget your sun cream!","tr":"Tabii ki. Bir de güneş kremini unutma!"}]},{"title":"Checking in","setting":"Otelin resepsiyonunda Yılmaz ailesi.","lines":[{"s":"Receptionist","en":"Welcome! Do you have a booking?","tr":"Hoş geldiniz! Rezervasyonunuz var mı?"},{"s":"Dad","en":"Yes, under the name Yılmaz.","tr":"Evet, Yılmaz adına."},{"s":"Receptionist","en":"Here is your key. Room 204, on the second floor.","tr":"Buyurun anahtarınız. 204 numaralı oda, ikinci katta."},{"s":"Mert","en":"Is there a swimming pool?","tr":"Yüzme havuzu var mı?"},{"s":"Receptionist","en":"Yes, it's behind the hotel. It opens at nine.","tr":"Evet, otelin arkasında. Saat dokuzda açılır."},{"s":"Mert","en":"Great! Thank you!","tr":"Harika! Teşekkürler!"}]},{"title":"Phone call from the beach","setting":"Ela, tatildeki arkadaşı Leo'yla telefonda konuşuyor.","lines":[{"s":"Leo","en":"Hi, Ela! How is your holiday?","tr":"Selam Ela! Tatilin nasıl?"},{"s":"Ela","en":"It's great! We are at the beach every day.","tr":"Harika! Her gün plajdayız."},{"s":"Leo","en":"Is the sea warm?","tr":"Deniz ılık mı?"},{"s":"Ela","en":"Yes! I swim and I build sandcastles.","tr":"Evet! Yüzüyorum ve kum kaleleri yapıyorum."},{"s":"Leo","en":"Wow! I want to come next year.","tr":"Vay! Gelecek yıl ben de gelmek istiyorum."},{"s":"Ela","en":"Please come! See you soon.","tr":"Lütfen gel! Görüşürüz."}]}],"reading":{"title":"Our summer trip","paras":[{"en":"Last summer, the Yılmaz family went on a trip to the coast. They stayed in a small hotel near the sea. Every morning, they walked along the beach and collected shells. In the afternoon, they swam in the swimming pool. Ela took lots of photos. Her favourite day was the boat trip, because they saw dolphins!","tr":"Geçen yaz Yılmaz ailesi sahile bir geziye çıktı. Denizin yakınında küçük bir otelde kaldılar. Her sabah plajda yürüyüp deniz kabukları topladılar. Öğleden sonra yüzme havuzunda yüzdüler. Ela çok fotoğraf çekti. En sevdiği gün tekne gezisiydi, çünkü yunuslar gördüler!"}]},"vocab":[{"w":"holiday","ipa":"/ˈhɒlədeɪ/","pos":"🌴","tr":"tatil","ex":"We go on holiday in July.","exTr":"Temmuzda tatile gidiyoruz."},{"w":"beach","ipa":"/biːtʃ/","pos":"🏖️","tr":"plaj","ex":"The beach is full of people.","exTr":"Plaj insanlarla dolu."},{"w":"mountain","ipa":"/ˈmaʊntən/","pos":"⛰️","tr":"dağ","ex":"I want to see the mountain.","exTr":"Dağı görmek istiyorum."},{"w":"hotel","ipa":"/həʊˈtel/","pos":"🏨","tr":"otel","ex":"The hotel is near the sea.","exTr":"Otel denize yakın."},{"w":"swimming pool","ipa":"/ˈswɪmɪŋ puːl/","pos":"🏊","tr":"yüzme havuzu","ex":"The swimming pool opens at nine.","exTr":"Yüzme havuzu saat dokuzda açılır."},{"w":"sandcastle","ipa":"/ˈsændkɑːsl/","pos":"🏰","tr":"kum kalesi","ex":"We build a sandcastle.","exTr":"Bir kum kalesi yapıyoruz."},{"w":"sun cream","ipa":"/sʌn kriːm/","pos":"🧴","tr":"güneş kremi","ex":"Don't forget your sun cream.","exTr":"Güneş kremini unutma."},{"w":"trip","ipa":"/trɪp/","pos":"🧳","tr":"gezi, yolculuk","ex":"We went on a trip to the coast.","exTr":"Sahile bir geziye çıktık."}],"chunks":[{"en":"Where do you want to go?","tr":"Nereye gitmek istersin?"},{"en":"Don't forget…!","tr":"…unutma!"},{"en":"See you soon!","tr":"Görüşürüz!"},{"en":"Let's go to…","tr":"…gidelim."}],"grammar":{"point":"want to + verb","tr":"İstek bildirmek için 'want to' ve ardından fiilin yalın hali kullanılır: 'I want to swim.' Türkçedeki '-mek istiyorum' yapısının karşılığıdır. 'She' ve 'he' için 'wants to' olur.","examples":["I want to go to the beach.","She wants to swim.","We want to see dolphins.","Do you want to come?"]},"questions":[{"q":"Where does Ela want to go?","a":"To the beach."},{"q":"What does Ela's dad tell her not to forget?","a":"Her sun cream."},{"q":"What did Ela see on the boat trip?","a":"Dolphins."}],"quiz":[{"q":"I ___ to swim in the sea.","o":["want","wants","wanting"],"a":0,"why":"'I' ile 'want' kullanılır."},{"q":"A place to sleep on holiday is a ___.","o":["beach","hotel","trip"],"a":1,"why":"Otel, tatilde kalınan yerdir."},{"q":"Ela builds a ___ on the beach.","o":["sun cream","mountain","sandcastle"],"a":2,"why":""},{"q":"What do you put on your skin in the sun?","o":["sun cream","swimming pool","mountain"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I want to go to the beach.","cue":"mountains","answer":"I want to go to the mountains."},{"type":"Dönüştürme","prompt":"She wants to swim.","cue":"negative","answer":"She doesn't want to swim."},{"type":"Soru yap","prompt":"They want to visit the castle.","cue":"Do they…?","answer":"Do they want to visit the castle?"}],"sounds":[{"focus":"/aʊ/","tr":"Bu iki sesli harf tek bir hareket olarak söylenir: 'a' sesinden başla ve 'u' sesine doğru kay. Dudaklarını sonda hafifçe yuvarla ve sesi bölme.","pairs":["how / ho","now / no","down / don"]}],"mission":{"brief":"Arkadaşın Leo ile bir tatil planı yapıyorsun. Leo'nun tatilde nereye gitmek istediğini ve ne yapmak istediğini öğrenip ortak bir karar almalısın.","persona":"Leo, a 10-year-old who loves animals. At first he only talks about the beach. Hidden fact: he secretly wants to go to the zoo, and he only mentions it if asked good open questions about what he likes doing on holiday. Friendly, short sentences, enthusiastic.","goal":"Leo'nun en sevdiği etkinliği öğren ve 'I want to…' kalıbıyla iki öneri yap.","opener":"Hi! Are you going on holiday this summer? Where do you want to go?"}},"KS2-013":{"objectives":["Hayvanların nerede yaşadığını İngilizce söylemek","Üçüncü tekil kişi için fiile '-s' eklemek","Evcil hayvanları ve yaşam alanlarını kısaca anlatmak"],"dialogues":[{"title":"Where do they live?","setting":"Fen dersinde öğretmen, hayvanların nerede yaşadığını soruyor.","lines":[{"s":"Teacher","en":"Ela, where does a fox live?","tr":"Ela, tilki nerede yaşar?"},{"s":"Ela","en":"A fox lives in a den, under the ground.","tr":"Tilki, yerin altındaki bir ininde yaşar."},{"s":"Teacher","en":"Correct! And where does a bird live?","tr":"Doğru! Peki bir kuş nerede yaşar?"},{"s":"Mert","en":"A bird lives in a nest, in a tree.","tr":"Bir kuş, bir ağaçta, yuvasında yaşar."},{"s":"Teacher","en":"Excellent, Mert! Ela, what about a bee?","tr":"Harika, Mert! Ela, peki bir arı?"},{"s":"Ela","en":"A bee lives in a hive. It makes honey!","tr":"Arı bir kovanda yaşar. Bal yapar!"}]},{"title":"At the zoo","setting":"Hayvanat bahçesinde Leo ve babası aslanın önünde duruyor.","lines":[{"s":"Leo","en":"Look! The lion is sleeping.","tr":"Bak! Aslan uyuyor."},{"s":"Dad","en":"Yes. Lions often live in groups called prides.","tr":"Evet. Aslanlar genellikle 'pride' denen gruplar halinde yaşar."},{"s":"Leo","en":"Do lions live in the forest?","tr":"Aslanlar ormanda mı yaşar?"},{"s":"Dad","en":"Not really. They live on the grassland in Africa.","tr":"Pek sayılmaz. Afrika'daki otlak alanlarda yaşarlar."},{"s":"Leo","en":"Wow! Next, I want to see a penguin.","tr":"Vay! Sırada bir penguen görmek istiyorum."},{"s":"Dad","en":"Good idea. Penguins live near the sea.","tr":"İyi fikir. Penguenler denizin yakınında yaşar."}]},{"title":"Our pets","setting":"Teneffüste Ela ve Mert evcil hayvanlarını anlatıyor.","lines":[{"s":"Mert","en":"Do you have a pet, Ela?","tr":"Evcil hayvanın var mı, Ela?"},{"s":"Ela","en":"Yes! I have a rabbit. It lives in a cage.","tr":"Evet! Bir tavşanım var. Kafeste yaşıyor."},{"s":"Mert","en":"What does it eat?","tr":"Ne yer?"},{"s":"Ela","en":"It eats carrots and grass.","tr":"Havuç ve ot yer."},{"s":"Mert","en":"I have a dog. It lives with us in the house.","tr":"Benim bir köpeğim var. Bizimle evde yaşıyor."},{"s":"Ela","en":"Lucky you! Dogs are very friendly.","tr":"Şanslısın! Köpekler çok arkadaş canlısıdır."}]}],"reading":{"title":"Homes in nature","paras":[{"en":"Animals live in many different homes. A fox lives in a den under the ground. Birds build nests in trees. Bees live together in a hive and make honey. Some animals, like dogs and rabbits, live with people. Every animal needs a safe place to sleep and rest. Pet owners must look after them every day.","tr":"Hayvanlar pek çok farklı yerde yaşar. Tilki, yerin altındaki bir inde yaşar. Kuşlar ağaçlara yuva yapar. Arılar birlikte bir kovanda yaşar ve bal yapar. Köpekler ve tavşanlar gibi bazı hayvanlar insanlarla birlikte yaşar. Her hayvanın uyuyabileceği ve dinlenebileceği güvenli bir yere ihtiyacı vardır. Evcil hayvan sahipleri onlara her gün bakmalıdır."}]},"vocab":[{"w":"fox","ipa":"/fɒks/","pos":"🦊","tr":"tilki","ex":"The fox is fast.","exTr":"Tilki hızlıdır."},{"w":"den","ipa":"/den/","pos":"🕳️","tr":"in (hayvan yuvası)","ex":"A fox lives in a den.","exTr":"Tilki bir inde yaşar."},{"w":"nest","ipa":"/nest/","pos":"🪺","tr":"yuva","ex":"The bird has a nest.","exTr":"Kuşun bir yuvası var."},{"w":"hive","ipa":"/haɪv/","pos":"🍯","tr":"kovan","ex":"Bees live in a hive.","exTr":"Arılar bir kovanda yaşar."},{"w":"bee","ipa":"/biː/","pos":"🐝","tr":"arı","ex":"The bee makes honey.","exTr":"Arı bal yapar."},{"w":"lion","ipa":"/ˈlaɪən/","pos":"🦁","tr":"aslan","ex":"The lion is sleeping.","exTr":"Aslan uyuyor."},{"w":"rabbit","ipa":"/ˈræbɪt/","pos":"🐰","tr":"tavşan","ex":"My rabbit eats carrots.","exTr":"Tavşanım havuç yer."},{"w":"grass","ipa":"/ɡrɑːs/","pos":"🌿","tr":"ot, çimen","ex":"The rabbit eats grass.","exTr":"Tavşan ot yer."}],"chunks":[{"en":"Where does… live?","tr":"… nerede yaşar?"},{"en":"It lives in a…","tr":"O, bir … içinde yaşar."},{"en":"Lucky you!","tr":"Şanslısın!"},{"en":"Every animal needs a safe home.","tr":"Her hayvanın güvenli bir evi olmalı."}],"grammar":{"point":"Third person -s (lives, eats)","tr":"Tek bir kişi ya da hayvan hakkında konuşurken fiilin sonuna '-s' eklenir: 'It lives', 'She eats'. Türkçede fiil ekleri kişiye göre değişir; İngilizcede ise sadece 'he', 'she' ve 'it' için '-s' kullanılır.","examples":["A fox lives in a den.","It eats grass.","She has a rabbit.","The bee makes honey."]},"questions":[{"q":"Where does a bird live?","a":"In a nest, in a tree."},{"q":"What does Ela's rabbit eat?","a":"Carrots and grass."},{"q":"What do bees make?","a":"Honey."}],"quiz":[{"q":"A bee lives in a ___.","o":["hive","den","nest"],"a":0,"why":""},{"q":"A fox lives in a ___ under the ground.","o":["hive","cage","den"],"a":2,"why":""},{"q":"It ___ carrots. (Tavşanı)","o":["eating","eats","to eat"],"a":1,"why":"Tek kişi/hayvan için fiile '-s' eklenir."},{"q":"Lions live in groups called ___.","o":["prides","nests","hives"],"a":0,"why":"'Pride' aslan grubu demektir."}],"drills":[{"type":"Yerine koyma","prompt":"A bird lives in a nest.","cue":"bee / hive","answer":"A bee lives in a hive."},{"type":"Dönüştürme","prompt":"The rabbit eats grass.","cue":"They","answer":"They eat grass."},{"type":"Soru yap","prompt":"The fox lives in a den.","cue":"Where…?","answer":"Where does the fox live?"}],"sounds":[{"focus":"/aɪ/","tr":"Türkçedeki 'ay' kelimesine benzer, ama 'a' sesinden başlayıp 'i' sesine doğru kayarak bitirilir. 'Hive' kelimesinde ağzını geniş aç, sonra 'i'ye geç.","pairs":["bite / bit","fight / fit","ride / rid"]}],"mission":{"brief":"Arkadaşın Leo ile bir hayvan tahmin oyunu oynayacaksın. Leo gizli bir hayvan düşünecek; sen 'Where does it live?' ve 'Does it eat…?' gibi sorular sorarak hayvanı bulmaya çalışmalısın.","persona":"Leo, a 10-year-old who loves animals. He thinks of a secret animal: a turtle he keeps at home in a tank. He only mentions it if asked about pets or where his animal lives. Short, simple sentences; he answers only the question asked.","goal":"Leo'nun düşündüğü hayvanı ve nerede yaşadığını 'Where does it live?' sorusuyla öğren.","opener":"Hi! I'm thinking of an animal. Ask me questions to guess it!"}},"KS2-014":{"objectives":["Güneş sistemindeki gezegenleri İngilizce saymak","'There is / There are' kalıbını kullanmak","Uzayla ilgili basit sorular sormak"],"dialogues":[{"title":"Look at the Moon","setting":"Gece bahçede Ali ve Elif gökyüzüne bakıyor.","lines":[{"s":"Ali","en":"Look! The Moon is very big tonight.","tr":"Bak! Ay bu gece çok büyük."},{"s":"Elif","en":"Yes! It is bright and white.","tr":"Evet! Parlak ve beyaz."},{"s":"Ali","en":"Our planet is called Earth. We live on Earth.","tr":"Gezegenimizin adı Dünya. Biz Dünya'da yaşıyoruz."},{"s":"Elif","en":"Is Mars a planet too?","tr":"Mars da bir gezegen mi?"},{"s":"Ali","en":"Yes, Mars is a planet. It is red and cold.","tr":"Evet, Mars bir gezegen. Kırmızı ve soğuk."},{"s":"Elif","en":"Wow! One day I want to go to space.","tr":"Vay! Bir gün uzaya gitmek istiyorum."}]},{"title":"Star-gazing with Dad","setting":"Baba, çocuklara teleskopla gökyüzünü gösteriyor.","lines":[{"s":"Dad","en":"Let's look at the stars with the telescope.","tr":"Haydi teleskopla yıldızlara bakalım."},{"s":"Elif","en":"The Sun is a star, right?","tr":"Güneş bir yıldız, değil mi?"},{"s":"Dad","en":"Yes! It is the closest star to Earth.","tr":"Evet! Dünya'ya en yakın yıldız odur."},{"s":"Ali","en":"How many planets go around the Sun?","tr":"Güneş'in etrafında kaç gezegen dönüyor?"},{"s":"Dad","en":"There are eight planets. Jupiter is the biggest.","tr":"Sekiz gezegen var. Jüpiter en büyüğü."},{"s":"Ali","en":"Is Saturn the one with rings?","tr":"Halkaları olan Satürn mü?"},{"s":"Dad","en":"Yes, Saturn has beautiful rings.","tr":"Evet, Satürn'ün çok güzel halkaları var."}]},{"title":"Astronaut dream","setting":"Sınıfta öğretmen çocuklara gelecekteki hayallerini soruyor.","lines":[{"s":"Teacher","en":"Who wants to be an astronaut?","tr":"Kim astronot olmak ister?"},{"s":"Elif","en":"Me! I want to fly a rocket.","tr":"Ben! Bir roketi uçurmak istiyorum."},{"s":"Ali","en":"I want to walk on the Moon.","tr":"Ben Ay'da yürümek istiyorum."},{"s":"Teacher","en":"Great! Astronauts wear special suits.","tr":"Harika! Astronotlar özel kıyafetler giyer."},{"s":"Elif","en":"Can they eat in space?","tr":"Uzayda yemek yiyebilirler mi?"},{"s":"Teacher","en":"Yes, they eat special food.","tr":"Evet, özel yiyecekler yerler."}]}],"reading":{"title":"Our solar system","paras":[{"en":"Our solar system is a family of planets. The Sun is at the centre. Eight planets go around the Sun. Earth is our home. It is the third planet from the Sun. Jupiter is the biggest planet. Saturn has beautiful rings. Mars is red and cold. Look up at night and you can see many stars.","tr":"Güneş sistemimiz gezegenlerden oluşan bir aile. Güneş ortada. Sekiz gezegen Güneş'in etrafında döner. Dünya bizim evimiz. Güneş'ten itibaren üçüncü gezegendir. Jüpiter en büyük gezegen. Satürn'ün çok güzel halkaları var. Mars kırmızı ve soğuk. Gece gökyüzüne bak, birçok yıldız görebilirsin."}]},"vocab":[{"w":"planet","ipa":"/ˈplænɪt/","pos":"🪐","tr":"gezegen","ex":"Earth is a planet.","exTr":"Dünya bir gezegendir."},{"w":"star","ipa":"/stɑː/","pos":"⭐","tr":"yıldız","ex":"The Sun is a star.","exTr":"Güneş bir yıldızdır."},{"w":"Moon","ipa":"/muːn/","pos":"🌙","tr":"Ay","ex":"The Moon is very big tonight.","exTr":"Ay bu gece çok büyük."},{"w":"Sun","ipa":"/sʌn/","pos":"☀️","tr":"Güneş","ex":"The Sun is bright.","exTr":"Güneş parlak."},{"w":"Earth","ipa":"/ɜːθ/","pos":"🌍","tr":"Dünya","ex":"We live on Earth.","exTr":"Biz Dünya'da yaşıyoruz."},{"w":"rocket","ipa":"/ˈrɒkɪt/","pos":"🚀","tr":"roket","ex":"I want to fly a rocket.","exTr":"Bir roketi uçurmak istiyorum."},{"w":"telescope","ipa":"/ˈtelɪskəʊp/","pos":"🔭","tr":"teleskop","ex":"Let's look at the stars with a telescope.","exTr":"Yıldızlara teleskopla bakalım."},{"w":"astronaut","ipa":"/ˈæstrənɔːt/","pos":"👨‍🚀","tr":"astronot","ex":"Astronauts wear special suits.","exTr":"Astronotlar özel kıyafetler giyer."}],"chunks":[{"en":"Look at the…!","tr":"…'a bak!"},{"en":"Is … a planet?","tr":"… bir gezegen mi?"},{"en":"I want to…","tr":"… istiyorum."},{"en":"Let's look at…","tr":"…'a bakalım."}],"grammar":{"point":"There is / There are","tr":"Tek bir şey olduğunda 'there is', birden fazla şey olduğunda 'there are' kullanılır. İkisi de Türkçedeki 'var' kelimesine karşılık gelir.","examples":["There is one Moon.","There are eight planets.","There is a red planet.","There are many stars."]},"questions":[{"q":"How many planets go around the Sun?","a":"Eight planets."},{"q":"Which planet has beautiful rings?","a":"Saturn."},{"q":"Where do we live?","a":"On Earth."}],"quiz":[{"q":"Which planet do we live on?","o":["Mars","Earth","Jupiter"],"a":1,"why":"Biz Dünya'da yaşıyoruz."},{"q":"Saturn has beautiful ___.","o":["rings","rockets","stars"],"a":0,"why":""},{"q":"There ___ eight planets.","o":["is","are","am"],"a":1,"why":"Birden fazla şey olduğu için 'are' kullanılır."},{"q":"What do we use to look at stars?","o":["a rocket","a planet","a telescope"],"a":2,"why":"Yıldızlara teleskopla bakılır."}],"drills":[{"type":"Yerine koyma","prompt":"Mars is red and cold.","cue":"Earth / blue and green","answer":"Earth is blue and green."},{"type":"Soru yap","prompt":"There are eight planets.","cue":"How many…?","answer":"How many planets are there?"},{"type":"Genişletme","prompt":"Saturn has rings.","cue":"+ beautiful","answer":"Saturn has beautiful rings."}],"sounds":[{"focus":"/ɜː/","tr":"Türkçede bu ses yok. Dudaklarını yuvarlamadan, dilini ağzının ortasında tutarak uzun bir 'ö' sesi çıkar.","pairs":["Earth / art","first / fast","bird / bard"]}],"mission":{"brief":"Oyun: Uzaylı arkadaşın Robo ile konuşacaksın. Ona Güneş sistemini İngilizce anlat ve sorular sorarak onun en sevdiği gezegeni öğren.","persona":"Robo, a friendly alien boy visiting Earth. Uses very short, simple sentences and asks one question at a time. Hidden fact: his favourite planet is Saturn, because he collects ring-shaped toys. He only says so if the child asks about his favourite planet or what he likes to collect.","goal":"Robo'ya en az üç gezegen hakkında İngilizce bilgi ver ve en sevdiği gezegenini öğren.","opener":"Hi! I'm Robo, from a faraway planet. Can you tell me about the planets?"}},"KS2-015":{"objectives":["Dinozorlarla ilgili kelimeleri İngilizce kullanmak","Geçmiş zamanda 'was' ve 'were' kullanmak","Bir fosil hakkında basit bilgi vermek"],"dialogues":[{"title":"At the museum","setting":"Müzede Ali ve babası dev bir dinozor iskeletinin önünde duruyor.","lines":[{"s":"Ali","en":"Wow! Look at this big dinosaur!","tr":"Vay! Şu büyük dinozora bak!"},{"s":"Dad","en":"This is a T-Rex. It is a carnivore.","tr":"Bu bir T-Rex. Etçil bir hayvan."},{"s":"Ali","en":"What does carnivore mean?","tr":"Carnivore ne demek?"},{"s":"Dad","en":"It eats meat. Look at its sharp teeth!","tr":"Et yer. Şu keskin dişlerine bak!"},{"s":"Ali","en":"Its teeth were very sharp, right?","tr":"Dişleri çok keskindi, değil mi?"},{"s":"Dad","en":"Yes. Let's read the sign together.","tr":"Evet. Hadi tabelayı birlikte okuyalım."}]},{"title":"Digging for fossils","setting":"Kumlu bir alanda Elif ve Ali fosil arıyor.","lines":[{"s":"Elif","en":"I found a bone! Is it a dinosaur bone?","tr":"Bir kemik buldum! Dinozor kemiği mi acaba?"},{"s":"Ali","en":"Maybe! Let's dig carefully.","tr":"Belki! Dikkatlice kazalım."},{"s":"Elif","en":"This is a fossil. It is very old.","tr":"Bu bir fosil. Çok eski."},{"s":"Ali","en":"Wow! Dinosaurs lived millions of years ago.","tr":"Vay! Dinozorlar milyonlarca yıl önce yaşadı."},{"s":"Elif","en":"I want to be a scientist one day!","tr":"Bir gün bilim insanı olmak istiyorum!"},{"s":"Ali","en":"Me too. Let's show it to the museum.","tr":"Ben de. Hadi müzeye gösterelim."}]},{"title":"Dinosaur eggs","setting":"Sınıfta öğretmen bir dinozor yumurtası resmi gösteriyor.","lines":[{"s":"Teacher","en":"Look at this picture. What is it?","tr":"Şu resme bak. Bu ne?"},{"s":"Elif","en":"It's an egg! Is it a dinosaur egg?","tr":"Bu bir yumurta! Dinozor yumurtası mı?"},{"s":"Teacher","en":"Yes! Dinosaurs laid eggs.","tr":"Evet! Dinozorlar yumurta yumurtlardı."},{"s":"Ali","en":"How big were the eggs?","tr":"Yumurtalar ne kadar büyüktü?"},{"s":"Teacher","en":"Some were as big as a football.","tr":"Bazıları bir futbol topu kadar büyüktü."},{"s":"Ali","en":"Cool! I want to see one.","tr":"Harika! Bir tane görmek istiyorum."}]}],"reading":{"title":"What is a fossil?","paras":[{"en":"Dinosaurs lived a long time ago. Some dinosaurs ate plants. Others ate meat. Scientists learn about dinosaurs from fossils. A fossil can be a bone, a tooth or an egg. People dig in the ground to find them. Then they take the fossils to a museum. Visitors can see the bones. Dinosaurs are very interesting!","tr":"Dinozorlar çok uzun zaman önce yaşadı. Bazıları bitki yerdi. Diğerleri et yerdi. Bilim insanları dinozorlar hakkında fosillerden bilgi öğrenir. Bir fosil bir kemik, bir diş ya da bir yumurta olabilir. İnsanlar fosilleri bulmak için yerin altını kazar. Sonra fosilleri bir müzeye götürürler. Ziyaretçiler kemikleri görebilir. Dinozorlar çok ilginç!"}]},"vocab":[{"w":"dinosaur","ipa":"/ˈdaɪnəsɔː/","pos":"🦕","tr":"dinozor","ex":"Dinosaurs lived a long time ago.","exTr":"Dinozorlar çok uzun zaman önce yaşadı."},{"w":"egg","ipa":"/eɡ/","pos":"🥚","tr":"yumurta","ex":"The egg is as big as a football.","exTr":"Yumurta bir futbol topu kadar büyük."},{"w":"tooth","ipa":"/tuːθ/","pos":"🦷","tr":"diş","ex":"This tooth is very sharp.","exTr":"Bu diş çok keskin."},{"w":"bone","ipa":"/bəʊn/","pos":"🦴","tr":"kemik","ex":"I found a bone in the sand.","exTr":"Kumda bir kemik buldum."},{"w":"fossil","ipa":"/ˈfɒsl/","pos":"🪨","tr":"fosil","ex":"This fossil is very old.","exTr":"Bu fosil çok eski."},{"w":"dig","ipa":"/dɪɡ/","pos":"⛏️","tr":"kazmak","ex":"Let's dig carefully.","exTr":"Dikkatlice kazalım."},{"w":"museum","ipa":"/mjuːˈziːəm/","pos":"🏛️","tr":"müze","ex":"The museum has a big dinosaur.","exTr":"Müzede dev bir dinozor var."},{"w":"carnivore","ipa":"/ˈkɑːnɪvɔː/","pos":"🥩","tr":"etçil hayvan","ex":"A lion is a carnivore.","exTr":"Aslan etçil bir hayvandır."}],"chunks":[{"en":"Look at this…!","tr":"Şu … 'a bak!"},{"en":"Let's … carefully.","tr":"… dikkatlice … yapalım."},{"en":"I want to be a…","tr":"… olmak istiyorum."},{"en":"What does … mean?","tr":"… ne demek?"}],"grammar":{"point":"Past of 'be': was / were","tr":"Geçmişte bir şeyin nasıl olduğunu anlatmak için 'was' ve 'were' kullanılır. 'Was' tekil, 'were' çoğul şeyler içindir ve Türkçedeki '-di' ekine karşılık gelir.","examples":["The dinosaur was very big.","The eggs were small.","The bone was very old.","The teeth were very sharp."]},"questions":[{"q":"What do carnivores eat?","a":"They eat meat."},{"q":"What can a fossil be?","a":"A bone, a tooth or an egg."},{"q":"Where do people dig to find fossils?","a":"In the ground."}],"quiz":[{"q":"Dinosaurs that eat meat are called ___.","o":["carnivores","fossils","museums"],"a":0,"why":"Et yiyen dinozorlara 'carnivore' denir."},{"q":"Where can you see old bones?","o":["in a kitchen","in a supermarket","in a museum"],"a":2,"why":""},{"q":"The dinosaur ___ very big.","o":["were","was","is"],"a":1,"why":"Tekil bir şey için 'was' kullanılır."},{"q":"People ___ in the ground to find fossils.","o":["eat","fly","dig"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"This is a fossil. It is very old.","cue":"bone","answer":"This is a bone. It is very old."},{"type":"Soru yap","prompt":"Dinosaurs lived a long time ago.","cue":"When…?","answer":"When did dinosaurs live?"},{"type":"Genişletme","prompt":"Carnivores eat meat.","cue":"+ with sharp teeth","answer":"Carnivores eat meat with sharp teeth."}],"sounds":[{"focus":"/θ/","tr":"Türkçede bu ses yok. Dilinin ucunu üst dişlerinin arasına koy ve hafifçe üfle; 't' ya da 's' gibi çıkmasın.","pairs":["tooth / two","thick / sick","three / tree"]}],"mission":{"brief":"Oyun: Dinozor uzmanı Dr. Dino'nun asistanısın. Ona dinozorlar hakkında İngilizce sorular sor ve sorarak onun sakladığı en iyi buluşunu öğren.","persona":"Dr. Dino, a friendly dinosaur scientist who speaks slowly and cheerfully. Uses short sentences and asks the child one question at a time. Hidden fact: last summer she found a dinosaur tooth in her garden, but she only talks about it when the child asks about her best discovery.","goal":"Dr. Dino'ya üç İngilizce soru sor ve onun en iyi buluşunun ne olduğunu öğren.","opener":"Hello! I'm Dr. Dino. I study dinosaurs. What do you want to know?"}},"KS2-016":{"objectives":["Bir icadı İngilizce tanıtmak","Geçmiş zaman için '-ed' kalıbını kullanmak","Teknoloji hakkında kısa bir fikir paylaşmak"],"dialogues":[{"title":"Science fair","setting":"Okul bilim fuarında Ali, yaptığı robotu Elif'e gösteriyor.","lines":[{"s":"Ali","en":"Look! I made a new invention. It's a robot.","tr":"Bak! Yeni bir icat yaptım. Bu bir robot."},{"s":"Elif","en":"Wow! What can it do?","tr":"Vay! Ne yapabiliyor?"},{"s":"Ali","en":"It can carry my bag to school.","tr":"Okula çantamı taşıyabiliyor."},{"s":"Elif","en":"That's a great idea! Was it hard to build?","tr":"Harika bir fikir! Yapmak zor muydu?"},{"s":"Ali","en":"A little. My dad helped me with the battery.","tr":"Biraz. Babam pil konusunda bana yardım etti."},{"s":"Elif","en":"Cool! I invented a clock that plays music.","tr":"Harika! Müzik çalan bir saat icat ettim."}]},{"title":"Who invented the wheel?","setting":"Kütüphanede Elif ve Ali makinelerle ilgili bir kitap okuyor.","lines":[{"s":"Elif","en":"Who invented the wheel?","tr":"Tekerleği kim icat etti?"},{"s":"Ali","en":"Nobody knows. It was many years ago.","tr":"Kimse bilmiyor. Çok yıllar önceydi."},{"s":"Elif","en":"Wheels are very useful, right?","tr":"Tekerlekler çok faydalı, değil mi?"},{"s":"Ali","en":"Yes! Wheels help us move heavy things.","tr":"Evet! Tekerlekler ağır şeyleri taşımamıza yardım eder."},{"s":"Elif","en":"Look at this book. It's about machines.","tr":"Şu kitaba bak. Makineler hakkında."},{"s":"Ali","en":"Great! Machines make work easier.","tr":"Harika! Makineler işi kolaylaştırır."}]},{"title":"A useful idea","setting":"Sınıfta öğretmen çocuklara her gün kullandıkları icatları soruyor.","lines":[{"s":"Teacher","en":"What invention do you use every day?","tr":"Her gün hangi icadı kullanıyorsun?"},{"s":"Elif","en":"My phone! It's very useful.","tr":"Telefonum! Çok faydalı."},{"s":"Ali","en":"I use the light bulb. It's bright at night.","tr":"Ben ampulü kullanıyorum. Geceleri parlak oluyor."},{"s":"Teacher","en":"Very good. Every invention starts with an idea.","tr":"Çok iyi. Her icat bir fikirle başlar."},{"s":"Elif","en":"I have an idea! A solar bag.","tr":"Bir fikrim var! Güneş enerjili bir çanta."},{"s":"Teacher","en":"Tell me more about it.","tr":"Bana bunun hakkında daha fazla anlat."}]}],"reading":{"title":"Ideas that change the world","paras":[{"en":"Inventions help people every day. Long ago, people had no electric lights. Then someone invented the light bulb. Today we use machines and robots at home and at work. Batteries store energy so phones and toys can work. Some inventions start with a simple idea. Ask yourself: How can I make life easier? Maybe your idea will be the next big invention!","tr":"İcatlar her gün insanlara yardım eder. Uzun zaman önce insanların elektrikli ışığı yoktu. Sonra biri ampulü icat etti. Bugün evlerimizde ve işyerlerimizde makineler ve robotlar kullanıyoruz. Piller enerjiyi depolar, böylece telefonlar ve oyuncaklar çalışabilir. Bazı icatlar basit bir fikirle başlar. Kendine sor: Hayatı nasıl daha kolay yapabilirim? Belki senin fikrin bir sonraki büyük icat olacak!"}]},"vocab":[{"w":"invention","ipa":"/ɪnˈvenʃn/","pos":"💡","tr":"icat","ex":"Every invention starts with an idea.","exTr":"Her icat bir fikirle başlar."},{"w":"invent","ipa":"/ɪnˈvent/","pos":"🛠️","tr":"icat etmek","ex":"Who invented the telephone?","exTr":"Telefonu kim icat etti?"},{"w":"wheel","ipa":"/wiːl/","pos":"🛞","tr":"tekerlek","ex":"The wheel helps us move heavy things.","exTr":"Tekerlek ağır şeyleri taşımamıza yardım eder."},{"w":"machine","ipa":"/məˈʃiːn/","pos":"⚙️","tr":"makine","ex":"This machine washes clothes.","exTr":"Bu makine çamaşır yıkar."},{"w":"robot","ipa":"/ˈrəʊbɒt/","pos":"🤖","tr":"robot","ex":"My robot can carry my bag.","exTr":"Robotum çantamı taşıyabilir."},{"w":"battery","ipa":"/ˈbætri/","pos":"🔋","tr":"pil","ex":"The battery is full.","exTr":"Pil dolu."},{"w":"useful","ipa":"/ˈjuːsfl/","pos":"👍","tr":"faydalı","ex":"A phone is very useful.","exTr":"Telefon çok faydalı."},{"w":"idea","ipa":"/aɪˈdɪə/","pos":"💭","tr":"fikir","ex":"I have a good idea!","exTr":"İyi bir fikrim var!"}],"chunks":[{"en":"I have an idea!","tr":"Bir fikrim var!"},{"en":"Tell me more about it.","tr":"Bu hakkında bana daha fazla anlat."},{"en":"Every … starts with…","tr":"Her … … ile başlar."},{"en":"Who invented…?","tr":"… kim icat etti?"}],"grammar":{"point":"Simple past: regular verbs (-ed)","tr":"Geçmişte olan bir şeyi anlatmak için fiile '-ed' eklenir. Türkçedeki '-di' ekine benzer, ama İngilizcede bu ek her özne için aynı kalır.","examples":["I invented a clock.","She helped me with the battery.","They used a robot.","We worked together."]},"questions":[{"q":"What is Ali's new invention?","a":"A robot."},{"q":"What can Ali's robot do?","a":"It can carry Ali's bag to school."},{"q":"Why are machines good?","a":"They make work easier."}],"quiz":[{"q":"What is Ali's new invention?","o":["a clock","a robot","a wheel"],"a":1,"why":"Ali 'It's a robot.' diyor."},{"q":"The past form of 'help' is ___.","o":["helps","helping","helped"],"a":2,"why":"Geçmiş zaman için fiile '-ed' eklenir."},{"q":"A ___ stores energy.","o":["battery","wheel","robot"],"a":0,"why":""},{"q":"Machines make work ___.","o":["harder","easier","heavier"],"a":1,"why":"Makineler işi kolaylaştırır."}],"drills":[{"type":"Yerine koyma","prompt":"It can carry my bag to school.","cue":"wash the dishes / at home","answer":"It can wash the dishes at home."},{"type":"Dönüştürme","prompt":"Machines make work easier.","cue":"Negative: do not","answer":"Machines do not make work easier."},{"type":"Genişletme","prompt":"I invented a clock.","cue":"+ that plays music","answer":"I invented a clock that plays music."}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Kısa /ɪ/ sesinde dudaklar gevşek kalır. Uzun /iː/ için dudakları yana gererek 'i' sesini uzat.","pairs":["ship / sheep","bit / beat","sit / seat"]}],"mission":{"brief":"Oyun: Profesör Bolt'un laboratuvarındasın. Ona bir icadının ne işe yaradığını İngilizce anlat ve sorular sorarak onun gizli sırrını öğren.","persona":"Professor Bolt, a cheerful inventor who builds silly machines. Speaks in short, simple sentences and asks one question at a time. Hidden fact: he has already built a flying bicycle, but he is too shy to tell anyone. He only admits it if the child asks what his biggest invention is.","goal":"Profesör Bolt'a bir icadını İngilizce anlat ve onun gizli sırrını öğren.","opener":"Hello, young inventor! I'm Professor Bolt. What is your best idea?"}},"KS2-017":{"objectives":["Video oyunlarıyla ilgili kelimeleri İngilizce kullanmak","'Let's' ile birlikte bir şey önermek","Bir oyuncuya kısa sorular sormak"],"dialogues":[{"title":"Let's play!","setting":"Ali ve Elif evde oyun oynamaya hazırlanıyor.","lines":[{"s":"Ali","en":"Do you want to play a game with me?","tr":"Benimle bir oyun oynamak ister misin?"},{"s":"Elif","en":"Yes! Which game?","tr":"Evet! Hangi oyun?"},{"s":"Ali","en":"A racing game. You can be the red car.","tr":"Yarış oyunu. Kırmızı araba sen ol."},{"s":"Elif","en":"Great! Where is the controller?","tr":"Harika! Kumanda nerede?"},{"s":"Ali","en":"Here! Press the green button to start.","tr":"Burada! Başlamak için yeşil düğmeye bas."},{"s":"Elif","en":"What is my score?","tr":"Benim puanım ne?"},{"s":"Ali","en":"You have fifty points. Good job!","tr":"Elli puanın var. Aferin!"}]},{"title":"Team practice","setting":"Okul bahçesinde takım oyunu için hazırlık yapılıyor.","lines":[{"s":"Teacher","en":"Who wants to join the game team?","tr":"Oyun takımına kim katılmak ister?"},{"s":"Ali","en":"I do! Let's practice first.","tr":"Ben isterim! Önce çalışalım."},{"s":"Elif","en":"Can we practice every day?","tr":"Her gün çalışabilir miyiz?"},{"s":"Teacher","en":"Yes! Practice makes players better.","tr":"Evet! Çalışmak oyuncuları daha iyi yapar."},{"s":"Ali","en":"We want to win the game!","tr":"Oyunu kazanmak istiyoruz!"},{"s":"Teacher","en":"Good! Work together and be kind.","tr":"İyi! Birlikte çalışın ve nazik olun."}]},{"title":"One more level","setting":"Akşam olmuş. Anne, Ali'nin oyun süresi hakkında konuşuyor.","lines":[{"s":"Mum","en":"You played for two hours. Time for a break.","tr":"İki saat oynadın. Mola zamanı."},{"s":"Ali","en":"Just one more level, please!","tr":"Sadece bir bölüm daha, lütfen!"},{"s":"Mum","en":"No. Let's go outside and play football.","tr":"Hayır. Dışarı çıkıp futbol oynayalım."},{"s":"Elif","en":"Good idea, Mum! I want to play too.","tr":"Güzel fikir anne! Ben de oynamak istiyorum."},{"s":"Mum","en":"Good. Balance is important.","tr":"Güzel. Dengeli olmak önemli."},{"s":"Ali","en":"Okay, Mum. I'm sorry.","tr":"Tamam anne. Özür dilerim."}]}],"reading":{"title":"Playing video games","paras":[{"en":"Video games are fun. Many people play them at home or with friends. A player moves a character on the screen. Some games have levels, and each level is harder. You get points when you win, and the score shows how well you did. Playing with a team is great, because you can help each other. But remember to take breaks, go outside and move your body too!","tr":"Video oyunları çok eğlenceli. Birçok insan onları evde ya da arkadaşlarıyla oynar. Oyuncu ekrandaki bir karakteri hareket ettirir. Bazı oyunların bölümleri vardır ve her bölüm daha zordur. Kazandığında puan alırsın; skor ne kadar iyi yaptığını gösterir. Takımla oynamak harika, çünkü birbirinize yardım edebilirsiniz. Ama mola vermeyi unutma, dışarı çık ve vücudunu da hareket ettir!"}]},"vocab":[{"w":"game","ipa":"/ɡeɪm/","pos":"🎮","tr":"oyun","ex":"Let's play a game.","exTr":"Haydi bir oyun oynayalım."},{"w":"player","ipa":"/ˈpleɪə/","pos":"🧑‍🎮","tr":"oyuncu","ex":"The player moves the car.","exTr":"Oyuncu arabayı hareket ettiriyor."},{"w":"score","ipa":"/skɔː/","pos":"🏆","tr":"skor, puan","ex":"What is my score?","exTr":"Benim puanım ne?"},{"w":"level","ipa":"/ˈlevl/","pos":"🪜","tr":"bölüm, seviye","ex":"This level is hard.","exTr":"Bu bölüm zor."},{"w":"controller","ipa":"/kənˈtrəʊlə/","pos":"🕹️","tr":"kumanda","ex":"Press the button on the controller.","exTr":"Kumandadaki düğmeye bas."},{"w":"team","ipa":"/tiːm/","pos":"👥","tr":"takım","ex":"Our team wants to win.","exTr":"Takımımız kazanmak istiyor."},{"w":"win","ipa":"/wɪn/","pos":"🥇","tr":"kazanmak","ex":"We want to win!","exTr":"Kazanmak istiyoruz!"},{"w":"practice","ipa":"/ˈpræktɪs/","pos":"🔁","tr":"çalışmak, antrenman yapmak","ex":"Practice makes you better.","exTr":"Çalışmak seni daha iyi yapar."}],"chunks":[{"en":"Do you want to play…?","tr":"… oynamak ister misin?"},{"en":"Let's practice first.","tr":"Önce çalışalım."},{"en":"Just one more level, please!","tr":"Sadece bir bölüm daha, lütfen!"},{"en":"Work together.","tr":"Birlikte çalışın."}],"grammar":{"point":"Let's + verb (suggestions)","tr":"Birlikte bir şey yapmayı önermek için 'Let's' kullanılır. 'Let us' kelimelerinin kısaltmasıdır ve 'haydi … yapalım' anlamına gelir. 'Let's' sonrasında fiilin yalın hâli gelir.","examples":["Let's play a game.","Let's practice first.","Let's go outside.","Let's win together."]},"questions":[{"q":"What colour is Elif's car?","a":"Red."},{"q":"Why does Mum say no?","a":"Because Ali played for two hours."},{"q":"What do you get when you win?","a":"Points."}],"quiz":[{"q":"In the game, you use a ___ to press buttons.","o":["screen","controller","score"],"a":1,"why":"Düğmelere basmak için kumanda kullanılır."},{"q":"What is a team?","o":["a level in a game","a kind of screen","a group of players who work together"],"a":2,"why":"Takım, birlikte çalışan oyuncular grubudur."},{"q":"Let's ___ first.","o":["lose","practice","screen"],"a":1,"why":""},{"q":"You get ___ when you win.","o":["points","breaks","homework"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Let's practice first.","cue":"go outside","answer":"Let's go outside first."},{"type":"Dönüştürme","prompt":"You play for two hours.","cue":"Ali","answer":"Ali plays for two hours."},{"type":"Genişletme","prompt":"Work together.","cue":"+ to win the game","answer":"Work together to win the game."}],"sounds":[{"focus":"/ɔː/","tr":"Dudakları hafifçe yuvarlayıp uzun bir 'o' sesi çıkar. Türkçedeki kısa 'o' gibi kesme.","pairs":["short / shot","sport / spot","score / scar"]}],"mission":{"brief":"Oyun: Yeni arkadaşın Max video oyunlarını çok sever. Ona oyunlar hakkında sorular sor ve sorularla onun gerçek düşüncelerini öğren.","persona":"Max, a friendly 10-year-old gamer. Uses short sentences and cheerful words. Hidden fact: he is secretly nervous about losing, so he never plays online with strangers. He only admits this if the child asks how he feels about losing a game.","goal":"Max'e iki oyun hakkında İngilizce soru sor ve kaybetmekten neden çekindiğini öğren.","opener":"Hi! I'm Max. Do you like video games? What's your favourite game?"}},"KS2-018":{"objectives":["Bir sandviç yapma adımlarını İngilizce söylemek","Emir cümlelerini kullanmak","Bir tarifi sırayla anlatmak"],"dialogues":[{"title":"Lunch time","setting":"Mutfakta Elif, annesine öğle yemeği için sandviç yapmasında yardım ediyor.","lines":[{"s":"Mum","en":"Let's make a sandwich for your lunch, Elif.","tr":"Öğle yemeğin için bir sandviç yapalım Elif."},{"s":"Elif","en":"Yes! What do we need?","tr":"Evet! Neye ihtiyacımız var?"},{"s":"Mum","en":"First, take two slices of bread.","tr":"Önce iki dilim ekmek al."},{"s":"Elif","en":"Here they are! Can I add cheese?","tr":"İşte burada! Peynir ekleyebilir miyim?"},{"s":"Mum","en":"Of course. Put the cheese on the bread.","tr":"Tabii. Peyniri ekmeğin üstüne koy."},{"s":"Elif","en":"Done! It looks yummy.","tr":"Tamam! Çok lezzetli görünüyor."}]},{"title":"Fresh vegetables","setting":"Ali ve babası sebzeleri hazırlıyor.","lines":[{"s":"Dad","en":"Can you wash the tomato and the cucumber?","tr":"Domatesi ve salatalığı yıkayabilir misin?"},{"s":"Ali","en":"Sure. Where is the knife?","tr":"Tabii. Bıçak nerede?"},{"s":"Dad","en":"Be careful! Ask me if you need help.","tr":"Dikkatli ol! Yardıma ihtiyacın olursa bana sor."},{"s":"Ali","en":"Okay. Can you slice the tomato for me?","tr":"Tamam. Domatesi benim için dilimleyebilir misin?"},{"s":"Dad","en":"Yes, I'll slice it. Then you put it on the bread.","tr":"Evet, dilimlerim. Sonra sen onu ekmeğin üstüne koy."},{"s":"Ali","en":"Thanks, Dad! Let's eat soon.","tr":"Teşekkürler baba! Yakında yiyelim."}]},{"title":"Ready to eat","setting":"Ali sandviçini tabağa koymuş, Elif'e gösteriyor.","lines":[{"s":"Ali","en":"Look at my sandwich! It's on the plate.","tr":"Sandviçime bak! Tabağın üstünde."},{"s":"Elif","en":"Wow, it's very colourful!","tr":"Vay, çok renkli!"},{"s":"Ali","en":"Do you want to share it?","tr":"Onu benimle paylaşmak ister misin?"},{"s":"Elif","en":"Yes, please! I like tomato.","tr":"Evet lütfen! Domatesi severim."},{"s":"Ali","en":"Great! Let's eat together.","tr":"Harika! Birlikte yiyelim."},{"s":"Elif","en":"Thank you, Ali!","tr":"Teşekkürler Ali!"}]}],"reading":{"title":"How to make a sandwich","paras":[{"en":"Making a sandwich is easy. First, take two slices of bread and put them on a plate. Next, add cheese and some tomato slices. Cucumber is fresh, so add a few pieces too. Use a clean knife to cut the sandwich in half. Then eat it with a smile! Remember to wash your hands before you cook.","tr":"Sandviç yapmak çok kolay. Önce iki dilim ekmeği al ve bir tabağa koy. Sonra peynir ve birkaç dilim domates ekle. Salatalık taze, bu yüzden birkaç parça da ekle. Sandviçi ikiye bölmek için temiz bir bıçak kullan. Sonra gülümseyerek ye! Yemek hazırlamadan önce ellerini yıkamayı unutma."}]},"vocab":[{"w":"bread","ipa":"/bred/","pos":"🍞","tr":"ekmek","ex":"Put the bread on the plate.","exTr":"Ekmeği tabağa koy."},{"w":"cheese","ipa":"/tʃiːz/","pos":"🧀","tr":"peynir","ex":"I want cheese on my sandwich.","exTr":"Sandviçimin üstünde peynir istiyorum."},{"w":"tomato","ipa":"/təˈmɑːtəʊ/","pos":"🍅","tr":"domates","ex":"The tomato is red and fresh.","exTr":"Domates kırmızı ve taze."},{"w":"cucumber","ipa":"/ˈkjuːkʌmbə/","pos":"🥒","tr":"salatalık","ex":"Cucumber is green.","exTr":"Salatalık yeşildir."},{"w":"knife","ipa":"/naɪf/","pos":"🔪","tr":"bıçak","ex":"Use a clean knife.","exTr":"Temiz bir bıçak kullan."},{"w":"plate","ipa":"/pleɪt/","pos":"🍽️","tr":"tabak","ex":"Put the sandwich on the plate.","exTr":"Sandviçi tabağa koy."},{"w":"slice","ipa":"/slaɪs/","pos":"✂️","tr":"dilim, dilimlemek","ex":"Slice the bread, please.","exTr":"Lütfen ekmeği dilimle."},{"w":"sandwich","ipa":"/ˈsænwɪtʃ/","pos":"🥪","tr":"sandviç","ex":"I made a sandwich for lunch.","exTr":"Öğle yemeği için bir sandviç yaptım."}],"chunks":[{"en":"Let's make a…","tr":"… yapalım."},{"en":"Be careful!","tr":"Dikkatli ol!"},{"en":"Can I add…?","tr":"… ekleyebilir miyim?"},{"en":"Let's eat together.","tr":"Birlikte yiyelim."}],"grammar":{"point":"Imperatives (giving instructions)","tr":"Birine bir şey yapmasını söylemek için fiilin yalın hâli kullanılır; başına özne gelmez. Türkçedeki emir kipine benzer.","examples":["Take two slices of bread.","Put the cheese on the bread.","Be careful with the knife.","Wash your hands first."]},"questions":[{"q":"What do you need to do first?","a":"Take two slices of bread."},{"q":"What should you use to cut the sandwich?","a":"A clean knife."},{"q":"What should you do before you cook?","a":"Wash your hands."}],"quiz":[{"q":"Which word means 'ekmek'?","o":["cheese","plate","bread"],"a":2,"why":""},{"q":"___ your hands before you cook.","o":["Wash","Washing","Washed"],"a":0,"why":"Emir cümlesinde fiil yalın hâlde kullanılır."},{"q":"Put the sandwich ___ the plate.","o":["at","on","under"],"a":1,"why":"'On' bir yüzeyin üstünü anlatır."},{"q":"Which one is a vegetable?","o":["bread","cheese","cucumber"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Put the cheese on the bread.","cue":"tomato","answer":"Put the tomato on the bread."},{"type":"Dönüştürme","prompt":"Be careful with the knife.","cue":"Don't be…","answer":"Don't be careless with the knife."},{"type":"Genişletme","prompt":"Let's eat together.","cue":"+ in the garden","answer":"Let's eat together in the garden."}],"sounds":[{"focus":"/ʃ/","tr":"Dilini damağa yaklaştır, dudaklarını hafifçe öne uzat ve hava üfle. Türkçedeki 'ş' sesine benzer ama daha uzun ve yumuşak olsun.","pairs":["share / chair","wash / watch","fresh / fetch"]}],"mission":{"brief":"Oyun: Küçük bir kafede aşçı yardımcısısın. Chef Lucy'ye bir sandviç tarifini adım adım anlat ve sorular sorarak onun gizli malzemesini öğren.","persona":"Chef Lucy, a cheerful 10-year-old chef who runs a pretend café. Uses short, simple sentences and loves giving instructions. Hidden fact: her special secret ingredient is honey. She only reveals it if the child asks what makes her sandwiches special.","goal":"Chef Lucy'ye bir sandviç tarifini adım adım İngilizce anlat ve onun gizli malzemesini öğren.","opener":"Hi! Welcome to my little café. What sandwich would you like to make?"}},"KS2-019":{"objectives":["Okul kurallarını İngilizce anlatmak","'must' ve 'mustn't' kalıplarını kullanmak","Bir kuralın neden önemli olduğunu açıklamak"],"dialogues":[{"title":"Arriving late","setting":"Okul girişinde öğretmen, Ali'nin geç kalmasını konuşuyor.","lines":[{"s":"Teacher","en":"Good morning, Ali. You are late today.","tr":"Günaydın Ali. Bugün geç kaldın."},{"s":"Ali","en":"Sorry, Teacher. I missed the bus.","tr":"Üzgünüm öğretmenim. Otobüsü kaçırdım."},{"s":"Teacher","en":"Remember the rule: students must arrive on time.","tr":"Kuralı hatırla: öğrenciler zamanında gelmek zorunda."},{"s":"Ali","en":"I will be on time tomorrow.","tr":"Yarın vaktinde olacağım."},{"s":"Teacher","en":"Good. Now go to your classroom.","tr":"İyi. Şimdi sınıfına git."},{"s":"Ali","en":"Yes, Teacher!","tr":"Tamam öğretmenim!"}]},{"title":"Quiet in the library","setting":"Kütüphanede Elif ve Ali sessiz olmak zorunda.","lines":[{"s":"Elif","en":"Ali, you mustn't talk loudly here. This is the library.","tr":"Ali, burada yüksek sesle konuşmamalısın. Burası kütüphane."},{"s":"Ali","en":"Sorry! Can we talk outside?","tr":"Üzgünüm! Dışarıda konuşabilir miyiz?"},{"s":"Elif","en":"Yes. We must respect other people.","tr":"Evet. Diğer insanlara saygı göstermek zorundayız."},{"s":"Ali","en":"You're right. Let's go out.","tr":"Haklısın. Hadi dışarı çıkalım."},{"s":"Elif","en":"Good idea!","tr":"Güzel fikir!"}]},{"title":"Homework and uniform","setting":"Eve dönen Elif, annesiyle okul kurallarını konuşuyor.","lines":[{"s":"Mum","en":"Did you finish your homework?","tr":"Ödevini bitirdin mi?"},{"s":"Elif","en":"Not yet. I'll do it after dinner.","tr":"Henüz değil. Akşam yemeğinden sonra yapacağım."},{"s":"Mum","en":"Good. And your uniform? Is it ready?","tr":"İyi. Peki ya üniformanı? Hazır mı?"},{"s":"Elif","en":"Yes, it's in my bag.","tr":"Evet, çantamda."},{"s":"Mum","en":"You must wear your uniform every day.","tr":"Üniformanı her gün giymek zorundasın."},{"s":"Elif","en":"I know, Mum. It's the school rule.","tr":"Biliyorum anne. Okul kuralı bu."}]}],"reading":{"title":"Why we have rules","paras":[{"en":"Every school has rules. Rules keep students safe and help everyone learn. At our school, we wear a uniform and we arrive on time. We do not run in the classroom. When the class is quiet, we can listen to the teacher. In the lunch queue, we wait our turn and we say please and thank you. Respect is the most important rule of all.","tr":"Her okulun kuralları vardır. Kurallar öğrencileri güvende tutar ve herkesin öğrenmesine yardım eder. Okulumuzda üniforma giyeriz ve zamanında geliriz. Sınıfta koşmayız. Sınıf sessiz olduğunda öğretmeni dinleyebiliriz. Yemek kuyruğunda sıramızı bekler, 'lütfen' ve 'teşekkür ederim' deriz. Saygı, en önemli kuraldır."}]},"vocab":[{"w":"rule","ipa":"/ruːl/","pos":"📏","tr":"kural","ex":"This is an important rule.","exTr":"Bu önemli bir kural."},{"w":"homework","ipa":"/ˈhəʊmwɜːk/","pos":"📚","tr":"ev ödevi","ex":"I finished my homework.","exTr":"Ev ödevimi bitirdim."},{"w":"uniform","ipa":"/ˈjuːnɪfɔːm/","pos":"👕","tr":"üniforma","ex":"We wear a uniform at school.","exTr":"Okulda üniforma giyeriz."},{"w":"classroom","ipa":"/ˈklɑːsruːm/","pos":"🏫","tr":"sınıf","ex":"The classroom is quiet.","exTr":"Sınıf sessiz."},{"w":"quiet","ipa":"/ˈkwaɪət/","pos":"🤫","tr":"sessiz","ex":"Please be quiet.","exTr":"Lütfen sessiz ol."},{"w":"queue","ipa":"/kjuː/","pos":"🚶","tr":"sıra, kuyruk","ex":"Wait in the queue.","exTr":"Sırada bekle."},{"w":"respect","ipa":"/rɪˈspekt/","pos":"🙏","tr":"saygı","ex":"Respect is important.","exTr":"Saygı önemlidir."},{"w":"late","ipa":"/leɪt/","pos":"⏰","tr":"geç","ex":"Don't be late for school.","exTr":"Okula geç kalma."}],"chunks":[{"en":"We must…","tr":"… zorundayız."},{"en":"Remember the rule.","tr":"Kuralı hatırla."},{"en":"Sorry, I'm late.","tr":"Üzgünüm, geç kaldım."},{"en":"It's the school rule.","tr":"Okul kuralı bu."}],"grammar":{"point":"Must and mustn't (rules)","tr":"Kurallarda zorunluluk için 'must' kullanılır ve 'zorunda olmak' anlamına gelir. 'Mustn't' ise yapmaman gereken şeyler için kullanılır ve 'yapmamalısın' demektir.","examples":["We must wear a uniform.","You mustn't run in the classroom.","Students must arrive on time.","We mustn't talk loudly in the library."]},"questions":[{"q":"What must students wear?","a":"A uniform."},{"q":"What should we do in the lunch queue?","a":"We wait our turn."},{"q":"What is the most important rule?","a":"Respect."}],"quiz":[{"q":"We ___ run in the classroom.","o":["must","mustn't","is"],"a":1,"why":"Sınıfta koşmak yasak, bu yüzden 'mustn't' kullanılır."},{"q":"Which word means 'sıra'?","o":["rule","uniform","queue"],"a":2,"why":""},{"q":"Ali ___ late today.","o":["is","are","were"],"a":0,"why":""},{"q":"Respect means…","o":["to be loud","to forget the rules","to treat people kindly"],"a":2,"why":"Saygı, insanlara nazik ve değerli davranmaktır."}],"drills":[{"type":"Yerine koyma","prompt":"We must wear a uniform.","cue":"do our homework","answer":"We must do our homework."},{"type":"Dönüştürme","prompt":"Please be quiet in the library.","cue":"use 'must'","answer":"You must be quiet in the library."},{"type":"Genişletme","prompt":"Respect is the most important rule.","cue":"+ at our school","answer":"Respect is the most important rule at our school."}],"sounds":[{"focus":"/ɑː/ – /æ/","tr":"Türkçede tam karşılığı yok. /æ/ için ağzını geniş aç ve düz bir 'e' gibi söyle; /ɑː/ için dilini geri çek ve sesi uzat.","pairs":["park / pack","car / cat","far / fat"]}],"mission":{"brief":"Oyun: Okul müdürü Mrs Lin ile konuşuyorsun. Ona okuldaki bir kuralın neden önemli olduğunu anlat ve sorularla yeni kuralın ne olduğunu öğren.","persona":"Mrs Lin, a kind and friendly head teacher. Speaks in short, clear sentences and asks one question at a time. Hidden fact: the school is planning a new rule about recycling, but she only mentions it when the child asks what the school wants to change next.","goal":"Mrs Lin'e bir okul kuralının neden önemli olduğunu İngilizce anlat ve yeni kuralı öğren.","opener":"Hello! I'm Mrs Lin, the head teacher. What do you think is the most important school rule?"}},"KS2-020":{"objectives":["Hafta sonunda neler yaptığını İngilizce anlatmak","Düzenli ve düzensiz geçmiş zaman fiillerini kullanmak","Arkadaşına geçmiş zamanda soru sormak"],"dialogues":[{"title":"Monday morning","setting":"Pazartesi sabahı. Sınıfta arkadaşlar hafta sonunu anlatıyor.","lines":[{"s":"Mia","en":"Hi, Ali! What did you do on Saturday?","tr":"Selam Ali! Cumartesi ne yaptın?"},{"s":"Ali","en":"I went to the park with my dad.","tr":"Babamla parka gittim."},{"s":"Mia","en":"Nice! Did you play football?","tr":"Harika! Futbol oynadın mı?"},{"s":"Ali","en":"Yes, I played with my friends. It was fun!","tr":"Evet, arkadaşlarımla oynadım. Çok eğlenceliydi!"},{"s":"Mia","en":"I stayed home. I watched a film.","tr":"Ben evde kaldım. Bir film izledim."},{"s":"Ali","en":"Which film did you watch?","tr":"Hangi filmi izledin?"},{"s":"Mia","en":"A funny animal film. I really liked it!","tr":"Komik bir hayvan filmi. Gerçekten çok beğendim!"}]},{"title":"Phone call with Leo","setting":"Akşam, Zeynep kuzeni Leo'yu arıyor.","lines":[{"s":"Zeynep","en":"Hi, Leo! Did you have a good weekend?","tr":"Selam Leo! İyi bir hafta sonu geçirdin mi?"},{"s":"Leo","en":"Yes! We visited Grandma on Sunday.","tr":"Evet! Pazar günü büyükannemi ziyaret ettik."},{"s":"Zeynep","en":"Did she make a cake?","tr":"Pasta yaptı mı?"},{"s":"Leo","en":"She made a big chocolate cake. I ate two pieces!","tr":"Büyük bir çikolatalı pasta yaptı. İki dilim yedim!"},{"s":"Zeynep","en":"Wow! I ate ice cream at the beach.","tr":"Vay! Ben sahilde dondurma yedim."},{"s":"Leo","en":"Lucky you! What was the weather like?","tr":"Ne şanslısın! Hava nasıldı?"},{"s":"Zeynep","en":"It was sunny and hot. What a day!","tr":"Güneşliydi ve sıcaktı. Ne güzel bir gündü!"}]},{"title":"Weekend diary","setting":"Öğretmen, sınıfa hafta sonu günlüğü yazdırıyor.","lines":[{"s":"Teacher","en":"Let's share our weekend diaries. Ece, what did you do?","tr":"Hafta sonu günlüklerimizi paylaşalım. Ece, sen ne yaptın?"},{"s":"Ece","en":"I visited my cousin. We painted a picture.","tr":"Kuzenimi ziyaret ettim. Bir resim boyadık."},{"s":"Teacher","en":"How lovely! Did you finish it?","tr":"Ne güzel! Bitirdin mi?"},{"s":"Ece","en":"Yes! It was a big yellow sun.","tr":"Evet! Büyük, sarı bir güneşti."},{"s":"Teacher","en":"Great job. Leo, what did you do?","tr":"Harika iş. Leo, sen ne yaptın?"},{"s":"Leo","en":"I cleaned my room and I played chess.","tr":"Odamı temizledim ve satranç oynadım."},{"s":"Teacher","en":"Excellent! Well done, everyone.","tr":"Mükemmel! Herkese aferin."}]}],"reading":{"title":"A fun weekend","paras":[{"en":"Last Saturday, I went to the park with my mum and my little sister. We played on the swings and ate sandwiches under a big tree. I saw a dog and a cat. My sister laughed a lot. On Sunday, I stayed home and read a book. I felt happy. It was a good weekend!","tr":"Geçen cumartesi annem ve küçük kız kardeşimle parka gittim. Salıncaklarda oynadık ve büyük bir ağacın altında sandviç yedik. Bir köpek ve bir kedi gördüm. Kız kardeşim çok güldü. Pazar günü evde kaldım ve bir kitap okudum. Kendimi mutlu hissettim. Güzel bir hafta sonuydu!"}]},"vocab":[{"w":"weekend","ipa":"/ˌwiːkˈend/","pos":"📅","tr":"hafta sonu","ex":"We had a good weekend.","exTr":"İyi bir hafta sonu geçirdik."},{"w":"went","ipa":"/went/","pos":"🚶","tr":"gitti (go fiilinin geçmiş hâli)","ex":"I went to the park.","exTr":"Parka gittim."},{"w":"played","ipa":"/pleɪd/","pos":"⚽","tr":"oynadı","ex":"We played football.","exTr":"Futbol oynadık."},{"w":"visited","ipa":"/ˈvɪzɪtɪd/","pos":"🏠","tr":"ziyaret etti","ex":"She visited her grandma.","exTr":"Büyükannesini ziyaret etti."},{"w":"watched","ipa":"/wɒtʃt/","pos":"📺","tr":"izledi","ex":"I watched a film.","exTr":"Bir film izledim."},{"w":"ate","ipa":"/et/","pos":"🍕","tr":"yedi","ex":"He ate two pieces of cake.","exTr":"İki dilim pasta yedi."},{"w":"stayed","ipa":"/steɪd/","pos":"🏡","tr":"kaldı","ex":"We stayed home.","exTr":"Evde kaldık."},{"w":"fun","ipa":"/fʌn/","pos":"😄","tr":"eğlenceli","ex":"The park was fun!","exTr":"Park çok eğlenceliydi!"}],"chunks":[{"en":"What did you do?","tr":"Ne yaptın?"},{"en":"I had fun!","tr":"Çok eğlendim!"},{"en":"It was great.","tr":"Harikaydı."},{"en":"Lucky you!","tr":"Ne şanslısın!"}],"grammar":{"point":"Past simple","tr":"Geçmişte bitmiş bir şeyi anlatırken fiilin geçmiş hâlini kullanırız. Düzenli fiillerin sonuna '-ed' eklenir: played, visited. Bazı fiiller ise tamamen değişir: go, went; eat, ate.","examples":["I played football on Saturday.","She visited her grandma.","We went to the beach.","He ate a big sandwich."]},"questions":[{"q":"What did Mia do on Saturday?","a":"She stayed home and watched a film."},{"q":"Where did Ali go on Saturday?","a":"He went to the park with his dad."},{"q":"What did Leo eat at Grandma's house?","a":"He ate two pieces of chocolate cake."}],"quiz":[{"q":"Yesterday I ___ to the park.","o":["go","went","goes"],"a":1,"why":"Go fiilinin geçmiş hâli 'went'tir."},{"q":"She ___ a film last night.","o":["watched","watch","watches"],"a":0,"why":"Düzenli fiile '-ed' eklenir: watch, watched."},{"q":"We ___ football after school.","o":["play","plays","played"],"a":2,"why":"Geçmiş zamanda 'played' kullanılır."},{"q":"I ___ two pieces of cake.","o":["eat","ate","eaten"],"a":1,"why":"Eat fiilinin geçmiş hâli 'ate'tir."}],"drills":[{"type":"Yerine koyma","prompt":"I went to the park.","cue":"beach","answer":"I went to the beach."},{"type":"Dönüştürme","prompt":"I played football on Saturday.","cue":"Use 'yesterday' instead","answer":"I played football yesterday."},{"type":"Soru yap","prompt":"She visited her grandma.","cue":"Did…?","answer":"Did she visit her grandma?"}],"sounds":[{"focus":"/ɪd/","tr":"'-ed' eki bazen kısa bir /ɪd/ sesi olarak okunur (visited). Bazen de sadece /d/ olur (played). Dilini diş etine yaklaştır ve sesi hafifçe bitir.","pairs":["visit / visited","play / played","want / wanted"]}],"mission":{"brief":"Claude, arkadaşın Ali olacak ve sana geçen hafta sonunu soracak. Ona nereye gittiğini, ne yaptığını ve neyi çok sevdiğini İngilizce anlat. Ali'nin de bir sırrı var; iyi sorular sorarak onu öğren.","persona":"Ali, a friendly 10-year-old boy who speaks in short, simple sentences. He is shy about one thing: on Sunday he learned to ride a bicycle without training wheels, but he only admits it when the learner asks a follow-up question about Sunday.","goal":"En az üç geçmiş zaman cümlesi kur ve Ali'nin gizli bilgisini öğren.","opener":"Hi! What did you do last weekend?"}},"KS2-021":{"objectives":["Hayvanları boy, hız ve ağırlık bakımından karşılaştırmak","Sıfat + '-er' + 'than' kalıbını kullanmak","Basit bir karşılaştırma sorusu sormak"],"dialogues":[{"title":"At the zoo","setting":"Hayvanat bahçesinde Mia ve Ali, fillerin önünde konuşuyor.","lines":[{"s":"Mia","en":"Wow, look at the elephant! It's so big.","tr":"Vay, file bak! Çok büyük."},{"s":"Ali","en":"Yes, it's bigger than the bear.","tr":"Evet, ayıdan daha büyük."},{"s":"Mia","en":"Is the giraffe taller than the elephant?","tr":"Zürafa fildan daha uzun mu?"},{"s":"Ali","en":"Yes! The giraffe is much taller. Look at its neck!","tr":"Evet! Zürafa çok daha uzun. Boynuna bak!"},{"s":"Mia","en":"What about the monkey? Is it faster than the lion?","tr":"Peki ya maymun? Aslandan daha hızlı mı?"},{"s":"Ali","en":"No, it's slower than the lion!","tr":"Hayır, aslandan daha yavaş!"},{"s":"Mia","en":"Haha, you're right!","tr":"Haha, haklısın!"}]},{"title":"Pet talk","setting":"Okulda Leo ve Ece evcil hayvanlarını karşılaştırıyor.","lines":[{"s":"Ece","en":"I have a hamster. It's very small.","tr":"Bir hamsterim var. Çok küçük."},{"s":"Leo","en":"Is it smaller than a mouse?","tr":"Bir fareden daha küçük mü?"},{"s":"Ece","en":"No, it's bigger than a mouse. But it's cuter!","tr":"Hayır, fareden daha büyük. Ama daha sevimli!"},{"s":"Leo","en":"My dog is heavier than your hamster, of course!","tr":"Tabii ki benim köpeğim senin hamsterinden daha ağır!"},{"s":"Ece","en":"Maybe. But my hamster is faster on the wheel.","tr":"Belki. Ama benim hamsterim çarkta daha hızlı koşar."},{"s":"Leo","en":"Haha! Then you win.","tr":"Haha! O zaman sen kazandın."}]},{"title":"Animal quiz","setting":"Öğretmen sınıfla kısa bir hayvan yarışması yapıyor.","lines":[{"s":"Teacher","en":"Quick quiz! Which is faster, a snail or a rabbit?","tr":"Hızlı bir quiz! Hangisi daha hızlı, salyangoz mu tavşan mı?"},{"s":"Ali","en":"A rabbit is faster than a snail!","tr":"Tavşan salyangozdan daha hızlı!"},{"s":"Teacher","en":"Correct! Now, is a whale heavier than a dolphin?","tr":"Doğru! Şimdi, balina yunustan daha ağır mı?"},{"s":"Mia","en":"Yes, a whale is much heavier than a dolphin.","tr":"Evet, balina yunustan çok daha ağır."},{"s":"Teacher","en":"Excellent! Is a turtle slower than a snake?","tr":"Harika! Peki kaplumbağa yılandan daha yavaş mı?"},{"s":"Ali","en":"Yes! A turtle is slower than a snake.","tr":"Evet! Kaplumbağa yılandan daha yavaş."}]}],"reading":{"title":"Big, small and fast","paras":[{"en":"Animals are very different. An elephant is bigger than a dog. A mouse is smaller than a cat. A cheetah is faster than a horse, and a snail is slower than a tortoise. The giraffe is the tallest animal in the world. My favourite animal is the dolphin, because it is very clever and fun to watch!","tr":"Hayvanlar çok farklıdır. Fil bir köpekten daha büyüktür. Fare bir kediden daha küçüktür. Çita bir attan daha hızlıdır, salyangoz ise kaplumbağadan daha yavaştır. Zürafa dünyanın en uzun hayvanıdır. En sevdiğim hayvan yunustur, çünkü çok zekidir ve izlemesi çok eğlencelidir!"}]},"vocab":[{"w":"bigger","ipa":"/ˈbɪɡə/","pos":"🐘","tr":"daha büyük","ex":"An elephant is bigger than a dog.","exTr":"Fil bir köpekten daha büyüktür."},{"w":"smaller","ipa":"/ˈsmɔːlə/","pos":"🐭","tr":"daha küçük","ex":"A mouse is smaller than a cat.","exTr":"Fare bir kediden daha küçüktür."},{"w":"faster","ipa":"/ˈfɑːstə/","pos":"🐆","tr":"daha hızlı","ex":"A cheetah is faster than a horse.","exTr":"Çita bir attan daha hızlıdır."},{"w":"slower","ipa":"/ˈsləʊə/","pos":"🐌","tr":"daha yavaş","ex":"A snail is slower than a tortoise.","exTr":"Salyangoz kaplumbağadan daha yavaştır."},{"w":"taller","ipa":"/ˈtɔːlə/","pos":"🦒","tr":"daha uzun","ex":"The giraffe is taller than me.","exTr":"Zürafa benden daha uzun."},{"w":"stronger","ipa":"/ˈstrɒŋɡə/","pos":"💪","tr":"daha güçlü","ex":"The bear is stronger than the dog.","exTr":"Ayı köpekten daha güçlüdür."},{"w":"heavier","ipa":"/ˈhevɪə/","pos":"🐋","tr":"daha ağır","ex":"A whale is heavier than a dolphin.","exTr":"Balina yunustan daha ağırdır."},{"w":"animal","ipa":"/ˈænɪml/","pos":"🦁","tr":"hayvan","ex":"The lion is my favourite animal.","exTr":"Aslan en sevdiğim hayvan."}],"chunks":[{"en":"Which is bigger?","tr":"Hangisi daha büyük?"},{"en":"It's much faster!","tr":"Çok daha hızlı!"},{"en":"You're right!","tr":"Haklısın!"},{"en":"Let's compare!","tr":"Karşılaştıralım!"}],"grammar":{"point":"Comparatives (-er than)","tr":"İki şeyi karşılaştırmak için sıfatın sonuna '-er' eklenir ve ardından 'than' gelir. 'Than' Türkçedeki '-den daha' anlamına gelir. Bazı kelimelerde son harf iki kez yazılır: big, bigger.","examples":["A cheetah is faster than a horse.","A mouse is smaller than a cat.","The giraffe is taller than the zebra.","A whale is heavier than a dolphin."]},"questions":[{"q":"Which animal is bigger, an elephant or a dog?","a":"An elephant is bigger than a dog."},{"q":"Is a snail faster than a tortoise?","a":"No, a snail is slower than a tortoise."},{"q":"What pet does Ece have?","a":"A hamster."}],"quiz":[{"q":"A whale is ___ than a dolphin.","o":["heavy","heavier","heaviest"],"a":1,"why":"Sıfatın sonuna '-er' eklenir: heavy, heavier."},{"q":"The snail is ___ than the rabbit.","o":["faster","slower","bigger"],"a":1,"why":"Salyangoz tavşandan daha yavaştır."},{"q":"A mouse is ___ than a cat.","o":["smaller","small","smallest"],"a":0,"why":"Karşılaştırma için '-er' kullanılır."},{"q":"The giraffe is ___ than me.","o":["tallest","tall","taller"],"a":2,"why":"İki şeyi karşılaştırırken 'taller ... than' kullanılır."}],"drills":[{"type":"Yerine koyma","prompt":"The giraffe is taller than the zebra.","cue":"the dog","answer":"The giraffe is taller than the dog."},{"type":"Dönüştürme","prompt":"A cheetah is faster than a horse.","cue":"Use 'slower' and swap the animals","answer":"A horse is slower than a cheetah."},{"type":"Soru yap","prompt":"A mouse is smaller than a cat.","cue":"Which…?","answer":"Which is smaller, a mouse or a cat?"}],"sounds":[{"focus":"/ə/","tr":"'-er' sonu kısa ve hafif bir /ə/ sesidir. 'Er' kelimesini sert 'ır' gibi okumak yerine dudaklarını gevşet ve sesi hafifçe bitir.","pairs":["slower / slow","taller / tall","bigger / big"]}],"mission":{"brief":"Claude, arkadaşın Leo olacak. Leo bir evcil hayvanı olduğunu söyleyecek ama ne olduğunu hemen anlatmayacak. Hayvanı diğer hayvanlarla karşılaştırarak tahmin etmeye çalış ve onun hakkında iyi sorular sor.","persona":"Leo, a friendly 10-year-old boy who loves animals. He uses short, simple sentences. His hidden fact: his pet is a tortoise named Max, and Max is older than Leo's dad. He only reveals what the pet is after the learner asks two good comparison questions.","goal":"En az üç karşılaştırma cümlesi kur ve Leo'nun evcil hayvanını bul.","opener":"Hi! I have a pet. Can you guess what kind of animal it is?"}},"KS2-022":{"objectives":["Yeteneklerimi İngilizce anlatmak","'Can' ve 'can't' kullanmak","Bir arkadaşa yeteneklerini sormak"],"dialogues":[{"title":"If you had a superpower","setting":"Okul bahçesinde Ece ve Leo süper güçler hakkında konuşuyor.","lines":[{"s":"Ece","en":"If you had a superpower, what would it be?","tr":"Bir süper gücün olsaydı, ne olurdu?"},{"s":"Leo","en":"I would fly! I can't fly now, but I'd love it.","tr":"Uçardım! Şu an uçamıyorum ama bayılırdım."},{"s":"Ece","en":"Cool! Can you jump high?","tr":"Harika! Çok yükseğe zıplayabilir misin?"},{"s":"Leo","en":"Yes, I can jump very high. Look!","tr":"Evet, çok yükseğe zıplayabilirim. Bak!"},{"s":"Ece","en":"Wow! You can jump like a kangaroo.","tr":"Vay! Kanguru gibi zıplayabiliyorsun."},{"s":"Leo","en":"What about you? Can you hold your breath for a long time?","tr":"Ya sen? Nefesini uzun süre tutabilir misin?"},{"s":"Ece","en":"Yes, I can! I can hold my breath for one minute.","tr":"Evet, tutabilirim! Nefesimi bir dakika tutabilirim."}]},{"title":"Superhero club","setting":"Yeni süper kahraman kulübüne katılmak isteyen Mia, kulüp başkanı Ali ile konuşuyor.","lines":[{"s":"Ali","en":"Welcome to the superhero club! What can you do?","tr":"Süper kahraman kulübüne hoş geldin! Ne yapabilirsin?"},{"s":"Mia","en":"I can climb trees really fast.","tr":"Ağaçlara gerçekten çok hızlı tırmanabilirim."},{"s":"Ali","en":"Great! Can you run fast too?","tr":"Harika! Hızlı koşabilir misin de?"},{"s":"Mia","en":"Sorry, I can't run fast. I'm bad at running.","tr":"Üzgünüm, hızlı koşamam. Koşmakta iyi değilim."},{"s":"Ali","en":"No problem. We need a climber, a jumper and a swimmer.","tr":"Sorun değil. Bir tırmanıcıya, bir zıplayıcıya ve bir yüzücüye ihtiyacımız var."},{"s":"Mia","en":"Then I'm your climber!","tr":"O zaman ben sizin tırmanıcınızım!"}]},{"title":"Quick science quiz","setting":"Öğretmen sınıfa hayvanların ve insanların yetenekleri hakkında sorular soruyor.","lines":[{"s":"Teacher","en":"Class, can a bird fly?","tr":"Sınıf, bir kuş uçabilir mi?"},{"s":"Mia","en":"Yes, a bird can fly!","tr":"Evet, kuş uçabilir!"},{"s":"Teacher","en":"Good. Can a fish breathe under water?","tr":"İyi. Balık suyun altında nefes alabilir mi?"},{"s":"Ali","en":"Yes, it can! It has gills.","tr":"Evet, alabilir! Solungaçları var."},{"s":"Teacher","en":"Excellent! Can a human fly without a plane?","tr":"Harika! İnsan uçak olmadan uçabilir mi?"},{"s":"Leo","en":"No, we can't! But I wish we could.","tr":"Hayır, uçamayız! Ama keşke uçabilseydik."}]}],"reading":{"title":"My superpower","paras":[{"en":"My name is Ece and I have a secret. I can't fly, and I can't turn invisible. But I can hold my breath under water for a long time! My friend Leo can jump very high. He can climb trees too. Our superhero team is simple: we help our friends. Every Friday, we play in the park and try new tricks.","tr":"Benim adım Ece ve bir sırrım var. Uçamam ve görünmez olamam. Ama suyun altında uzun süre nefesimi tutabilirim! Arkadaşım Leo çok yükseğe zıplayabilir. Ağaçlara da tırmanabilir. Süper kahraman takımımız basit: arkadaşlarımıza yardım ederiz. Her cuma parkta oynar ve yeni numaralar denemeye çalışırız."}]},"vocab":[{"w":"superpower","ipa":"/ˈsuːpəˌpaʊə/","pos":"⚡","tr":"süper güç","ex":"Flying is a superpower.","exTr":"Uçmak bir süper güçtür."},{"w":"hero","ipa":"/ˈhɪərəʊ/","pos":"🦸","tr":"kahraman","ex":"My dad is my hero.","exTr":"Babam benim kahramanım."},{"w":"fly","ipa":"/flaɪ/","pos":"🕊️","tr":"uçmak","ex":"I can't fly like a bird.","exTr":"Bir kuş gibi uçamam."},{"w":"invisible","ipa":"/ɪnˈvɪzəbl/","pos":"👻","tr":"görünmez","ex":"The superhero is invisible.","exTr":"Süper kahraman görünmezdir."},{"w":"jump","ipa":"/dʒʌmp/","pos":"🦘","tr":"zıplamak","ex":"Leo can jump very high.","exTr":"Leo çok yükseğe zıplayabilir."},{"w":"climb","ipa":"/klaɪm/","pos":"🧗","tr":"tırmanmak","ex":"Mia can climb trees fast.","exTr":"Mia ağaçlara hızlı tırmanabilir."},{"w":"hold my breath","ipa":"/həʊld maɪ breθ/","pos":"🫁","tr":"nefesini tutmak","ex":"Can you hold your breath?","exTr":"Nefesini tutabilir misin?"},{"w":"swim","ipa":"/swɪm/","pos":"🏊","tr":"yüzmek","ex":"I can swim very well.","exTr":"Çok iyi yüzebilirim."}],"chunks":[{"en":"If I had a superpower…","tr":"Bir süper gücüm olsaydı…"},{"en":"Can you…?","tr":"… yapabilir misin?"},{"en":"I'm bad at…","tr":"… konusunda kötüyüm."},{"en":"No problem!","tr":"Sorun değil!"}],"grammar":{"point":"Can / can't for abilities","tr":"'Can' bir yeteneği ya da becerisi olduğunu anlatır ve fiilden önce gelir: I can swim. Olumsuzu 'can't' ile yaparız ve fiil değişmez. Soru yapmak için 'can' cümlenin başına geçer.","examples":["I can swim very well.","She can't fly, but she can jump.","Can you climb trees?","He can hold his breath for one minute."]},"questions":[{"q":"What superpower does Leo want?","a":"He wants to fly."},{"q":"What can Ece do under water?","a":"She can hold her breath for a long time."},{"q":"Why can't Mia be the runner in the superhero club?","a":"Because she can't run fast."}],"quiz":[{"q":"I ___ swim very well.","o":["can","cans","canned"],"a":0,"why":"'Can' fiilden önce gelir ve değişmez."},{"q":"She ___ fly, but she can jump.","o":["can","can't","cans"],"a":1,"why":"'Can't' yeteneğin olmadığını gösterir."},{"q":"___ you climb trees?","o":["Are","Do","Can"],"a":2,"why":"Soru için 'Can' cümlenin başına gelir."},{"q":"Leo ___ jump very high.","o":["cans","can","can't"],"a":1,"why":"Olumlu cümlede 'can' kullanılır."}],"drills":[{"type":"Yerine koyma","prompt":"I can swim very well.","cue":"climb trees","answer":"I can climb trees very well."},{"type":"Dönüştürme","prompt":"Leo can jump very high.","cue":"Make it negative","answer":"Leo can't jump very high."},{"type":"Soru yap","prompt":"Ece can hold her breath for a long time.","cue":"Can…?","answer":"Can Ece hold her breath for a long time?"}],"sounds":[{"focus":"/æ/","tr":"Türkçede /æ/ sesi yoktur. Ağzını geniş aç, dilini aşağıda tut ve 'e' ile 'a' arasında bir ses çıkar: can, cat.","pairs":["can / can't","hat / hart","cat / cart"]}],"mission":{"brief":"Claude, süper kahraman kulübüne yeni bir üye olmak isteyen Zeynep olacak. Zeynep'e hangi yeteneklere sahip olduğunu İngilizce sor. Ona kulüpte hangi görevin uygun olacağını öner.","persona":"Zeynep, a clever 10-year-old girl who wants to join the superhero club. She says she has no special talent at first. Her hidden fact: she can play the drums very well, but she is shy about it and only reveals it when asked about her hobbies or what she is good at.","goal":"En az üç 'can' ya da 'can't' cümlesiyle Zeynep'in yeteneklerini öğren.","opener":"Hi! I want to join the superhero club, but I'm not sure I have a superpower."}},"KS2-023":{"objectives":["Kamp yerini ve kamp eşyalarını anlatmak","'There is' ve 'There are' kalıplarını kullanmak","Bir grup planını sesli olarak söylemek"],"dialogues":[{"title":"Packing the car","setting":"Aile kamp için arabaya eşya yerleştiriyor. Ali ve annesi konuşuyor.","lines":[{"s":"Ali","en":"Mum, are we ready for the camping trip?","tr":"Anne, kamp gezisi için hazır mıyız?"},{"s":"Mum","en":"Almost! There is a tent in the car. Do we have the torch?","tr":"Neredeyse! Arabada bir çadır var. Fener var mı?"},{"s":"Ali","en":"Yes, there is a torch in my bag.","tr":"Evet, çantamda bir fener var."},{"s":"Mum","en":"Good. Are there enough sleeping bags?","tr":"İyi. Yeterince uyku tulumu var mı?"},{"s":"Ali","en":"There are three sleeping bags. One for each of us!","tr":"Üç uyku tulumu var. Her birimiz için bir tane!"},{"s":"Mum","en":"Perfect. Let's go!","tr":"Mükemmel. Hadi gidelim!"}]},{"title":"At the lake","setting":"Kamp yerinde, Mia ve Leo gölün kenarında konuşuyor.","lines":[{"s":"Mia","en":"Wow, there is a big lake near our tent!","tr":"Vay, çadırımızın yakınında büyük bir göl var!"},{"s":"Leo","en":"Yes! There are many ducks on the water.","tr":"Evet! Suyun üstünde çok ördek var."},{"s":"Mia","en":"Is there a boat for us?","tr":"Bizim için bir tekne var mı?"},{"s":"Leo","en":"No boat, but there is a little bridge.","tr":"Tekne yok ama küçük bir köprü var."},{"s":"Mia","en":"Can we fish from the bridge?","tr":"Köprüden balık tutabilir miyiz?"},{"s":"Leo","en":"Maybe. Let's ask the guide first.","tr":"Belki. Önce rehbere soralım."}]},{"title":"Around the campfire","setting":"Akşam, kamp ateşinin başında grup sohbet ediyor.","lines":[{"s":"Guide","en":"Who is ready for the campfire?","tr":"Kamp ateşi için kim hazır?"},{"s":"Ece","en":"I am! There are some marshmallows, right?","tr":"Ben hazırım! Birkaç marshmallow var, değil mi?"},{"s":"Guide","en":"Yes, there are six marshmallows for each person.","tr":"Evet, her kişi için altı marshmallow var."},{"s":"Ali","en":"Is there a star map too?","tr":"Yıldız haritası da var mı?"},{"s":"Guide","en":"There is! Look at the sky. There are so many stars.","tr":"Var! Gökyüzüne bak. Çok fazla yıldız var."},{"s":"Ece","en":"Wow! This is the best camp ever!","tr":"Vay! Bu, şimdiye kadarki en iyi kamp!"}]}],"reading":{"title":"A night under the stars","paras":[{"en":"Our camping trip starts on Friday. There is a forest near the lake, and there are many tall trees. Our tent is green, and there is a small fire in the middle of our camp. At night there are a lot of stars in the sky. There are no cars and no noise, only birds and frogs! Remember to bring a torch and warm clothes.","tr":"Kamp gezimiz cuma günü başlıyor. Gölün yakınında bir orman var ve orada birçok uzun ağaç var. Çadırımız yeşil ve kampımızın ortasında küçük bir ateş var. Geceleri gökyüzünde çok fazla yıldız var. Hiç araba ve gürültü yok, sadece kuşlar ve kurbağalar var! Bir fener ve sıcak kıyafetler getirmeyi unutma."}]},"vocab":[{"w":"tent","ipa":"/tent/","pos":"⛺","tr":"çadır","ex":"Our tent is green.","exTr":"Çadırımız yeşil."},{"w":"sleeping bag","ipa":"/ˈsliːpɪŋ bæɡ/","pos":"🛏️","tr":"uyku tulumu","ex":"The sleeping bag is warm.","exTr":"Uyku tulumu sıcak."},{"w":"torch","ipa":"/tɔːtʃ/","pos":"🔦","tr":"fener","ex":"Bring a torch at night.","exTr":"Geceleri bir fener getir."},{"w":"forest","ipa":"/ˈfɒrɪst/","pos":"🌲","tr":"orman","ex":"There is a forest near the lake.","exTr":"Gölün yakınında bir orman var."},{"w":"lake","ipa":"/leɪk/","pos":"🏞️","tr":"göl","ex":"The lake is very big.","exTr":"Göl çok büyük."},{"w":"campfire","ipa":"/ˈkæmpfaɪə/","pos":"🔥","tr":"kamp ateşi","ex":"We sing by the campfire.","exTr":"Kamp ateşinin başında şarkı söyleriz."},{"w":"star","ipa":"/stɑː/","pos":"⭐","tr":"yıldız","ex":"There are many stars tonight.","exTr":"Bu gece çok fazla yıldız var."},{"w":"frog","ipa":"/frɒɡ/","pos":"🐸","tr":"kurbağa","ex":"I can see a frog.","exTr":"Bir kurbağa görebiliyorum."}],"chunks":[{"en":"There is…","tr":"… var."},{"en":"Are there…?","tr":"… var mı?"},{"en":"Let's set up the tent!","tr":"Hadi çadırı kuralım!"},{"en":"Remember to bring…","tr":"… getirmeyi unutma."}],"grammar":{"point":"There is / There are","tr":"Bir yerde bir şeyin var olduğunu anlatmak için tekil isimlerde 'There is', çoğul isimlerde 'There are' kullanılır. İkisi de Türkçedeki '... var' anlamına gelir. Soru yaparken fiil cümlenin başına geçer.","examples":["There is a torch in my bag.","There are three sleeping bags.","There is a lake near the tent.","Are there any frogs?"]},"questions":[{"q":"What is in Ali's bag?","a":"A torch."},{"q":"How many sleeping bags are there?","a":"There are three."},{"q":"What can Mia and Leo see near their tent?","a":"A big lake and many ducks on the water."}],"quiz":[{"q":"___ a tent in the car.","o":["There is","There are","There be"],"a":0,"why":"Tekil bir isimden önce 'There is' gelir."},{"q":"___ many stars tonight.","o":["There is","There are","There have"],"a":1,"why":"Çoğul isimlerde 'There are' kullanılır."},{"q":"___ there any frogs?","o":["Is","Are","Do"],"a":1,"why":"Çoğul soruda 'Are there' kullanılır."},{"q":"There ___ a forest near the lake.","o":["are","be","is"],"a":2,"why":"Tekil 'a forest' için 'is' gerekir."}],"drills":[{"type":"Yerine koyma","prompt":"There is a torch in my bag.","cue":"tent / car","answer":"There is a tent in the car."},{"type":"Dönüştürme","prompt":"There are three sleeping bags.","cue":"Make it singular: one","answer":"There is one sleeping bag."},{"type":"Soru yap","prompt":"There is a lake near the tent.","cue":"Is there…?","answer":"Is there a lake near the tent?"}],"sounds":[{"focus":"/ɜː/","tr":"Dudaklarını hafifçe yuvarla, dilini ortada tut ve uzun, 'ö' ile 'er' arası bir ses çıkar. Türkçedeki 'ö' gibi kısa değil, uzun okunur.","pairs":["bird / bed","birds / beds","fur / four"]}],"mission":{"brief":"Claude, kamp arkadaşın Ece olacak. Ece kamp alanında neler olduğunu bilmiyor. Ona çadır, göl ve ormanı 'There is / There are' kalıplarıyla anlat ve ona eksik eşyaları bulmasında yardım et.","persona":"Ece, a cheerful 10-year-old going camping for the first time. Her hidden fact: she forgot to pack her sleeping bag and feels embarrassed about it. She only admits it when the learner asks good questions about what she has packed.","goal":"Ece'nin unuttuğu eşyayı bul ve ona 'There is / There are' ile bir çözüm öner.","opener":"Hi! I'm so excited about camping. Is there a lot of space for our tent?"}},"KS2-024":{"objectives":["Doğayı korumak için yapılması gerekenleri anlatmak","'Should' ve 'shouldn't' kullanmak","Bir öneriyi nazikçe sunmak"],"dialogues":[{"title":"Bin day","setting":"Okul bahçesinde Leo ve Ece çöpleri ayırıyor.","lines":[{"s":"Ece","en":"Leo, where should I put this plastic bottle?","tr":"Leo, bu plastik şişeyi nereye koymalıyım?"},{"s":"Leo","en":"In the blue bin. We should recycle plastic.","tr":"Mavi kutuya. Plastiği geri dönüştürmeliyiz."},{"s":"Ece","en":"What about this paper?","tr":"Peki ya bu kâğıt?"},{"s":"Leo","en":"Paper goes in the same bin. You shouldn't throw it on the ground.","tr":"Kâğıt da aynı kutuya gider. Onu yere atmamalısın."},{"s":"Ece","en":"Oops! I almost did. Thanks!","tr":"Hay aksi! Neredeyse atıyordum. Teşekkürler!"},{"s":"Leo","en":"No problem. Let's pick up this litter too.","tr":"Sorun değil. Şu çöpü de toplayalım."},{"s":"Ece","en":"Good idea! We should help nature.","tr":"İyi fikir! Doğaya yardım etmeliyiz."}]},{"title":"Saving water","setting":"Akşam yemeğinden sonra Mia annesiyle su tasarrufunu konuşuyor.","lines":[{"s":"Mia","en":"Mum, the tap is still running!","tr":"Anne, musluk hâlâ akıyor!"},{"s":"Mum","en":"Oh, you're right. We should turn it off when we brush our teeth.","tr":"Oh, haklısın. Dişlerimizi fırçalarken kapatmalıyız."},{"s":"Mia","en":"Good idea. Should we take shorter showers too?","tr":"İyi fikir. Duşları da daha kısa mı almalıyız?"},{"s":"Mum","en":"Yes, shorter showers save a lot of water.","tr":"Evet, kısa duşlar çok su tasarrufu sağlar."},{"s":"Mia","en":"Okay. I'll remember that tomorrow.","tr":"Tamam. Bunu yarın hatırlayacağım."},{"s":"Mum","en":"Thank you, Mia! You're a little hero for the planet.","tr":"Teşekkürler Mia! Gezegen için küçük bir kahramansın."}]},{"title":"Our class poster","setting":"Öğretmen, sınıfa doğa koruma posteri için fikir soruyor.","lines":[{"s":"Teacher","en":"Our class poster is about nature. What should we write?","tr":"Sınıf posterimiz doğa hakkında. Ne yazmalıyız?"},{"s":"Ali","en":"We should write: Save the trees!","tr":"Şunu yazmalıyız: Ağaçları koruyun!"},{"s":"Teacher","en":"Nice! Should we draw animals too?","tr":"Güzel! Hayvanları da çizmeli miyiz?"},{"s":"Ece","en":"Yes! And we shouldn't forget the rivers.","tr":"Evet! Ve nehirleri unutmamalıyız."},{"s":"Teacher","en":"Perfect. Let's make the poster together.","tr":"Mükemmel. Posteri birlikte yapalım."}]}],"reading":{"title":"Protect our planet","paras":[{"en":"Nature gives us clean air, fresh water and beautiful forests. We should protect it every day. At home, we should sort our rubbish into the right bins. Paper and bottles can be recycled. We shouldn't waste water, and we shouldn't throw litter in the park. Small actions can make a big difference!","tr":"Doğa bize temiz hava, taze su ve güzel ormanlar verir. Onu her gün korumalıyız. Evde çöplerimizi doğru kutulara ayırmalıyız. Kâğıt ve şişeler geri dönüştürülebilir. Suyu boşa harcamamalıyız ve parkta çöp atmamalıyız. Küçük adımlar büyük fark yaratabilir!"}]},"vocab":[{"w":"recycle","ipa":"/ˌriːˈsaɪkl/","pos":"♻️","tr":"geri dönüştürmek","ex":"We recycle paper and bottles.","exTr":"Kâğıt ve şişeleri geri dönüştürüyoruz."},{"w":"bottle","ipa":"/ˈbɒtl/","pos":"🍾","tr":"şişe","ex":"Put the bottle in the blue bin.","exTr":"Şişeyi mavi kutuya koy."},{"w":"paper","ipa":"/ˈpeɪpə/","pos":"📄","tr":"kâğıt","ex":"This paper is clean.","exTr":"Bu kâğıt temiz."},{"w":"tree","ipa":"/triː/","pos":"🌳","tr":"ağaç","ex":"Trees give us clean air.","exTr":"Ağaçlar bize temiz hava verir."},{"w":"bin","ipa":"/bɪn/","pos":"🗑️","tr":"kutu, çöp kutusu","ex":"The bin is full.","exTr":"Kutu dolu."},{"w":"nature","ipa":"/ˈneɪtʃə/","pos":"🌿","tr":"doğa","ex":"We should protect nature.","exTr":"Doğayı korumalıyız."},{"w":"plastic","ipa":"/ˈplæstɪk/","pos":"🛍️","tr":"plastik","ex":"Don't throw plastic on the ground.","exTr":"Plastiği yere atma."},{"w":"clean","ipa":"/kliːn/","pos":"🧽","tr":"temiz","ex":"The water is clean.","exTr":"Su temiz."}],"chunks":[{"en":"We should…","tr":"… etmeliyiz."},{"en":"You shouldn't…","tr":"… yapmamalısın."},{"en":"Small actions make a big difference.","tr":"Küçük adımlar büyük fark yaratır."},{"en":"Good idea!","tr":"İyi fikir!"}],"grammar":{"point":"Should / shouldn't (advice)","tr":"'Should' bir tavsiye vermek ya da doğru olanı söylemek için kullanılır ve Türkçedeki '-meli, -malı' ekiyle karşılık bulur. Fiilden önce 'to' gelmez: We should recycle. Olumsuzu 'shouldn't' ile yaparız.","examples":["We should recycle paper.","You shouldn't throw litter on the ground.","We should turn off the tap.","They shouldn't waste water."]},"questions":[{"q":"Where should Ece put the plastic bottle?","a":"In the blue bin."},{"q":"What should Mia's mum do when she brushes her teeth?","a":"She should turn off the tap."},{"q":"What shouldn't the class forget on the poster?","a":"The rivers."}],"quiz":[{"q":"We ___ recycle paper.","o":["should","shoulds","to should"],"a":0,"why":"'Should' fiilden önce gelir ve 'to' almaz."},{"q":"You ___ throw litter in the park.","o":["should","shouldn't","should to"],"a":1,"why":"Yapılmaması gereken bir şey için 'shouldn't' kullanılır."},{"q":"Which sentence is correct?","o":["Should we to turn off the tap?","Should we turn off the tap?","We should turns off the tap."],"a":1,"why":"Soru: Should + özne + fiil."},{"q":"Small actions can make a big ___.","o":["difference","different","differently"],"a":0,"why":"'Make a difference' fark yaratmak demektir."}],"drills":[{"type":"Yerine koyma","prompt":"We should recycle paper.","cue":"bottles","answer":"We should recycle bottles."},{"type":"Dönüştürme","prompt":"You shouldn't waste water.","cue":"Make it positive: save","answer":"You should save water."},{"type":"Soru yap","prompt":"We should turn off the tap.","cue":"Should…?","answer":"Should we turn off the tap?"}],"sounds":[{"focus":"/w/","tr":"Türkçede 'w' sesi yoktur. Dudaklarını küçük bir daire gibi yuvarla ve 'u' sesinden başlayarak kelimeyi söyle. 'V' için ise alt dudağını üst dişlerine değdir.","pairs":["wet / vet","west / vest","wary / very"]}],"mission":{"brief":"Claude, okulun çevre kulübünün başkanı Ali olacak. Ali bir geri dönüşüm kampanyası düzenliyor. Ona bir öneri sun ve hangi kutuya neyin atılacağını nazikçe konuş.","persona":"Ali, a friendly and well-organised 11-year-old club leader. His hidden fact: the recycling bins at school have the wrong labels, because the club bought them by mistake. He admits this only when the learner asks good questions about the bins.","goal":"Ali'nin gizli bilgisini öğren ve 'We should…' ya da 'You shouldn't…' kalıplarıyla bir öneri yap.","opener":"Hi! Our club wants to clean the school garden. Can you help us?"}},"KS2-025":{"objectives":["Gelecekte olmak istediğin mesleği anlatmak","'Want to' kalıbını kullanmak","Bir arkadaşının hayalini sormak"],"dialogues":[{"title":"Show and tell","setting":"Sınıfta her öğrenci hayalindeki mesleği anlatıyor. Sıra Ece'de.","lines":[{"s":"Teacher","en":"Ece, what is your dream job?","tr":"Ece, hayalindeki meslek ne?"},{"s":"Ece","en":"I want to be a vet. I love animals!","tr":"Veteriner olmak istiyorum. Hayvanları çok seviyorum!"},{"s":"Teacher","en":"Wonderful! Why do you want to be a vet?","tr":"Harika! Neden veteriner olmak istiyorsun?"},{"s":"Ece","en":"I want to help sick dogs and cats.","tr":"Hasta köpeklere ve kedilere yardım etmek istiyorum."},{"s":"Teacher","en":"That's a kind dream. Thank you, Ece.","tr":"Bu nazik bir hayal. Teşekkürler Ece."},{"s":"Leo","en":"Me next! I want to be a pilot.","tr":"Sıra bende! Pilot olmak istiyorum."},{"s":"Teacher","en":"Great! Let's hear it.","tr":"Harika! Hadi dinleyelim."}]},{"title":"Break time chat","setting":"Teneffüste Mia ve Ali hayalleri hakkında konuşuyor.","lines":[{"s":"Mia","en":"Ali, what do you want to be when you grow up?","tr":"Ali, büyüyünce ne olmak istiyorsun?"},{"s":"Ali","en":"I want to be a chef. I want to cook pizza for everyone!","tr":"Şef olmak istiyorum. Herkes için pizza pişirmek istiyorum!"},{"s":"Mia","en":"Yummy! Do you want to open a restaurant?","tr":"Yum! Bir restoran açmak ister misin?"},{"s":"Ali","en":"Yes, one day. What about you?","tr":"Evet, bir gün. Ya sen?"},{"s":"Mia","en":"I want to be a teacher. I want to teach children new words!","tr":"Öğretmen olmak istiyorum. Çocuklara yeni kelimeler öğretmek istiyorum!"},{"s":"Ali","en":"That sounds amazing!","tr":"Kulağa harika geliyor!"}]},{"title":"A dream about space","setting":"Yıldız gözlem gecesinde Leo ve öğretmeni uzay hakkında konuşuyor.","lines":[{"s":"Teacher","en":"Leo, do you want to visit space one day?","tr":"Leo, bir gün uzaya gitmek ister misin?"},{"s":"Leo","en":"Yes! I want to be an astronaut. I want to see the stars up close.","tr":"Evet! Astronot olmak istiyorum. Yıldızları yakından görmek istiyorum."},{"s":"Teacher","en":"That's a big dream. What do you need to do?","tr":"Bu büyük bir hayal. Ne yapman gerekiyor?"},{"s":"Leo","en":"I need to study science and maths hard.","tr":"Fen ve matematiği çok çalışmam gerekiyor."},{"s":"Teacher","en":"Good plan! Keep working on it.","tr":"İyi plan! Üzerinde çalışmaya devam et."},{"s":"Leo","en":"I will! Thank you.","tr":"Çalışacağım! Teşekkürler."}]}],"reading":{"title":"A dream for the future","paras":[{"en":"Hello! My name is Mia. I want to be a teacher when I grow up. I want to help children learn new words, and I want to read stories every day. My friend Ali wants to be a chef because he loves cooking. Our dreams are different, but we both want to work hard. What do you want to be?","tr":"Merhaba! Benim adım Mia. Büyüyünce öğretmen olmak istiyorum. Çocuklara yeni kelimeler öğretmek ve her gün hikâye okumak istiyorum. Arkadaşım Ali, yemek yapmayı sevdiği için şef olmak istiyor. Hayallerimiz farklı, ama ikimiz de çok çalışmak istiyoruz. Sen ne olmak istiyorsun?"}]},"vocab":[{"w":"dream job","ipa":"/driːm dʒɒb/","pos":"💼","tr":"hayal edilen meslek","ex":"My dream job is to be a vet.","exTr":"Hayalimdeki meslek veteriner olmak."},{"w":"vet","ipa":"/vet/","pos":"🐶","tr":"veteriner","ex":"I want to be a vet.","exTr":"Veteriner olmak istiyorum."},{"w":"teacher","ipa":"/ˈtiːtʃə/","pos":"👩‍🏫","tr":"öğretmen","ex":"My teacher is kind.","exTr":"Öğretmenim nazik."},{"w":"pilot","ipa":"/ˈpaɪlət/","pos":"✈️","tr":"pilot","ex":"Leo wants to be a pilot.","exTr":"Leo pilot olmak istiyor."},{"w":"astronaut","ipa":"/ˈæstrənɔːt/","pos":"🧑‍🚀","tr":"astronot","ex":"An astronaut sees the stars up close.","exTr":"Bir astronot yıldızları yakından görür."},{"w":"chef","ipa":"/ʃef/","pos":"👨‍🍳","tr":"şef","ex":"The chef makes pizza.","exTr":"Şef pizza yapıyor."},{"w":"cook","ipa":"/kʊk/","pos":"🍳","tr":"pişirmek, yemek yapmak","ex":"I want to cook for my family.","exTr":"Ailem için yemek yapmak istiyorum."},{"w":"study","ipa":"/ˈstʌdi/","pos":"📚","tr":"çalışmak, ders çalışmak","ex":"I need to study every day.","exTr":"Her gün çalışmam gerekiyor."}],"chunks":[{"en":"I want to be a…","tr":"… olmak istiyorum."},{"en":"What do you want to be?","tr":"Ne olmak istiyorsun?"},{"en":"That's a big dream!","tr":"Bu büyük bir hayal!"},{"en":"Keep working on it.","tr":"Üzerinde çalışmaya devam et."}],"grammar":{"point":"Want to + verb","tr":"Bir şeyi yapmak ya da olmak istediğini anlatmak için 'want to' ve fiilin yalın hâli kullanılır. Türkçedeki '-mak, -mek istiyorum' karşılığına gelir. 'He' ve 'she' için 'wants to' olur.","examples":["I want to be a pilot.","She wants to be a vet.","Ali wants to cook pizza.","Do you want to be an astronaut?"]},"questions":[{"q":"What does Ece want to be?","a":"A vet."},{"q":"What does Ali want to cook?","a":"Pizza."},{"q":"What does Leo need to study?","a":"Science and maths."}],"quiz":[{"q":"I ___ be a pilot.","o":["want to","wants to","wanting to"],"a":0,"why":"'I' ile 'want to' kullanılır."},{"q":"She ___ to be a vet.","o":["want to","wants to","wanted to"],"a":1,"why":"Üçüncü tekil kişide 'wants' olur."},{"q":"What do you ___ to be?","o":["want","wants","wanting"],"a":0,"why":"Soruda 'do' ile 'want' kullanılır."},{"q":"Ali ___ to cook pizza.","o":["wanting","want","wants"],"a":2,"why":"Ali üçüncü tekil kişidir, bu yüzden 'wants' gerekir."}],"drills":[{"type":"Yerine koyma","prompt":"I want to be a pilot.","cue":"astronaut","answer":"I want to be an astronaut."},{"type":"Dönüştürme","prompt":"Ali wants to be a chef.","cue":"Use 'I'","answer":"I want to be a chef."},{"type":"Soru yap","prompt":"Mia wants to be a teacher.","cue":"What…?","answer":"What does Mia want to be?"}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Kısa /ɪ/ sesi Türkçedeki 'i' sesine benzer ama daha kısa ve gevşektir. Uzun /iː/ sesinde ise dudaklarını iyice gererek sesi uzatırsın.","pairs":["ship / sheep","sit / seat","bin / been"]}],"mission":{"brief":"Claude, sınıfın yeni arkadaşı Leo olacak. Leo'ya hayalindeki mesleği sor, neden o mesleği istediğini öğren ve ona bu hayale ulaşmak için bir adım öner.","persona":"Leo, a curious 10-year-old boy. He says he wants to be a pilot, but his real dream is to be a horse vet. His hidden fact is that he only admits this after the learner asks him a good 'why' question about his dream.","goal":"Leo'nun gerçek hayalini öğren ve 'I want to…' kalıbıyla ona bir öneri yap.","opener":"Hi! I'm Leo. I want to be a pilot. What about you?"}},"KS2-026":{"objectives":["Müzik aletlerinin adlarını İngilizce söylemek","'Can' ile neler yapabildiğini anlatmak","Kısa bir şarkıyı ritimle tekrar etmek"],"dialogues":[{"title":"In the music room","setting":"Okulun müzik odasında Mia ve Ali bir gitar ile davula bakıyor.","lines":[{"s":"Mia","en":"Look! What is that?","tr":"Bak! Bu ne?"},{"s":"Ali","en":"It's a guitar. I play it at home.","tr":"Bu bir gitar. Onu evde çalıyorum."},{"s":"Mia","en":"Can you play a song?","tr":"Bir şarkı çalabilir misin?"},{"s":"Ali","en":"Yes! Listen. Ta-ta-ta!","tr":"Evet! Dinle. Ta-ta-ta!"},{"s":"Mia","en":"Wow, it's loud! I like the drums.","tr":"Vay, çok gürültülü! Davulu seviyorum."},{"s":"Ali","en":"Do you play an instrument?","tr":"Sen bir enstrüman çalıyor musun?"},{"s":"Mia","en":"No, but I can sing well.","tr":"Hayır, ama güzel şarkı söyleyebilirim."}]},{"title":"Concert day","setting":"Öğretmen okul konseri için sınıfa haber veriyor.","lines":[{"s":"Teacher","en":"Children, we have a school concert on Friday!","tr":"Çocuklar, cuma günü okul konserimiz var!"},{"s":"Ali","en":"Can I play the piano?","tr":"Piyano çalabilir miyim?"},{"s":"Teacher","en":"Yes, you can. Mia, can you sing?","tr":"Evet, çalabilirsin. Mia, şarkı söyleyebilir misin?"},{"s":"Mia","en":"Yes, I can! I love singing.","tr":"Evet, söyleyebilirim! Şarkı söylemeyi seviyorum."},{"s":"Teacher","en":"Great! Let's practise after lunch.","tr":"Harika! Öğle yemeğinden sonra prova yapalım."},{"s":"Ali","en":"Okay, Teacher!","tr":"Tamam, öğretmenim!"}]},{"title":"Drum and guitar chant","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Drum, drum, boom, boom!","tr":"Davul, davul, bum, bum!"},{"s":"Kids","en":"Drum, drum, boom, boom!","tr":"Davul, davul, bum, bum!"},{"s":"Teacher","en":"Guitar, guitar, ping, ping!","tr":"Gitar, gitar, ting, ting!"},{"s":"Kids","en":"Guitar, guitar, ping, ping!","tr":"Gitar, gitar, ting, ting!"},{"s":"Teacher","en":"Sing, sing, we all sing!","tr":"Şarkı söyle, şarkı söyle, hepimiz söyleyelim!"},{"s":"Kids","en":"Sing, sing, we all sing!","tr":"Şarkı söyle, şarkı söyle, hepimiz söyleyelim!"}]}],"reading":{"title":"Mia's music day","paras":[{"en":"Mia loves music very much. She has a small red drum in her room. Her older brother, Can, plays the guitar. On Saturday, they make a band in the garden. Mia plays the drum and Can sings a funny song. Their dad claps his hands. Their mum dances. Everybody laughs. Music makes us happy!","tr":"Mia müziği çok sever. Odasında küçük kırmızı bir davulu var. Ağabeyi Can gitar çalar. Cumartesi günü bahçede bir grup kuruyorlar. Mia davulu çalar, Can da komik bir şarkı söyler. Babası ellerini çırpar. Annesi dans eder. Herkes güler. Müzik bizi mutlu eder!"}]},"vocab":[{"w":"drum","ipa":"/drʌm/","pos":"🥁","tr":"davul","ex":"I play the drum.","exTr":"Davul çalıyorum."},{"w":"guitar","ipa":"/ɡɪˈtɑː/","pos":"🎸","tr":"gitar","ex":"My brother has a guitar.","exTr":"Ağabeyimin bir gitarı var."},{"w":"piano","ipa":"/piˈænəʊ/","pos":"🎹","tr":"piyano","ex":"Can I play the piano?","exTr":"Piyano çalabilir miyim?"},{"w":"sing","ipa":"/sɪŋ/","pos":"🎤","tr":"şarkı söylemek","ex":"I can sing well.","exTr":"Şarkıyı güzel söyleyebilirim."},{"w":"band","ipa":"/bænd/","pos":"🎺","tr":"grup, müzik grubu","ex":"We make a band.","exTr":"Bir grup kuruyoruz."},{"w":"concert","ipa":"/ˈkɒnsət/","pos":"🎉","tr":"konser","ex":"The concert is on Friday.","exTr":"Konser cuma günü."},{"w":"clap","ipa":"/klæp/","pos":"👏","tr":"alkışlamak","ex":"Clap your hands!","exTr":"Ellerini çırp!"},{"w":"dance","ipa":"/dɑːns/","pos":"💃","tr":"dans etmek","ex":"Mum likes to dance.","exTr":"Annem dans etmeyi sever."}],"chunks":[{"en":"Can you play a song?","tr":"Bir şarkı çalabilir misin?"},{"en":"Let's practise after lunch.","tr":"Öğle yemeğinden sonra prova yapalım."},{"en":"I love singing.","tr":"Şarkı söylemeyi seviyorum."},{"en":"Yes, I can!","tr":"Evet, yapabilirim!"}],"grammar":{"point":"Can for ability","tr":"'Can' bir şeyi yapabildiğimizi ya da yapamadığımızı anlatır. Her özneyle aynı biçimde kullanılır; 'he can' denir, sonuna 's' eklenmez. Olumsuzu 'can't' ile yaparız.","examples":["I can play the guitar.","Can you sing?","She can dance well.","I can't play the piano."]},"questions":[{"q":"What does Mia have in her room?","a":"A small red drum."},{"q":"Who sings in the band?","a":"Can sings."},{"q":"What does Ali want to play at the concert?","a":"The piano."}],"quiz":[{"q":"🥁 is a…","o":["drum","guitar","piano"],"a":0,"why":""},{"q":"I can ___ the guitar.","o":["playing","play","plays"],"a":1,"why":"'Can' den sonra sade fiil gelir."},{"q":"Music makes us ___.","o":["sad","tired","happy"],"a":2,"why":""},{"q":"Ali asks, 'Can I play the ___?'","o":["piano","guitar","drum"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Can you play a song?","cue":"piano","answer":"Can you play the piano?"},{"type":"Genişletme","prompt":"I can sing.","cue":"+ very well","answer":"I can sing very well."},{"type":"Soru yap","prompt":"I can play the drum.","cue":"Can…?","answer":"Can you play the drum?"}],"sounds":[{"focus":"/ɪ/ – /iː/","tr":"Kısa ve gevşek /ɪ/ sesini 'i' gibi ama kısa tut; /iː/ sesini ise dudakları yayarak uzun uzat. 'Ship' ve 'sheep' kelimeleri Türkçedeki 'i' sesinde karışabilir.","pairs":["ship / sheep","sit / seat","fill / feel"]}],"mission":{"brief":"Okul konserinde hangi enstrümanı çalacağını arkadaşına anlat. Claude, arkadaşın Mia olacak; sana sorular soracak ve sen İngilizce cevap vereceksin.","persona":"Mia, a friendly 10-year-old who loves music and singing. Uses short sentences and asks one question at a time. Hidden fact: she has been secretly practising the flute at home, and she wants to play it at the concert, but she is too shy to say so unless asked good questions about what she would like to do.","goal":"Üç enstrümanı İngilizce tanıt ve Mia'nın konserde yapmak istediği gizli şeyi öğren.","opener":"Hi! Do you play an instrument? I think music is the best thing ever."}},"KS2-027":{"objectives":["Kayıp bir eşyayla ilgili basit ipuçlarını İngilizce tarif etmek","'Was' ve 'were' ile geçmişte nerede olduğunu anlatmak","Kısa bir gizem hikâyesini sırasıyla anlatmak"],"dialogues":[{"title":"Who took the cake?","setting":"Sınıftan bir kek kaybolmuş; Leo ve Maya ipuçlarına bakıyor.","lines":[{"s":"Leo","en":"The cake is gone! Where is it?","tr":"Kek yok! Nerede?"},{"s":"Maya","en":"Don't panic. Let's look for clues.","tr":"Panik yapma. İpuçlarına bakalım."},{"s":"Leo","en":"Look! Chocolate on the floor.","tr":"Bak! Yerde çikolata var."},{"s":"Maya","en":"Good clue! Who likes chocolate?","tr":"İyi bir ipucu! Çikolatayı kim sever?"},{"s":"Leo","en":"Tom likes chocolate. He is always hungry!","tr":"Tom çikolatayı sever. O her zaman aç!"},{"s":"Maya","en":"Was he in the room at lunch?","tr":"Öğle yemeğinde odada mıydı?"},{"s":"Leo","en":"Yes, he was. Let's ask him.","tr":"Evet, oradaydı. Ona soralım."}]},{"title":"Tom's story","setting":"Tom odaya gelip öğle yemeğindeki yerini anlatıyor.","lines":[{"s":"Tom","en":"I didn't take the cake. I was in the library.","tr":"Keki almadım. Kütüphanedeydim."},{"s":"Leo","en":"Were you alone?","tr":"Yalnız mıydın?"},{"s":"Tom","en":"No, my friend Sara was with me. She can tell you.","tr":"Hayır, arkadaşım Sara benimleydi. Sana anlatabilir."},{"s":"Maya","en":"Interesting. Where was the cake before?","tr":"İlginç. Kek daha önce neredeydi?"},{"s":"Tom","en":"On the table near the window.","tr":"Pencerenin yanındaki masada."},{"s":"Leo","en":"Then the window is open. Look at the footprints!","tr":"O zaman pencere açık. Ayak izlerine bak!"}]},{"title":"Case closed","setting":"Öğretmen son ipucuna dikkat çekiyor.","lines":[{"s":"Teacher","en":"Ah, I see the answer now. Look at the window again.","tr":"Ah, şimdi cevabı görüyorum. Pencereye bir daha bak."},{"s":"Leo","en":"Oh! There is a small dog outside!","tr":"Oh! Dışarıda küçük bir köpek var!"},{"s":"Teacher","en":"The dog ate the cake. Is that right?","tr":"Köpek keki yemiş. Doğru mu?"},{"s":"Maya","en":"Yes! Crumbs in the garden. Case closed!","tr":"Evet! Bahçede kırıntılar var. Dosya kapandı!"},{"s":"Tom","en":"Oops! I wanted cake too.","tr":"Ups! Ben de kek istemiştim."}]}],"reading":{"title":"The missing key","paras":[{"en":"Lily could not find her house key. She looked in her bag. She looked under the bed. Then she looked in the kitchen. The key was in the fridge! Her little brother had put it there to make a joke. Lily laughed. Next time, she will check the fridge first! Her brother was very proud of his trick.","tr":"Lily ev anahtarını bulamadı. Çantasına baktı. Yatağın altına baktı. Sonra mutfağa baktı. Anahtar buzdolabındaydı! Küçük erkek kardeşi bir şaka yapmak için onu oraya koymuştu. Lily güldü. Bir dahaki sefere önce buzdolabına bakacak! Erkek kardeşi hilesiyle çok gurur duydu."}]},"vocab":[{"w":"clue","ipa":"/kluː/","pos":"🔍","tr":"ipucu","ex":"Good clue!","exTr":"İyi bir ipucu!"},{"w":"missing","ipa":"/ˈmɪsɪŋ/","pos":"❓","tr":"kayıp","ex":"The key is missing.","exTr":"Anahtar kayıp."},{"w":"footprint","ipa":"/ˈfʊtprɪnt/","pos":"👣","tr":"ayak izi","ex":"I see footprints on the floor.","exTr":"Yerde ayak izleri görüyorum."},{"w":"crumbs","ipa":"/krʌmz/","pos":"🍪","tr":"kırıntılar","ex":"There are crumbs on the table.","exTr":"Masada kırıntılar var."},{"w":"key","ipa":"/kiː/","pos":"🔑","tr":"anahtar","ex":"Where is my key?","exTr":"Anahtarım nerede?"},{"w":"fridge","ipa":"/frɪdʒ/","pos":"🧊","tr":"buzdolabı","ex":"The juice is in the fridge.","exTr":"Meyve suyu buzdolabında."},{"w":"window","ipa":"/ˈwɪndəʊ/","pos":"🪟","tr":"pencere","ex":"Close the window, please.","exTr":"Lütfen pencereyi kapat."},{"w":"library","ipa":"/ˈlaɪbrəri/","pos":"📚","tr":"kütüphane","ex":"I read books in the library.","exTr":"Kütüphanede kitap okurum."}],"chunks":[{"en":"Let's look for clues.","tr":"İpuçlarına bakalım."},{"en":"Don't panic.","tr":"Panik yapma."},{"en":"Look at the footprints!","tr":"Ayak izlerine bak!"},{"en":"Case closed!","tr":"Dosya kapandı!"}],"grammar":{"point":"Was / were (past of be)","tr":"'Was' ve 'were' geçmişte bir yerde olduğumuzu ya da bir şeyin o zaman nasıl olduğunu anlatır. 'I, he, she, it' ile 'was', 'you, we, they' ile 'were' kullanılır. Soru yaparken fiili özneden önce getiririz.","examples":["I was in the library.","Were you alone?","The cake was on the table.","They were in the garden."]},"questions":[{"q":"Where was Tom at lunch?","a":"In the library."},{"q":"What did Leo find on the floor?","a":"Chocolate."},{"q":"Where was the missing key?","a":"In the fridge."}],"quiz":[{"q":"The cake was ___ the table.","o":["in","at","on"],"a":2,"why":"Masanın üstü için 'on' kullanılır."},{"q":"🔍 means…","o":["clue","key","crumb"],"a":0,"why":""},{"q":"Where ___ you at lunch?","o":["was","were","is"],"a":1,"why":"'You' ile 'were' kullanılır."},{"q":"Lily's key was ___ the fridge.","o":["in","on","at"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"I was in the library.","cue":"garden","answer":"I was in the garden."},{"type":"Soru yap","prompt":"They were at school.","cue":"Were…?","answer":"Were they at school?"},{"type":"Dönüştürme","prompt":"The key is in the fridge.","cue":"Geçmiş zaman: The key…","answer":"The key was in the fridge."}],"sounds":[{"focus":"/ʊ/ – /uː/","tr":"Kısa /ʊ/ sesini dudakları gevşek tutarak söyle; uzun /uː/ sesinde dudaklarını daha çok yuvarla. Türkçedeki 'u' ile 'ü' arasındaki farka dikkat et.","pairs":["look / Luke","foot / food","full / fool"]}],"mission":{"brief":"Okulda kaybolan bir oyuncak arabayı bulmalısın. Claude, dedektif arkadaşın Sam olacak; ipuçlarını ancak doğru İngilizce soruları sorarsan öğrenebilirsin.","persona":"Sam, a friendly 10-year-old detective partner. Uses short sentences and answers one thing at a time. Hidden fact: Sam borrowed the lost toy car and hid it under the bench because he wanted to play with it, and he only admits this if asked good questions about where he was and what he did after lunch.","goal":"Sam'e üç ipucu hakkında soru sor ve oyuncak arabanın nerede olduğunu öğren.","opener":"Hi! I'm Sam. We have a missing toy car. Do you want to be my detective partner?"}},"KS2-028":{"objectives":["Bayramları ve kutlamaları İngilizce tanıtmak","'Like + -ing' kalıbıyla neyi sevdiğini söylemek","Kısa bir bayram şarkısını ritimle tekrar etmek"],"dialogues":[{"title":"Our festival","setting":"Sınıfta Jack ve Elif en sevdikleri bayramları anlatıyor.","lines":[{"s":"Jack","en":"What is your favourite festival, Elif?","tr":"Favori bayramın hangisi, Elif?"},{"s":"Elif","en":"We visit my grandma and eat lots of sweets!","tr":"Büyükannemi ziyaret ederiz ve bir sürü tatlı yeriz!"},{"s":"Jack","en":"Sweets! I like that. My favourite is Christmas.","tr":"Tatlı! Bunu sevdim. Benim favorim Noel."},{"s":"Elif","en":"Why?","tr":"Neden?"},{"s":"Jack","en":"We decorate a big tree and we open presents.","tr":"Büyük bir ağacı süsleriz ve hediyeleri açarız."},{"s":"Elif","en":"That sounds nice!","tr":"Kulağa hoş geliyor!"}]},{"title":"Festival of lights","setting":"Öğretmen sınıfa Hint bayramı Diwali'yi anlatıyor.","lines":[{"s":"Teacher","en":"Today we learn about Diwali. It is the festival of lights.","tr":"Bugün Diwali'yi öğreniyoruz. Işıklar bayramı."},{"s":"Ali","en":"Why are there lights?","tr":"Neden ışıklar var?"},{"s":"Teacher","en":"People light lamps to bring good luck into their homes.","tr":"İnsanlar evlerine iyi şans getirmek için lambalar yakar."},{"s":"Elif","en":"Can we make a lamp?","tr":"Bir lamba yapabilir miyiz?"},{"s":"Teacher","en":"Yes, we can! Let's use paper and paint.","tr":"Evet, yapabiliriz! Kağıt ve boya kullanalım."},{"s":"Ali","en":"Great. I love colours!","tr":"Harika. Renkleri çok severim!"}]},{"title":"Lantern chant","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Red lanterns, yellow lanterns, lights so bright!","tr":"Kırmızı fenerler, sarı fenerler, ışıklar çok parlak!"},{"s":"Kids","en":"Red lanterns, yellow lanterns, lights so bright!","tr":"Kırmızı fenerler, sarı fenerler, ışıklar çok parlak!"},{"s":"Teacher","en":"Dance, dance, every night!","tr":"Dans et, dans et, her gece!"},{"s":"Kids","en":"Dance, dance, every night!","tr":"Dans et, dans et, her gece!"},{"s":"Teacher","en":"Festival time is the best time!","tr":"Bayram zamanı en güzel zamandır!"},{"s":"Kids","en":"Festival time is the best time!","tr":"Bayram zamanı en güzel zamandır!"}]}],"reading":{"title":"Festivals around the world","paras":[{"en":"Every year, people all over the world celebrate festivals. In China, people dance with a big paper dragon. In India, Diwali is the festival of lights. In Mexico, families make colourful paper decorations. In Turkey, families celebrate Bayram with sweets and visits. Festivals make us happy and bring people together!","tr":"Dünyanın her yerinde insanlar her yıl bayramları kutlar. Çin'de insanlar büyük bir kağıt ejderhayla dans eder. Hindistan'da Diwali, ışıklar bayramıdır. Meksika'da aileler renkli kağıt süslemeler yapar. Türkiye'de aileler bayramı tatlılar ve ziyaretlerle kutlar. Bayramlar bizi mutlu eder ve insanları bir araya getirir!"}]},"vocab":[{"w":"festival","ipa":"/ˈfestɪvl/","pos":"🎉","tr":"bayram, festival","ex":"Diwali is a festival of lights.","exTr":"Diwali ışıklar festivalidir."},{"w":"lantern","ipa":"/ˈlæntən/","pos":"🏮","tr":"fener","ex":"The red lantern is very bright.","exTr":"Kırmızı fener çok parlak."},{"w":"sweets","ipa":"/swiːts/","pos":"🍬","tr":"şekerler, tatlılar","ex":"We eat sweets at the festival.","exTr":"Bayramda tatlı yeriz."},{"w":"decorate","ipa":"/ˈdekəreɪt/","pos":"🎀","tr":"süslemek","ex":"We decorate the room.","exTr":"Odayı süslüyoruz."},{"w":"dance","ipa":"/dɑːns/","pos":"💃","tr":"dans etmek","ex":"Let's dance together!","exTr":"Birlikte dans edelim!"},{"w":"present","ipa":"/ˈprezənt/","pos":"🎁","tr":"hediye","ex":"I open my present.","exTr":"Hediyemi açıyorum."},{"w":"celebrate","ipa":"/ˈselɪbreɪt/","pos":"🥳","tr":"kutlamak","ex":"We celebrate with our family.","exTr":"Ailemizle birlikte kutluyoruz."},{"w":"paint","ipa":"/peɪnt/","pos":"🎨","tr":"boyamak","ex":"I paint a red lamp.","exTr":"Kırmızı bir lamba boyuyorum."}],"chunks":[{"en":"What is your favourite festival?","tr":"Favori bayramın hangisi?"},{"en":"Let's make a lamp.","tr":"Bir lamba yapalım."},{"en":"That sounds nice!","tr":"Kulağa hoş geliyor!"},{"en":"Festival time is the best time!","tr":"Bayram zamanı en güzel zamandır!"}],"grammar":{"point":"Like + -ing","tr":"Bir şeyi sevdiğimizi anlatmak için 'like' kelimesinden sonra fiilin -ing hâlini kullanırız. Örneğin 'I like dancing' demek, dans etmeyi sevmek demektir. Soru yaparken 'Do' ya da 'Does' ile başlarız.","examples":["I like dancing at festivals.","She likes making lanterns.","We like eating sweets.","Do you like painting?"]},"questions":[{"q":"What does Elif eat at her festival?","a":"Lots of sweets."},{"q":"What do people light for Diwali?","a":"Lamps."},{"q":"Which festival does Jack like best?","a":"Christmas."}],"quiz":[{"q":"🎁 is a…","o":["paint","present","sweets"],"a":1,"why":""},{"q":"I like ___ at festivals.","o":["danced","dance","dancing"],"a":2,"why":"'Like' den sonra -ing hâli gelir."},{"q":"People ___ lamps for Diwali.","o":["light","lighting","lights"],"a":0,"why":"Çoğul öznede fiil -s almaz."},{"q":"Jack's favourite festival is…","o":["Bayram","Christmas","Diwali"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"We eat lots of sweets.","cue":"make lanterns","answer":"We make lanterns."},{"type":"Soru yap","prompt":"She likes dancing.","cue":"Does…?","answer":"Does she like dancing?"},{"type":"Genişletme","prompt":"I like painting.","cue":"+ at the festival","answer":"I like painting at the festival."}],"sounds":[{"focus":"/æ/ – /e/","tr":"/æ/ sesinde ağzını geniş aç ve 'e' ile 'a' arasında bir ses çıkar; /e/ sesi ise daha kısa ve dar. Türkçede bu ayrım yok, bu yüzden iki kelimeyi kolayca karıştırabilirsin.","pairs":["bet / bat","pen / pan","men / man"]}],"mission":{"brief":"İngiliz arkadaşın Lucy, Türkiye'deki en sevdiğin bayramı merak ediyor. Ona üç şey anlat ve onun en sevdiği bayramı öğren. Claude, Lucy olacak ve sorularını sana yöneltecek.","persona":"Lucy, a 10-year-old from London who loves festivals. Uses short sentences and asks one question at a time. Hidden fact: Lucy's real favourite is Bonfire Night, because she loves the fireworks, but she only says so when asked what she enjoys most at festivals.","goal":"Lucy'nin en sevdiği bayramı ve nedenini İngilizce öğren.","opener":"Hi! I'm Lucy. What is your favourite festival?"}},"KS2-029":{"objectives":["Nazik davranışları İngilizce anlatmak","Emir kipiyle birine yardım teklif etmek ya da bir şey istemek","Kısa bir nezaket şarkısını ritimle tekrar etmek"],"dialogues":[{"title":"Showing the new girl around","setting":"Teneffüste Mia, yeni gelen Sam'e okulun yerlerini gösteriyor.","lines":[{"s":"Sam","en":"Hi. I'm new. Where is the library?","tr":"Merhaba. Yeniyim. Kütüphane nerede?"},{"s":"Mia","en":"Come with me. I'll show you.","tr":"Benimle gel. Sana göstereyim."},{"s":"Sam","en":"Thanks! You are very kind.","tr":"Teşekkürler! Çok naziksin."},{"s":"Mia","en":"It's okay. Everyone was new once.","tr":"Sorun yok. Herkes bir zamanlar yeni olmuştu."},{"s":"Sam","en":"Can I sit with you at lunch?","tr":"Öğle yemeğinde yanında oturabilir miyim?"},{"s":"Mia","en":"Of course! Sit here.","tr":"Tabii ki! Buraya otur."}]},{"title":"A kind word","setting":"Ben, arkadaşı Lina'nın üzgün olduğunu fark ediyor.","lines":[{"s":"Lina","en":"I dropped my paints. Now my picture is ruined.","tr":"Boyalarımı düşürdüm. Şimdi resmim mahvoldu."},{"s":"Ben","en":"Oh no! Do you want some of my paints?","tr":"Ah, olamaz! Benim boyalarımdan ister misin?"},{"s":"Lina","en":"Really? Thank you, Ben!","tr":"Gerçekten mi? Teşekkürler, Ben!"},{"s":"Ben","en":"Your picture is great. The sky is so blue.","tr":"Resmin harika. Gökyüzü çok mavi."},{"s":"Lina","en":"You are kind. I feel better now.","tr":"Sen çok iyisin. Şimdi kendimi daha iyi hissediyorum."},{"s":"Ben","en":"Good. Let's paint together!","tr":"İyi. Birlikte boyayalım!"}]},{"title":"Kindness song","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Share, share, be kind to all!","tr":"Paylaş, paylaş, herkese nazik ol!"},{"s":"Kids","en":"Share, share, be kind to all!","tr":"Paylaş, paylaş, herkese nazik ol!"},{"s":"Teacher","en":"Help a friend when they fall!","tr":"Bir arkadaş düştüğünde ona yardım et!"},{"s":"Kids","en":"Help a friend when they fall!","tr":"Bir arkadaş düştüğünde ona yardım et!"},{"s":"Teacher","en":"Kindness makes the whole class strong!","tr":"Nezaket bütün sınıfı güçlü yapar!"},{"s":"Kids","en":"Kindness makes the whole class strong!","tr":"Nezaket bütün sınıfı güçlü yapar!"}]}],"reading":{"title":"A kind class","paras":[{"en":"In Mia's class, everyone is kind. When a new boy arrives, the children show him the school. When Lina is sad, her friends draw her a card. Ben shares his crayons every day. Kindness is free, and it makes everybody feel good. Can you be kind today? Small acts count a lot!","tr":"Mia'nın sınıfında herkes naziktir. Yeni bir çocuk geldiğinde, arkadaşları ona okulu gösterir. Lina üzgün olduğunda, arkadaşları ona bir kart çizer. Ben her gün boya kalemlerini paylaşır. Nezaket parasızdır ve herkesi iyi hissettirir. Bugün sen nazik olabilir misin? Küçük şeyler çok önemlidir!"}]},"vocab":[{"w":"kind","ipa":"/kaɪnd/","pos":"🤗","tr":"nazik","ex":"Mia is very kind.","exTr":"Mia çok nazik."},{"w":"share","ipa":"/ʃeə/","pos":"🤝","tr":"paylaşmak","ex":"Please share your crayons.","exTr":"Lütfen boya kalemlerini paylaş."},{"w":"arrive","ipa":"/əˈraɪv/","pos":"🚌","tr":"gelmek, varmak","ex":"The new girl arrives today.","exTr":"Yeni kız bugün geliyor."},{"w":"sad","ipa":"/sæd/","pos":"😢","tr":"üzgün","ex":"Lina is sad.","exTr":"Lina üzgün."},{"w":"card","ipa":"/kɑːd/","pos":"💌","tr":"kart","ex":"She made a birthday card.","exTr":"Doğum günü kartı yaptı."},{"w":"crayon","ipa":"/ˈkreɪɒn/","pos":"🖍️","tr":"boya kalemi, mum boya","ex":"I need a red crayon.","exTr":"Kırmızı bir boya kalemine ihtiyacım var."},{"w":"help","ipa":"/help/","pos":"🙋","tr":"yardım etmek","ex":"Can you help me?","exTr":"Bana yardım eder misin?"},{"w":"feel","ipa":"/fiːl/","pos":"💗","tr":"hissetmek","ex":"I feel happy today.","exTr":"Bugün kendimi mutlu hissediyorum."}],"chunks":[{"en":"Come with me.","tr":"Benimle gel."},{"en":"Can I sit with you?","tr":"Yanında oturabilir miyim?"},{"en":"You are very kind.","tr":"Çok naziksin."},{"en":"Let's paint together!","tr":"Birlikte boyayalım!"}],"grammar":{"point":"Imperative (commands)","tr":"Birine bir şey yapmasını söylerken fiilin sade hâlini kullanırız; 'to' eklenmez. Kibar olmak için cümlenin başına ya da sonuna 'please' ekleyebiliriz. Olumsuz emirlerde 'Don't' kullanılır.","examples":["Come with me.","Share your crayons, please.","Don't be sad.","Look at the picture!"]},"questions":[{"q":"Why is Lina sad?","a":"Because her picture is ruined."},{"q":"What does Ben give Lina?","a":"Some of his paints."},{"q":"What does Mia do for Sam?","a":"She shows him the library."}],"quiz":[{"q":"Lina is ___ after she drops her paints.","o":["happy","sad","angry"],"a":1,"why":""},{"q":"🤗 means…","o":["kind","cold","loud"],"a":0,"why":""},{"q":"___ with me.","o":["Coming","Come","Comes"],"a":1,"why":"Emir cümlesinde fiil sade hâlde olur."},{"q":"Please ___ your crayons.","o":["sharing","shares","share"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Come with me.","cue":"sit","answer":"Sit with me."},{"type":"Dönüştürme","prompt":"You are sad.","cue":"Olumsuz emir: Don't…","answer":"Don't be sad."},{"type":"Soru yap","prompt":"I'm sure Ben shares his crayons every day.","cue":"Does…?","answer":"Does Ben share his crayons every day?"}],"sounds":[{"focus":"/ɜː/","tr":"Dilini ağzının ortasında tut, dudaklarını hafifçe yuvarla ve 'ır' tınısıyla uzat. Türkçedeki 'ö' sesine benzetme; dil daha geride ve daha gergin olmalı.","pairs":["shirt / short","bird / bed","learn / lean"]}],"mission":{"brief":"Yeni gelen bir arkadaşının ilk gününü kolaylaştırmalısın. Claude, yeni öğrenci Ada olacak; ona nazikçe yardım et ve Ada'nın neleri sevdiğini öğren.","persona":"Ada, a shy new student from Manchester who sounds a little nervous. Uses short sentences. Hidden fact: she loves drawing horses and would love to join the art club, but she is too shy to say it unless you ask what she likes doing after school.","goal":"Ada'nın sevdiği bir şeyi öğren ve onu bir etkinliğe davet et.","opener":"Hi. I'm new here. Is this the right class?"}},"KS2-030":{"objectives":["Birlikte bir plan yapmak için öneri cümleleri kurmak","Telefonda buluşma saati ve yeri konuşmak","Kısa bir plan şarkısını ritimle tekrar etmek"],"dialogues":[{"title":"Saturday plans","setting":"Elif, arkadaşı Ahmet'i cumartesi günü parka davet ediyor.","lines":[{"s":"Elif","en":"Do you want to go to the park on Saturday?","tr":"Cumartesi parka gitmek ister misin?"},{"s":"Ahmet","en":"Yes, that sounds fun! What time?","tr":"Evet, kulağa eğlenceli geliyor! Saat kaçta?"},{"s":"Elif","en":"How about two o'clock?","tr":"Saat ikiye ne dersin?"},{"s":"Ahmet","en":"Sorry, I can't. I have piano lessons at two.","tr":"Üzgünüm, olmaz. İkide piyano dersim var."},{"s":"Elif","en":"No problem. Let's go at four then.","tr":"Sorun değil. O zaman dörtte gidelim."},{"s":"Ahmet","en":"Great! See you at the gate.","tr":"Harika! Kapıda görüşürüz."}]},{"title":"Phone call about the cinema","setting":"Elif, arkadaşı Zeynep'le telefonda sinemada buluşmayı konuşuyor.","lines":[{"s":"Zeynep","en":"Hi Elif! Shall we meet at the cinema?","tr":"Selam Elif! Sinemada buluşalım mı?"},{"s":"Elif","en":"Good idea. Which film do you want to watch?","tr":"İyi fikir. Hangi filmi izlemek istersin?"},{"s":"Zeynep","en":"A funny animal film. It starts at five.","tr":"Komik bir hayvan filmi. Beşte başlıyor."},{"s":"Elif","en":"Perfect. Can we have a snack before?","tr":"Harika. Önce bir şeyler atıştırabilir miyiz?"},{"s":"Zeynep","en":"Yes, let's get popcorn together.","tr":"Evet, birlikte patlamış mısır alalım."},{"s":"Elif","en":"I'll bring some money. See you soon!","tr":"Biraz para getiririm. Yakında görüşürüz!"}]},{"title":"Meeting chant","setting":"Ritimle tekrar et, alkışla!","lines":[{"s":"Teacher","en":"Let's meet at ten, let's meet at ten!","tr":"Saat onda buluşalım, saat onda buluşalım!"},{"s":"Kids","en":"Let's meet at ten, let's meet at ten!","tr":"Saat onda buluşalım, saat onda buluşalım!"},{"s":"Teacher","en":"Bring a ball and bring a pen!","tr":"Bir top ve bir kalem getirin!"},{"s":"Kids","en":"Bring a ball and bring a pen!","tr":"Bir top ve bir kalem getirin!"},{"s":"Teacher","en":"Friends and fun, that's what we need!","tr":"Arkadaşlık ve eğlence, ihtiyacımız olan bu!"},{"s":"Kids","en":"Friends and fun, that's what we need!","tr":"Arkadaşlık ve eğlence, ihtiyacımız olan bu!"}]}],"reading":{"title":"A plan for Sunday","paras":[{"en":"On Sunday, Ada wants to meet her friends. First, they will play football in the park. Then they will have lunch at Ada's house. In the afternoon, they will paint pictures together. Ada asks everyone to bring a snack. Her friend Ben can't come until three, so they will start without him. Plans are fun when everyone is ready!","tr":"Pazar günü Ada arkadaşlarıyla buluşmak istiyor. Önce parkta birlikte futbol oynayacaklar. Sonra Ada'nın evinde öğle yemeği yiyecekler. Öğleden sonra birlikte resim yapacaklar. Ada herkesten bir atıştırmalık getirmesini istiyor. Arkadaşı Ben üçe kadar gelemez, bu yüzden onsuz başlayacaklar. Planlar herkes hazır olduğunda eğlenceli olur!"}]},"vocab":[{"w":"meet","ipa":"/miːt/","pos":"🤝","tr":"buluşmak","ex":"Let's meet at the park.","exTr":"Parkta buluşalım."},{"w":"plan","ipa":"/plæn/","pos":"📝","tr":"plan","ex":"We have a good plan.","exTr":"İyi bir planımız var."},{"w":"snack","ipa":"/snæk/","pos":"🍪","tr":"atıştırmalık","ex":"I want a snack after school.","exTr":"Okuldan sonra bir atıştırmalık istiyorum."},{"w":"bring","ipa":"/brɪŋ/","pos":"🎒","tr":"getirmek","ex":"Please bring a pen.","exTr":"Lütfen bir kalem getir."},{"w":"cinema","ipa":"/ˈsɪnəmə/","pos":"🎬","tr":"sinema","ex":"We watch films at the cinema.","exTr":"Sinemada film izleriz."},{"w":"popcorn","ipa":"/ˈpɒpkɔːn/","pos":"🍿","tr":"patlamış mısır","ex":"I love popcorn.","exTr":"Patlamış mısırı çok severim."},{"w":"gate","ipa":"/ɡeɪt/","pos":"🚪","tr":"kapı (bahçe kapısı)","ex":"Wait at the gate.","exTr":"Kapıda bekle."},{"w":"afternoon","ipa":"/ˌɑːftəˈnuːn/","pos":"☀️","tr":"öğleden sonra","ex":"We play in the afternoon.","exTr":"Öğleden sonra oynarız."}],"chunks":[{"en":"Do you want to…?","tr":"…yapmak ister misin?"},{"en":"How about two o'clock?","tr":"Saat ikiye ne dersin?"},{"en":"Sorry, I can't.","tr":"Üzgünüm, olmaz."},{"en":"See you at the gate!","tr":"Kapıda görüşürüz!"}],"grammar":{"point":"Making suggestions: Let's, Shall we, How about","tr":"Birine bir şey önerirken 'Let's' ve 'Shall we' kalıplarından sonra fiilin sade hâli gelir. 'How about' ise bir isim ya da fiilin -ing hâlini alır. Bu kalıplar arkadaşlarla plan yaparken çok işe yarar.","examples":["Let's meet at the park.","Shall we go to the cinema?","How about two o'clock?","How about playing football?"]},"questions":[{"q":"What time does Ahmet have piano lessons?","a":"At two."},{"q":"What film do Elif and Zeynep want to watch?","a":"A funny animal film."},{"q":"Who can't come until three?","a":"Ben."}],"quiz":[{"q":"'Shall we ___ at five?'","o":["meet","meets","meeting"],"a":0,"why":""},{"q":"🍿 is…","o":["cinema","snack","popcorn"],"a":2,"why":""},{"q":"Sorry, I ___ come.","o":["can't","am","have"],"a":0,"why":"'Can't' bir şeyi yapamadığını anlatır."},{"q":"'How about two o'clock?' means…","o":["What time is it?","Is two o'clock good for you?","Two o'clock is too late."],"a":1,"why":"Bu kalıp bir öneri sorar."}],"drills":[{"type":"Yerine koyma","prompt":"Let's meet at the park.","cue":"the cinema","answer":"Let's meet at the cinema."},{"type":"Dönüştürme","prompt":"Let's play football.","cue":"Shall we…?","answer":"Shall we play football?"},{"type":"Genişletme","prompt":"Bring a snack.","cue":"+ on Saturday","answer":"Bring a snack on Saturday."}],"sounds":[{"focus":"/ʃ/ – /tʃ/","tr":"/ʃ/ Türkçedeki 'ş' gibidir; dudaklarını hafif öne uzat. /tʃ/ ise önce 't' duyup sonra 'ş' gibi bırakılan 'ç' sesidir. Bu iki sesi karıştırma.","pairs":["ship / chip","shop / chop","sheep / cheap"]}],"mission":{"brief":"Bir arkadaşınla hafta sonu için ortak bir plan yapmalısın. Claude, arkadaşın Mert olacak; ne yapmak istediğini sorup iki farklı öneri üzerinde anlaşmaya çalışacaksın.","persona":"Mert, a 10-year-old who loves football but is often busy. Uses short sentences and answers one thing at a time. Hidden fact: he has a new bike and really wants to go cycling, but he only says so if asked what he prefers to do outside when the weather is nice.","goal":"Mert ile ortak bir gün, saat ve buluşma yeri belirle.","opener":"Hi! Do you want to do something on Saturday?"}}};